// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":138,"question":"أحيانًا يأتي بلاغٌ عاجلٌ عن وقوع حادث حريقٍ أو غرقٍ أو نحوهما يستدعي انتقال فرقة الدِّفاع المدني، ويكون الأفراد أثناء حدوث البلاغ يُؤدون الصلاة جماعةً، فما الحكم؟ وهل تُقطع الصلاة أو يستمرون في أدائها، ومن ثَمَّ أداؤها بعد نهاية المهمة؟","title":"حكم قطع الصلاة لتفادي الخطر أو إنقاذ نفس","answer":"الجواب: يجب تقديم الخطر، فإذا كان هناك خطر غرقٍ أو حريق؛ لا مانع من قطع الصلاة، بل قد يجب قطعها إذا كان يتحقق في الخطر، فتُقطع وتُقْضَى بعد ذلك، هذا هو الصواب، فالنبي ﷺ لما اشتدَّت الحربُ مع الأحزاب يوم الأحزاب أخَّر الظهر والعصر حتى صلاها بعد المغرب؛ لشدَّة الحرب، والصحابة يوم تُستر في قتال فارس لما اشتدَّت بهم الحرب أذان الفجر، وصار بعضُهم على أبواب البلد، وبعضهم على الأسوار؛ أخَّروا صلاة الفجر وصلوها ضُحًى.\nوالحريق مضرَّته عظيمة، والغرق كذلك، فإذا جاء الخبرُ أن الحريق حاصلٌ، وأن الغرق حاصلٌ، فليُبادر ولو بقطع الصلاة، أما إذا كان يُخشى أن يكون غريقًا، أو يُخشى، ما بعد صار شيء؛ يُكملوا الصلاة، أما إذا صار الخبرُ أنه وقع فالواجب البدار والمُسارعة إلى إنقاذ مَن أصابه ذلك، ولو أخَّر الصلاة، والحمد لله، فيُؤخِّر الصلاة.\nوالصلاة يجوز تأخيرها للضَّرورة، والضَّرورة تعني: في مصلحة المسلمين، لا في مصلحته هو، لا، فيجب أن يُصلي في الوقت، لكن تأخيرها لمصلحة المسلمين العامَّة الضَّرورية -كالحريق والقتال والغرق- فيجب أن تُقدم المصلحة العامَّة، ولا بأس أن يؤخر عن الوقت، أما مصلحته هو فلا، يجب أن يُصلي في الوقت ولا يُؤخِّر لأجل تجارته، أو حساب تجارته، أو غير ذلك من أموره في الدنيا.","link":"https://binbaz.org.sa/fatwas/3674/حكم-قطع-الصلاة-لتفادي-الخطر-او-انقاذ-نفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0130.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":239,"question":"ما رأي الشيخ في قضية التَّصوير؟ وما رأي الشيخ لو كان يُصور وهو لا يعلم؟","title":"ما الذي يُستثنى من التصوير المحرم؟","answer":"الجواب: أصل التصوير محرم، هذا الأصل في التَّصوير، قال ﷺ: أشد الناس عذابًا المُصورون، وقال عليه الصلاة والسلام: إنَّ أصحاب هذه الصور يُعذَّبون يوم القيامة ويُقال لهم: أحيوا ما خلقتُم.\nفالتصوير لا يجوز، لا للذكرى ولا لغير هذا من الشؤون التي ليس لها ضرورةٌ، أما للضَّرورة مثل: تصوير الإنسان عند الحاجة إلى الجنسية التابعية المعروفة، أو رخصة القيادة في السيارة، ما يُعطى إلا بذلك؛ فهذا يُعفى عنه للضَّرورة، فهو كالمُكْرَه، وهكذا ما يُصور من النَّدوات والمُحاضرات التي يُرجى فيها مزيدٌ من العلم والخير والفضل، هذا محلُّ نظرٍ، ولا أعلم مَن يمنع ذلك؛ لقصد نفع المسلمين، وإشاعة الخير بين المسلمين، ونشر الدعوة، هذا واقعٌ للمصلحة العامَّة.\nفإذا جاز للتابعية ورخصة القيادة والشهادة الغربية الضَّرورية؛ فالشيء الذي ينفع المجتمع وينفع المسلمين ويكون وسيلةً إلى هداية كثيرٍ من الناس وانتفاعهم هذا يكون أوْلى بالجواز؛ لهذا الغرض النبيل العظيم، ولهذا أقررناه في مجالس الرابطة، وفي مواضع كثيرةٍ لهذه المصلحة العظمى، وإن كنتُ لا أُحبُّ التَّصوير مطلقًا، ولا آذنه مطلقًا إلا للضَّرورة كما سمعنا، والضرورة أمرٌ يُحتاج إليه، وهكذا تصوير المجرمين ليُحْذَروا وليُمْسَكوا إذا وُجِدُوا، وما أشبه ذلك من الحاجات.","link":"https://binbaz.org.sa/fatwas/4117/ما-الذي-يستثنى-من-التصوير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0249.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":298,"question":"كيف يكون وضع الغُترة وأكمام الثوب في الصلاة؟ وما الدليل على ذلك؟ وهل يجب إسدال الغُترة في الصلاة؟ ومَن لم يفعل ذلك فما الحكم؟","title":"هل يجب إسدال الغُترة وأكمام الثوب في الصلاة","answer":"الجواب: المشروع للمؤمن إسدال كميه وعمامته وغُترته، كلها يتركها، لا يكفتها في الصلاة؛ فالنبي ﷺ قال: أُمرتُ بالسجود على سبعة أعظم، وألا أكُفَّ شعرًا، ولا ثوبًا، هكذا يقول ﷺ: أُمرتُ أن أسجد على سبعة أعظم، وألا أكُفَّ شعرًا، ولا ثوبًا، فالسنة أن تطرح كُمّيك، وتطرح العمامة أو الغُترة معك، لا تكف شيئًا.","link":"https://binbaz.org.sa/fatwas/4300/هل-يجب-اسدال-الغترة-واكمام-الثوب-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0347.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":310,"question":"أرسلوا إليَّ أناسًا مسلمين في بلاد الكفر، وهم في مدرسةٍ داخليةٍ، ولا يستطيعون أن يُصلّوا في أوقاتها خشية أن يروهم ويُفصلون من هذه المدرسة، أرجو من سماحتكم التَّفضل بالإجابة على هذا السؤال، وماذا يفعلون لكي نرد عليهم؟","title":"حكم من يخشى إظهار صلاته في بلد كُفر","answer":"الجواب: إذا كان المسلمون في بلاد الكفرة ويخشون إذا أظهروا صلاتهم أن يُعذَّبوا؛ جاز لهم أن يُصلوا في البيوت، أو في المدرسة، ولا حرج عليهم في ذلك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا أمِنُوا وجب عليهم إظهار الصلاة، وإذا لم يأمنوا صلوا في بيوتهم، وفي مدارسهم؛ حتى يُسهل الله لهم الهجرة والانتقال إلى بلاد المسلمين، فمتى استطاعوا الهجرة إلى بلدٍ يستطيعون فيها إظهار دينهم وجبت عليهم الهجرة، وما داموا عاجزين فعليهم تقوى الله، وإذا عجزوا عن الصلاة جهرةً صلوا في بيوتهم، وفي مدارسهم.","link":"https://binbaz.org.sa/fatwas/4313/حكم-من-يخشى-اظهار-صلاته-في-بلد-كفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0360.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":315,"question":"ما حكم وضع المناكير على الأظافر؟","title":"ما حكم وضع المناكير على الأظافر؟","answer":"الجواب: المناكير على اسمها، ما ينبغي فعلها؛ لأنها مُستوردة لهم، لا حاجة إليها، فالأوْلى تركها، والأحوط تركها؛ لأنَّ لها جسمًا، لها جرمًا يُغطِّي الأظافر، ويمنع الماء، لكن مَن فعلتها من النساء تُزيلها عند الوضوء، والحناء يكفي عنها.\nلكن الناس مفتونون بما يرد إليهم من الخارج، مفتونون فتنةً عمياء، وإلا فلا حاجة إلى المناكير، ويكفي عنها الحناء والحمد لله، لكن مَن وضعتها فعليها أن تُزيلها عند الوضوء، كلما توضَّأت تُزيلها عن أظفارها.\nس: وإذا وضعتها.....؟\nالشيخ: تُزيلها عند الوضوء الثاني.","link":"https://binbaz.org.sa/fatwas/4341/ما-حكم-وضع-المناكير-على-الاظافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0366.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":722,"question":"س: ما رأيكم في المجلات التي تُباع في الأسواق وعليها صورة نساء مُتبرجات فاتنات؟ وهل يجوز بيعها؟","title":"حكم بيع المجلات التي عليها صور نساء","answer":"الجواب: صور المجلات والصحف اليومية والأسبوعية كلها يجب أن تُمنع إذا كانت تشتمل على صور النساء؛ لأنها فتنة، وقد وجّه للدولة في ذلك، ولوزير الإعلام في ذلك ما يقتضي هذا، ونُبّه الجميع على وجوب حماية المسلمين من هذه المجلات والصَّحافة التي تنشر الرذائل والصور الخليعة، سواء في الغلاف أو في داخل المجلة، كل هذا منكرٌ لا يجوز.\nفالواجب على وزارة الإعلام وعلى الرقابة الدينية منع ذلك، وعلى الدولة -وفَّقها الله- منع ذلك، وليس لهم السَّماح بذلك؛ لأنَّ هذا يضرُّ المجتمع كثيرًا، فلا يجوز استيراد أي مجلةٍ ولا أي صحيفةٍ تكون فيها مقالات ضدّ الإسلام، أو صور خليعة، بل يجب منعها، أو قطع تلك الصور وإزالتها قبل الدخول، إما أن تُزال المقالات الضَّارة والصور الخليعة منها، أو تُمنع منعًا باتًّا، ولا يجوز استخدامها أبدًا، ولا يجوز للدولة ولا لوزارة الإعلام ولا للمُراقبين الدِّينيين التَّسامح في هذا الأمر، بل يجب عليهم أن يكونوا نشيطين وأقوياء في هذا الأمر؛ حمايةً للمجتمع الإسلامي في هذه البلاد من هذه البلايا والمحن التي تضرُّ المجتمع ضررًا كبيرًا.","link":"https://binbaz.org.sa/fatwas/20559/حكم-بيع-المجلات-التي-عليها-صور-نساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0517فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":740,"question":"توجد بعض الملابس عليها صور صغيرة، فما حكم الصلاة فيها؟","title":"حكم الصلاة بملابس عليها صور","answer":"الجواب: الملابس التي فيها صور لا يُصلَّى بها، ويُنهى عن الصلاة فيها، سواء كانت الصور كبيرة أو صغيرة، طيور صغيرة أو كبيرة، أو حيوانات أخرى، إلا إذا كانت في محلٍّ يُمتهن، إذا كانت في البُسُط والوسائد الممتهنة فلا بأس بذلك، أما أن يُلبس على الرجال أو النساء أو الأطفال، أو يُنصب في الجدران، أو يُعلّق على أي شيءٍ، هذا يُمنع؛ لأنَّ فيه إظهارًا للصور، والنبي ﷺ لما رأى سترًا عند عائشة فيه تصاوير هتكه وغضب وقال: إنَّ أصحاب هذه الصور يُعذَّبون يوم القيامة، ويُقال لهم: أحيوا ما خلقتم، قالت عائشة: فاتَّخذنا من ذلك الستر وسادتين يرتفق بهما النبيُّ ﷺ.\nوفي الحديث الصحيح أيضًا: أنَّ جبرائيل كان على موعدٍ مع النبي ﷺ، فتأخَّر عن ذلك، فسأله النبيُّ ﷺ عن التأخُّر فقال: إنَّ في البيت تمثالًا وسترًا فيه تصاوير وكلبًا، وقال له جبرائيل: مُرْ بالكلب أن يُخرج، وبالتمثال أن يُقطع رأسه، وبالستر أن يُقطع منه وسادتان منتبذتان تُوطآن، ففعل النبيُّ ﷺ، فدخل جبرائيل عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/20620/حكم-الصلاة-بملابس-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0551بعض الملابس عليها صور صغيرة فما حكم الصلاة فيها؟فتاوى المحاضرات.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":1420,"question":"من صلى بملابس فيها صور، هل صلاته صحيحة؟","title":"هل تصح صلاة من صلى بملابس فيها صور؟","answer":"الجواب:\nنعم، صحيحة، لأن هذا محرم في الصلاة وغيرها، ما هو خاص بالصلاة، نفس الصور مُحَرَّمة، والشيء العام لا يبطل الصلاة، وكذلك الصلاة في الأرض المغصوبة، وما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/21515/هل-تصح-صلاة-من-صلى-بملابس-فيها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة بملابس فيها صور.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":1460,"question":"بعض النساء في الصلاة تضع العباءة على الكتفين لتستر قدميها، هل هذا يكون من التَّشَبُّه؟","title":"حكم وضع عباءة المرأة على كتفيها بالصلاة؟","answer":"الجواب:\nما يجوز هذا، نعم، تجعل رداءً أو جلالًا أو غيره، لا تتشبَّه بالرجال.","link":"https://binbaz.org.sa/fatwas/21557/حكم-وضع-عباءة-المراة-على-كتفيها-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلاة المرأة.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":2446,"question":"وَصْلُ الصلاة بالصلاة مُحَرَّم؟","title":"ما حكم وَصْل الصلاة بالصلاة؟","answer":"الجواب:\nلا، ما يجوز؛ لأن الرسول ﷺ نهى عن هذا، مثل ما أخبر معاوية، كونه يُسَلِّم ويقوم ما يقول أستغفر الله ولا يذكر الله ولا يتكلم بشيء.\nس: إذا قام من المسجد قبل أن يُسَبِّح هل ممكن يرجع مرة ثانية أو يسبح؟\nالشيخ: لا حرج عليه، كلها نافلة.","link":"https://binbaz.org.sa/fatwas/22575/ما-حكم-وصل-الصلاة-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وصل الصلاة بالصلاة.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":2487,"question":"إذا صليت تحية المسجد وسلّمت على اليمين وعلى الشمال فيها محذور؟","title":"حكم التصافح بعد أداء تحية المسجد","answer":"الجواب:\nأفضل تصافحهم، أفضل تصافح الذي عن يمينك وعن شمالك.\nس: ما فيها محذور؟\nالشيخ: لا، سُنة.\nس: بعضهم يُنكر يقول ما دام أنه يقرأ القرآن دعه لا تُسَلِّم عليه؟\nالشيخ: لا، غلط، السُّنة إذا لقي المسلم إخوانه ولو في الصف يُسَلِّم عليهم ويصافحهم.\nس: أحد الدعاة قال: لا، ما تُسَلِّم عليهم؟\nالشيخ: غلط، هذا غلط، هذا جهل.","link":"https://binbaz.org.sa/fatwas/22617/حكم-التصافح-بعد-اداء-تحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مصافحة الناس بعد الصلاة.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":2651,"question":"وضع الدفايات في القبلة من شدة البرد؟","title":"ما حكم وضع الدفايات في القِبْلة لشدة البرد؟","answer":"الجواب: لو جعلوها يمين أو شمال أو خلف؛ يكون أحوْط عن التَّشَبُّه بعُبّاد النار من المجوس، لكن هذا ما هو مقصود إن شاء الله، لا حرج.","link":"https://binbaz.org.sa/fatwas/22787/ما-حكم-وضع-الدفايات-في-القبلة-لشدة-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع الدفايات في القبلة عند شدة البرد.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":2768,"question":"تقول إحدى الأخوات أهدي إليها ثوب وهذا الثوب فيه صليب، وصَلَّت وهي لابسة هذا الثوب، تقول: هل تعيد الصلاة أم لا شيء عليها؟","title":"ما حكم الصلاة في ثوب عليه صليب؟","answer":"الجواب: الصلاة صحيحة، لكن تترك هذا اللباس، أو يُحَكُّ الصليب أو تغسله بشيء.\nس: الثوب الذي فيه صليب يَحْرُم لبسه؟\nالشيخ: نعم، والصور كذلك وصور ذوات الأرواح، إلا إذا طمست؛ ما في بأس.\nس: بالنسبة للأطفال الصغار أيضًا؟\nالشيخ: حتى الأطفال؛ لأنه يُعَلَّق ويُحْفَظ.","link":"https://binbaz.org.sa/fatwas/22916/ما-حكم-الصلاة-في-ثوب-عليه-صليب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلى وكان على الثوب صليب.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":3094,"question":"من أصيب برِعاف يسير في الصلاة، هل يجب عليه قطع الصلاة؟","title":"حكم الرِّعاف والقيء اليسيران في الصلاة","answer":"الجواب: لا، يُعفى عنه، اليسير يُعفى عنه، الرِّعاف اليسير؛ الدم الذي في الأسنان أو في العين يُعفى عن اليسير.\nس: والقيء مثله؟\nالشيخ: والقيء اليسير يُعفى عن الشيء اليسير الذي ما يُسمّى \"قيء\"؛ لأن القيء لا بد من التكرار.\nس: \"طَرَشَ\" في الأرض وسّخ الذي بجانبه.\nالشيخ: سهل شيء يسير.\nس: شيء كثير؟\nالشيخ: الكثير يغسل ما أصابه.\nس: قيء الطفل الصغير نجس أيضًا؟\nالشيخ: مثل بَوْله.","link":"https://binbaz.org.sa/fatwas/23254/حكم-الرعاف-والقيء-اليسيران-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرعاف والقيء اليسير في الصلاة.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":3416,"question":"الأمر بالصلاة في النعال ما يدل على السُّنِّيَّة؟","title":"على ما يدل الأمر بالصلاة في النعال؟","answer":"الجواب: إذا كان لقصد مخالفة اليهود، وإذا فعله لأجل السُّنِّيَّة فلا بأس؛ أفضل من باب المخالفة. ولكن الآن بعد فرش المساجد قد يكون فيها ما يؤذي الناس، إذا جعلها عند الباب حتى لا يؤذي أحدًا، ولا يدنّس الفرش، ولا يُقَذِّر على المصلين، لعل هذا أحوط.\nس: بعضهم -عفا الله عنك- ينزعها حتى في البَرّ؟\nالشيخ: لا، إذا كان نظيفًا يصلى فيها أحسن، لكن غير النظيف قد تؤذي بالصلاة بها بعض الناس، وقد يتأذى بها.\nس: ألم تكن على السُّنِّيَّة؟\nالشيخ: هو الأقرب، النبي ﷺ قال: إن اليهود لا يصلون في نعالهم فخالفوهم المخالفة سنة.","link":"https://binbaz.org.sa/fatwas/23588/على-ما-يدل-الامر-بالصلاة-في-النعال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة في النعلين أو الخفين.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":3430,"question":"قد يبقى في فم الإنسان بقايا من قطع السواك صغيرة، فيقذف بها أمامه، يُنْهَِي عنه؟","title":"حكم التفل تجاه القبلة في الصلاة وغيرها","answer":"الجواب: الله أعلم..... عن يساره أفضل مطلقًا، ولكن الأحاديث جاءت في الصلاة، ولكن إذا جعلها عن يساره؛ لأن بعض الروايات إطلاق البعض، إذا جعلها عن يساره يكون حسن إن شاء الله، أحوط.\nس: ذكر الشارح عن ابن خزيمة من تفل تجاه القبلة جاء يوم القيامة تَفْلُه بين عينيه هذا في الصلاة؟\nالشيخ: هذا محتمل، وهذا مما يؤيد كونه يتفل عن يساره حسن، أما في الصلاة فيتعيّن مثل ما قال ﷺ: فلا يبصقن نهي، والأصل منه التحريم فلا يبصق أمامه في الصلاة أبدًا لا في النفل، ولا في الفرض، لا في المسجد، ولا في غيره. أما في خارج الصلاة فهذا محل نظر، الأمر فيه سهل، لكن إذا كان عن يساره حتى في خارج الصلاة يكون أكمل وأحوط.","link":"https://binbaz.org.sa/fatwas/23604/حكم-التفل-تجاه-القبلة-في-الصلاة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن التفل تجاه القبلة في الصلاة.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":3538,"question":"بعض الوُعّاظ يعبّر يقول: فرض الفجر هذا الفرض اليتيم يشتكي إلى الله من قلة رواده؟","title":"حكم مقولة \"فرض الفجر يتيم يشتكي إلى الله\"","answer":"الجواب: هذا كلام ما له أصل، الواجب أن يقول هذا الفرض كثير من الناس يتثاقلون عنه ويتشاغلون بالنوم، فالواجب تقوى الله، والحذر من مشابهة أهل النفاق، ونحوه من الكلام الطيب.  أما قوله (يشتكي إلى الله) قد يُخشى أن هذا كذب على الله، من قال لك هذا الكلام؟!\nس: يُنْكَر عليه.. الله يرضى عليك؟\nالشيخ: العبارة تَرْكُها أوْلى.","link":"https://binbaz.org.sa/fatwas/23720/حكم-مقولة-فرض-الفجر-يتيم-يشتكي-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على مقولة فرض الفجر يتيم يشتكي إلى الله من قلة رواده.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":3544,"question":"الصلاة في ثوب وفيه ذوات أرواح؟","title":"حكم الصلاة في ثوب به صور ذوات أرواح","answer":"الجواب: لا يجوز، وعليه إزالتها، وصلاته صحيحة.\nس: يعيد الصلاة؟ هل صلاته صحيحة؟\nالشيخ: صلاته صحيحة، وعليه التوبة.","link":"https://binbaz.org.sa/fatwas/23726/حكم-الصلاة-في-ثوب-به-صور-ذوات-ارواح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة في ثوب فيه ذوات أرواح.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":4536,"question":"مَن اعتنى بنعليه يُسنّ له أن يُصلي فيهما؟","title":"هل يُسنّ لمَن اعتنى بنعليه أن يُصلي فيهما؟","answer":"الجواب: إذا لم يكن هناك أذى ولا قذر ولا فتنة من توسيخ الفرش، لكن الآن تحصل به الفتنة وشيء من الشرور وتساهل من أكثر الناس في دخول المساجد بنعالهم وأخفافهم، فتكون فيه فتنة ونزاع وتقذير وأوساخ، وهذه قُصاراها أن تكون مستحبةً، فلا يُحافظ عليها مع وجود ما هو أشرّ منها، لا يُحافظ على شيء مستحبٍّ مع وجود ما يكون شرًّا على الجميع وتنفير الناس.\nس: في المقابل الآن نُسيت هذه السنة، وأصبح الناس يُنكرونها حتى في البَرِّ لو يُصلي أحدٌ بنعليه؟\nج: لا، في البر طيب، في بعض المساجد فيها التراب، ما فيه شيء إذا اعتنى بها وحثَّ إخوانه على العناية وحرّصهم على العناية... يعتنون، يُعلَّمون مثلما فعل النبيُّ ﷺ مع الصحابة.","link":"https://binbaz.org.sa/fatwas/24816/هل-يسن-لمن-اعتنى-بنعليه-ان-يصلي-فيهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُسنّ لمَن اعتنى بنعليه أن يُصلي فيهما.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":4586,"question":"الاضطجاع يكون في البيت فقط؟","title":"هل يجوز الاضطجاع قبل الفجر في المسجد؟","answer":"الجواب: نعم في البيت، ما هو في المسجد، كان النبيُّ يفعلها في البيت، وكان ابن عمر يحصبهم إذا رآهم مُضطجعين في المسجد، فليس من السنة الاضطجاع في المسجد.\nس: هل هو خاص بمن قام من الليل؟\nج: ليس خاصًّا، لا، سنة مطلقًا، ولو ما قام الليل.","link":"https://binbaz.org.sa/fatwas/24873/هل-يجوز-الاضطجاع-قبل-الفجر-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ثمّ اضطجع على شقه الأيمن...، أين يكون الاضطجاع.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":4723,"question":"الصلاة في مواطن الإبل؟","title":"ما حكم الصلاة في مواطن الإبل؟","answer":"لا يُصلَّى في مواطن الإبل، معاطن الإبل لا يُصلَّى فيها، الرسول نهى عن الصلاة في معاطن الإبل، يُصلَّى في مرابض الغنم.","link":"https://binbaz.org.sa/fatwas/25024/ما-حكم-الصلاة-في-مواطن-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة في مواطن الإبل.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":4933,"question":"ألا يجمع بين الروايات في صلاة الفجر أن الرسول ﷺ كان يدخل الصلاةَ بغلسٍ، وكان يُطول القراءة حتى يُسفر؟","title":"صفة صلاة النبي عليه الصلاة والسلام للفجر","answer":"الجواب: هذا عمل النبيِّ ﷺ، كان يغلّس ويُطوّل عليه الصلاة والسلام، ولهذا قال أبو برزة: \"كانوا ينفلتون حين يعرف الرجلُ جليسه\".","link":"https://binbaz.org.sa/fatwas/27027/صفة-صلاة-النبي-عليه-الصلاة-والسلام-للفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة صلاة النبي للفجر.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":5413,"question":"حديث أبي قتادة: إذا دخل أحدُكم المسجدَ فلا يجلس حتى يُصلي ركعتين الأمر للاستحباب أم للوجوب؟","title":"هل تحية المسجد واجبة أم مستحبة؟","answer":"الجواب: المشهور عند العلماء أنه للاستحباب؛ لقوله ﷺ لما سأله الأعرابي عن الصَّلوات الخمس: هل عليَّ غيرها؟ قال: لا، إلا أن تطوع، ولكن القول بالوجوب قولٌ قويٌّ؛ لأنَّ فيه الأمر: فليركع ركعتين، وفيه النهي فلا يجلس، فينبغي ألا يتساهل في هذا، فإذا دخل وهو طاهر؛ صلَّى ركعتين، ويحذر التَّساهل في هذا. س: إذا كان الأمرُ للاستحباب وأتى للمسجد في وقت نهيٍ يُصلي أم يجلس؟ ج: ولو في وقت نهيٍ، السنة أن يُصلي؛ لأنَّ الأمر عامّ، وهذه من ذوات الأسباب، مثل: صلاة الكسوف، فلو كسفت الشمسُ في العصر يُصليها على الصَّحيح. س: قول الرسول ﷺ للرجل عندما تخطَّى الرقابَ في المسجد يوم الجمعة، قال: اجلس، فقد آذيتَ وآنيتَ فلم يأمره بتحيَّة المسجد؟! ج: لعله قد صلاها، وهذا ما هو بصريح.[1]","link":"https://binbaz.org.sa/fatwas/31181/هل-تحية-المسجد-واجبة-ام-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 029.mp3","categories":["الأدعية والأذكار","شروح الحديث","مسائل متفرقة في الصلاة"]},{"id":5609,"question":"بماذا تنصحون مَن ابتُلي بكثرة الوساوس في الوضوء وفي الصلاة؟","title":"ما النصيحة للمُبتلي بالوساوس في الوضوء والصلاة؟","answer":"الجواب: يتعوّذ بالله من الشيطان، ننصحه بالتعوّذ بالله من الشيطان: قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ [الناس:1- 4]، وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ [الأعراف:200]، قال بعض الصحابة: يا رسول الله، إنَّ الشيطان قد لبس عليَّ صلاتي؟ وهو عثمان بن أبي العاص، فأمره النبي ﷺ قال: استعذ بالله من الشيطان ثلاث مرات، واتفل عن يسارك ثلاث مرات، قال عثمان: ففعلتُ ذلك فأذهب الله عني ما أجد. س: أفضل ما أُلِّف في ذلك؟ ج: ما أتذكر شيئًا، لكن \"إغاثة اللهفان\" طيب لابن القيم رحمه الله، \"إغاثة اللهفان من وساوس الشيطان\". س: ينفث في ذات الصلاة؟ ج: نعم في نفس الصلاة. س: يلتفت في نفس الصلاة وينفث؟ ج: نعم في نفس الصلاة عن يساره قليلًا.[1]","link":"https://binbaz.org.sa/fatwas/31576/ما-النصيحة-للمبتلي-بالوساوس-في-الوضوء-والصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 049.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":5611,"question":"الذي صلَّى بالثوب المغصوب هل يُؤمر بالإعادة؟","title":"هل يُؤمر بالإعادة مَن صلَّى بثوب مغصوب؟","answer":"الجواب: الأقرب -والله أعلم- لا يُؤمر بالإعادة على القاعدة، مثل: لو صلَّى متعمدًا في ثوبٍ نجسٍ. س: ما تكون الصلاة في الثوب المغصوب مثل الصلاة في الأرض المغصوبة؟ ج: الصلاة صحيحة، هذا الصواب، الأرض المغصوبة والثوب المغصوب: الصلاة صحيحة؛ لأنَّ النهي ما هو لأجل الصلاة، النهي من أجل الغصب، وهو عام للمُصلي وغير المصلي، بخلاف الشيء الذي يختص بالصلاة: كالنجاسة ونحوها. س: يعني ما يُؤمر بالإعادة؟ ج: لا يؤمر بالإعادة، وعليه أن يؤدي الحقَّ إلى أهله من أرضٍ أو ثوبٍ.[1]","link":"https://binbaz.org.sa/fatwas/31578/هل-يومر-بالاعادة-من-صلى-بثوب-مغصوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 051.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":5861,"question":"كثير من الناس يتلفظون بأقوال مثل قولهم: الله الله الله، وهذا ليس بكلام توحيد كما تعلمون، لكن ماذا تقولون في قوله سبحانه: قُلِ اللَّهُ ثُمَّ ذَرْهُمْ فِي خَوْضِهِمْ يَلْعَبُونَ [الأنعام: 91] ؟","title":"حكم ترديد الله الله، أو هو هو عند الأذكار","answer":"الجواب:  هذا من الصوفية، يقولون: الله الله الله، أو هو هو هو، هذا كلام باطل لا يجوز، هذا ليس بشرع، ولا ذكر، الله الله هذا من طرق الصوفية الذين أوجدوا عبادات، وأحدثوا عبادات ما لها أساس في الشرع.  فهؤلاء موجودون في بلاد كثيرة، في الشام، وفي مصر، وفي إفريقيا، وفي كل مكان ولهم أذكار خاصة أحدثوها، وطرق أحدثوها باطلة، لا ينبغي تقليدهم فيها، بل ينبغي أن ينصحوا، ويحذروا منها، فهم إن اجتمعوا ذكرهم هذا الله الله الله الله، أو هو هو هو، هذا منكر.   أما قوله -جل وعلا-: قُلِ اللَّهُ ثُمَّ ذَرْهُمْ فِي خَوْضِهِمْ يَلْعَبُونَ [الأنعام:91] فهذا تابع لما قبله، يعني الله الذي أنزل، خبره محذوف، مبتدأ خبره محذوف، مثل لو قلت: من الذي خلقك؟ تقول: الله، أي الله الذي خلقك، هذا كلام معروف، أو قلت: من يحيي الموتى؟ فتقول: الله، من فعل كذا وكذا؟ من أنزل التوراة، ومن أنزل الإنجيل؟ الله، هذا كلام تام. والقاعدة: أن الخبر يحذف إذا وجد ما يدل عليه، فإذا قال لك إنسان: من الذي قام؟ تقول: زيد يعني قام زيد، حذف الفعل؛ لأن هناك ما يدل عليه.","link":"https://binbaz.org.sa/fatwas/1184/حكم-ترديد-الله-الله-او-هو-هو-عند-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_180.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":6011,"question":"ياشيخ، رفع اليدين بعد الفريضة، والدعاء ياشيخ بعد الفريضة؟","title":"حكم رفع اليدين بالدعاء بعد الصلاة","answer":"الجواب: رفع اليدين بعد الفريضة للدعاء بدعة، من يرفع يديه بعد الفريضة، ويدعو الإمام، أو المأمومين، ما له أصل، هذا بدعة، أما النافلة إذا فعله بعض الأحيان . السؤال: لا بعد الفريضة؟ الجواب: هذا ما يجوز؛ لأنه بدعة بعد الفريضة.","link":"https://binbaz.org.sa/fatwas/1389/حكم-رفع-اليدين-بالدعاء-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_345.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":6032,"question":"ما حكم رفع اليدين بعد الفرائض، والسنن، والدعاء، والمسح بهما على الوجه؟","title":"حكم رفع اليدين بالدعاء عقب الصلوات ومسح الوجه بهما","answer":"الجواب: أما رفع اليدين بعد الفرائض ما له أصل، بدعة ما كان النبي يفعله، ولا أصحابه إذا سلموا من الفرائض. وأما بعد السنن فإذا فعله في بعض الأحيان؛ فالأمر سهل؛ لأن رفع اليدين من أسباب الإجابة، لكن لا يواظب عليه بعد كل سنة، وأما مسح الوجه فقد جاء به أحاديث فيها ضعف، والأولى عدمه، الأحاديث الصحيحة ليس فيها المسح بعد الدعاء، لكن جاء فيه أحاديث فيها ضعف. قال بعض أهل العلم: إنها مجتمعة تكون حسنة، ولكن الأحاديث الصريحة ليس فيها مسح الوجه، فالأولى ترك المسح، إذا دعا؛ يكفي، وإذا مسح بعض الأحيان؛ فالأمر سهل، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/1436/حكم-رفع-اليدين-بالدعاء-عقب-الصلوات-ومسح-الوجه-بهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_373.mp3","categories":["مسائل متفرقة في الصلاة","الأدعية والأذكار"]},{"id":7282,"question":"الحكم في قطع الصلاة بالنسبة للكل، سواء كانت امرأة، أو رجلًا؟","title":"حكم قطع الصلاة للضرورة","answer":"الجواب:\n\nإذا دعت الحاجة نعم، إذا دعت الحاجة من قتل إنسان، أو موت إنسان في خطر، أو حريق، أو أشباهه أشياء -يعني مهمة- يخشى من وقوعها؛ فلا بأس أن يقطع ليستبرء الحاجة، ويعرف الأمر، ثم يعود إلى الصلاة.","link":"https://binbaz.org.sa/fatwas/3348/حكم-قطع-الصلاة-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1669.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":7586,"question":"يقول أيضاً المرسل فائز سعيد غرمان الشهري من تنومة: هل يجوز أن يصلي أحد في الظلام وهو داخل المنزل أم لابد من وجود نور عنده وهو يصلي، نرجو الإفادة؟","title":"حكم الصلاة في الظلام","answer":"الجواب: لا حرج في أن يصلي في الظلام إذا عرف القبلة وصار إلى القبلة فلا حرج أن يصلي في الظلام، ولا يشترط له وجود النور، ولا يجب بل ذلك جائز، إن صلى في النور أو في الظلام لا بأس، إذا كانت القبلة معروفة ولا يحتاج إلى النور في معرفة القبلة فلا حاجة إلى النور، المقصود: أنه لا يتعلق بهذا شيء، الصلاة صحيحة مطلقاً، سواء كان ذلك في نور أو في ظلمة إذا كان إلى قبلة واستوفت شروطها. نعم.","link":"https://binbaz.org.sa/fatwas/4639/حكم-الصلاة-في-الظلام ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01904.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":7923,"question":"هذه رسالة -طول الله عمرك- عن التثاؤب في صلاة الفجر بعث بها محسن الكهربائي من مؤسسة السيسي بالمدينة المنورة، يرجو عرض هذه الرسالة على سماحة الشيخ عبد العزيز بن عبد الله بن باز يقول: أطال الله لنا في عمركم وجنبكم شر المخاطر وحفظكم الله لنا من كل سوء على الدوام، أنا كثير التثاؤب وخصوصاً في صلاة الفجر مما يعطلني كثيراً عن الصلاة، وقد يصيبني أربع أو خمس مرات بالذات في صلاة الفجر، حيث أنا قلق بسبب هذا التثاؤب الذي أخبر عنه النبي ﷺ أنه من الشيطان، كيف أقي نفسي منه، أفيدوني، جزاكم الله عنا خير عن الإسلام والمسلمين؟","title":"علاج كثرة التثاؤب في صلاة الفجر","answer":"الجواب: التثاؤب لاشك أنه من الشيطان كما قاله النبي ﷺ: إن الله يحب العطاس ويكره التثاؤب، وأخبر أن التثاؤب من الشيطان، وأن السنة للمؤمن إذا تثاءب أن يكتم ما استطاع، وأن يضع يده على فيه، وألا يقول: هاه؛ فإن الشيطان يضحك منه، فالسنة في مسألة التثاؤب أن يكتم ما استطاع، وأن لا يتكلم عند التثاؤب، وأن يضع يده على فيه، وإذا ابتلي به الإنسان فإنه يعالجه بما يستطيع من الطرق التي تزيله، وهو في الغالب ينشأ عن الكسل والبطنة والشبع، فلعلك أيها السائل تتأخر في النوم، فإذا قمت الفجر قمت وأنت كسلان ضعيف لم تأخذ حظك من النوم؛ فلهذا يصيبك التثاؤب الكثير في صلاة الفجر.\nفنصيحتي لك أيها السائل: أن تبكر بالنوم حتى تأخذ حظك الكثير الطيب من النوم فتصبح نشيطاً طيباً، وأوصيك أيضاً إذا قمت من النوم أن تفعل ما شرعه الله بأن تقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، الحمد لله الذي أحياني بعدما أماتني وإليه النشور، هكذا علمنا النبي عليه الصلاة والسلام عند القيام من نوم الليل، فينبغي أن تقول هذا إذا قمت من النوم آخر الليل تقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، وهكذا إذا استيقظت في أثناء النوم، إذا استيقظت في أثناء النوم تقول هذا أيضاً، وتقول أيضاً عند القيام آخر الليل: الحمد لله الذي أحياني بعدما أماتني وإليه النشور، وعند هذا يزول هذا التثاؤب إن شاء الله؛ لأنه من الشيطان، والذكر يطرد الشيطان، والتبكير بالنوم يزيل الكسل والضعف الذي يحصل لمن تأخر نومه، فإذا اجتمع التبكير بالنوم مع ذكر الله  عند القيام من النوم فإن الله جل وعلا يزيل عنك هذا التثاؤب، وهكذا الوضوء الشرعي يعين على ذلك، فعليك أن تفعل ما شرعه الله من التبكير بالنوم، ومن الذكر عند الاستيقاظ، والله جل وعلا يعينك ويزيل عنك هذا الشر الذي تأذيت به وقلقت منه. نعم.","link":"https://binbaz.org.sa/fatwas/5422/علاج-كثرة-التثاوب-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_064/06402.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":8285,"question":"إذاً ننتقل إلى رسالة أخينا حيدر عبد الله أبو دياب من السودان. أخونا يقول: هل يجوز للمرأة أن تخطب في جمع من الناس فيه رجال ونساء، وبواسطة مكبرات الصوت باسم الدين، وتصوير تلك الندوة كما يسمونها بأفلام الفيديو، ويتم توزيعها داخل وخارج البلد، وكل ذلك باسم الدين؟ وهل في الإسلام قاعدة اسمها: الغاية تبرر الوسيلة؟","title":"حكم محاضرة المرأة للرجال وتصوير المحاضرة","answer":"الجواب: هذه الخطبة لا حرج فيها، كون المرأة تخطب الناس وتذكر الناس وإن كان فيهم رجال، لا مانع من ذلك بالصوت العادي، لا بالخضوع ولا بصوت آخر منكر كما قال جل وعلا: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32].\nفإذا كانت الخطبة قولاً معروفاً ليس فيه شيء مما يعتبر خضوعاً في القول، والمقصود النصيحة، فقد نصح الصحابيات وغير الصحابيات نصحوا الرجال ونصحوا النساء، والله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، ويقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا [فصلت:33] وهذا يعم الرجال والنساء جميعاً، فإذا خطبت وذكرت ودعت إلى الله فلا بأس بذلك بشرط الصيانة والبعد عن الخلوة بأي رجل من غير محارمها، ومع الحجاب، كل هذا لا بأس به.\nأما التصوير فهذا هو الذي ينكر، فإنها لا تصور إلا إذا كان تصويرها وهي مستورة متحجبة في وجهها وكل شيء هذا لا يضر تصويرها، لكن جنس التصوير ينبغي ألا يفعل في هذه المسائل، بل ينبغي أن يسجل سماعاً من دون صورة؛ لأن الصورة أصلها ممنوع ومحرم كما قال النبي ﷺ: أشد الناس عذاباً يوم القيامة المصورون فلا حاجة إلى التصوير، ولا حاجة إلى تصويرها ولكن يسجل الكلام، تسجل الخطبة والموعظة وينفع الله بها من يشاء من دون حاجة إلى التصوير. نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6093/حكم-محاضرة-المراة-للرجال-وتصوير-المحاضرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10006.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":8317,"question":"شيخ عبد العزيز في بداية هذه الحلقة نعود إلى رسالة الأخت (ع. ز) من الأعظمية بغداد الرصافة، أختنا عرضنا في حلقة سبقت بعضاً من أسئلة لها، وكان من أسئلتها السؤال عن الصلاة من الوضوء حتى التسليم كما حددت هي، تفضلتم وبينتم الكيفية الصحيحة التي ينبغي أن يكون عليها المسلم تجاه الصلاة ولا سيما إذا اختلف الأداء في قطر من الأقطار على طريقة مذهبية معينة، أرجو أن تتفضلوا سماحة الشيخ بتكملة ما بدأتموه في تلكم الحلقة لعل أختنا وأخواتها -كما تقول- يستفدن وكذلك المستمعين الكرام؟","title":"تتمة صفة صلاة النبي صلى الله عليه وسلم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه، وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد:\nفقد سبق الكلام على الوضوء، وبينا الكيفية الشرعية للوضوء، وسبق الكلام في أول الصلاة وانتهينا إلى الركوع؛ فالذي شرعه الله جل وعلا في الركوع: أن المصلي إذا انتهى من القراءة يكبر رافعاً يديه راكعاً، يرفع يديه إلى حذو منكبيه أو إلى حيال أذنيه ويكبر قائلاً: الله أكبر، ثم يسوي ظهره -كما تقدم- ويجعل يديه على ركبتيه مفرجتي الأصابع ويقول: سبحان ربي العظيم.. سبحان ربي العظيم، وهذا يستوي فيه المرأة والرجل جميعاً، ويشرع له أن يقول مع ذلك: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، والأفضل أن يكرر التسبيح ثلاثاً يقول: سبحان ربي العظيم .. سبحان ربي العظيم .. سبحان ربي العظيم، وإن كرر أكثر فهو أفضل ما لم يشق على المأمومين إذا كان إماماً، ويستحب أن يقول في ذلك: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي؛ لما ثبت عن عائشة رضي الله عنها قالت: كان النبي صلى الله عليه وسلم يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، وجاء عنه ﷺ أنه كان يقول في الركوع: سبحان ذي الجبروت والملكوت والكبرياء والعظمة، سبوح قدوس رب الملائكة والروح، فإذا قال مثل هذا فحسن اقتداءً بالنبي عليه الصلاة والسلام.\nثم يرفع قائلاً: سمع الله لمن حمده، إذا كان إماماً أو منفرداً، يقول عند الرفع: سمع الله لمن حمده، ويرفع يديه مثلما فعل عند الركوع حيال منكبيه أو حيال أذنيه عند قوله: سمع الله لمن حمده، ثم بعد انتصابه واعتداله يقول: ربنا ولك الحمد، أو اللهم ربنا لك الحمد، حمداً كثيراً طيباً مباركاً فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، هذا ثبت عن النبي ﷺ من قوله وفعله عليه الصلاة والسلام، ولا فرق في هذا بين الرجل والمرأة، وإن زاد على هذا فقال: أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفعع ذا الجد منك الجد، فذلك حسن؛ لأن الرسول كان يقوله في بعض الأحيان عليه الصلاة والسلام، ومعنى: (ولا ينفع ذا الجد منك الجد) يعني: ولا ينفع ذا الغنى منك غناه، فالجميع فقراء إلى الله سبحانه وتعالى، والجد هو: الحظ والغنى.\nوأما إذا كان مأموماً فإنه يقول: (ربنا ولك الحمد) عند الرفع، ويرفع يديه أيضاً حيال منكبيه أو حيال أذنيه عند الرفع قائلاً: ربنا ولك الحمد، أو ربنا لك الحمد، أو اللهم ربنا لك الحمد، أو اللهم ربنا ولك الحمد، كل هذا مشروع للإمام والمأموم والمنفرد جميعاً، لكن الإمام يقول: (سمع الله لمن حمده) أولاً وهكذا المنفرد، ثم يأتي بالحمد بعد ذلك، أما المأموم فإنه يقول هذا عند ارتفاعه من الركوع يقول: (ربنا ولك الحمد) ولا يأتي بالتسميع، لا يقول: (سمع الله لمن حمده) على الصحيح المختار الذي دلت عليه الأحاديث عن رسول الله عليه الصلاة والسلام.\nوالواجب الاعتدال في هذا الركن، لا يعجل، متى رفع يعتدل ويطمئن قائماً ويضع يديه على صدره هذا هو الأفضل، قال بعض أهل العلم: يرسلها، ولكن الصواب أنه يضعهما على صدره، يضع اليمنى كف اليمنى على كف اليسرى على صدره كما فعل قبل الركوع وهو قائم، هذا هو السنة؛ لما ثبت عنه ﷺ أنه كان إذا كان قائماً في الصلاة وضع كفه اليمنى على كفه اليسرى في الصلاة على صدره، ثبت هذا من حديث وائل بن حجر ، وثبت هذا أيضاً من حديث قبيصة بن خلد الطائي عن أبيه، وثبت مرسلاً من حديث طاوس عن النبي ﷺ، هذا هو الأفضل والسنة، وإن أرسل يديه فلا حرج في صلاته صلاته صحيحة لكنه ترك السنة، ولا ينبغي للمؤمنين المشاقة في هذا أو المنازعة، بل المؤمن يعلم السنة وطالب العلم يعلم السنة لإخوانه، ولكن لا يشنع على من أرسل، ولا يكون بينه وبينهم العداوة والشحناء؛ لأنها سنة نافلة، فلا ينبغي للإخوان لا في أفريقيا ولا في غيرها النزاع في هذا والشحناء، بل يكون التعليم بالرفق والحكمة والمحبة لأخيه كما يحب لنفسه، هكذا ينبغي في هذه الأمور.\nوجاء في حديث سهل في الصحيح صحيح البخاري عن سهل بن سعد قال: كان الرجل يؤمر أن يجعل يده اليمنى على ذراعه اليسرى في الصلاة قال أبو حازم الراوي عن سهل: لا أعلمه إلا ينمي ذلك إلى النبي ﷺ؛ فدل ذلك على أنه في الصلاة إذا كان قائماً يضع يده اليمنى على ذراعه اليسرى، والمعنى: على كفه وطرف ذراعه؛ لأن هذا هو الجمع بينه وبين رواية وائل بن حجر ، فإذا وضع كفه على الرسغ والساعد فقد وضعه على الذراع، لأن الساعد من الذراع فيضع كفه اليمنى على كفه اليسرى وعلى الرسغ والساعد كما جاء مصرحاً به في حديث وائل ، وهذا يشمل القيام الذي قبل الركوع والقيام الذي بعد الركوع.\nوهذا الاعتدال من أركان الصلاة لابد منه، بعض الناس قد يعجل من حين يرفع ينزل ساجداً وهذا لا يجوز، بل الواجب على المصلي أن يعتدل بعد الركوع ويطمئن ولا يعجل، قال أنس : كان النبي ﷺ إذا وقف بعد الركوع يعتدل ويقف طويلاً حتى يقول القائل: قد نسي، وهكذا بين السجدتين يطول عليه الصلاة والسلام حتى يقول القائل: قد نسي، فالواجب على المصلي في الفريضة وفي النافلة ألا يعجل، بل يطمئن بعد الركوع طمأنينة واضحة يأتي فيها بالذكر المشروع وهكذا بين السجدتين لا يعجل يطمئن ويعتدل بين السجدتين كما يأتي ويقول بينهما: (رب اغفر لي.. رب اغفر لي) كما فعله النبي عليه الصلاة والسلام.\nثم بعد هذا الحمد والثناء والاعتدال والطمأنينة بعد الركوع ينحط ساجداً قائلاً: (الله أكبر) من دون رفع اليدين، ينحط ساجداً من دون رفع اليدين؛ لأن الثابت عن رسول الله ﷺ عدم الرفع في هذا المقام، فيسجد على أعضائه السبعة: جبهته وأنفه هذا عضو، وكفيه، وعلى ركبتيه، وعلى أصابع رجليه، قال النبي ﷺ: أمرت أن أسجد على سبعة أعظم: على الوجه، واليدين، والركبتين، وأطراف القدمين هذا هو المشروع وهذا هو الواجب على الرجال والنساء جميعاً أن يسجدوا على هذه الأعضاء السبعة: الجبهة والأنف هذا عضو، واليدين -يعني: الكفين- يبسطهما ويمدهما إلى القبلة يمد أطراف أصابعه إلى القبلة ضاماً بعضها إلى بعض، والركبتين، وأطراف القدمين يعني: على أصابع القدمين باسطاً لها على الأرض الأصابع ومعتمداً عليها وأطرافها إلى القبلة هكذا فعل النبي ﷺ.\nوالأفضل أن يقدم ركبتيه قبل يديه عند انحطاطه للسجود، هذا هو الأفضل، وذهب بعض أهل العلم إلى أنه يقدم يديه، ولكن الأرجح هو أنه يقدم ركبتيه ثم يديه؛ لأنه ثبت هذا من حديث وائل بن حجر عن النبي صلى الله عليه وسلم أنه كان إذا سجد وضع ركبتيه قبل يديه.\nوجاء في حديث آخر عن أبي هريرة  عن النبي ﷺ أنه قال: لا يبرك أحدكم كما يبرك البعير، وليضع يديه قبل ركبتيه فأشكل هذا على كثير من أهل العلم، فقال بعضهم: يضع يديه قبل ركبتيه، وقال آخرون: بل يضع ركبتيه قبل يديه، وهذا هو الذي يخالف بروك البعير؛ لأن بروك البعير يبدأ بيديه، فإذا برك المؤمن على ركبتيه خالف البعير، وهذا هو الموافق لحديث وائل وهذا هو الصواب: أن يسجد على ركبتيه أولاً ثم يضع يديه على الأرض ثم يضع جبهته وأنفه على الأرض، هذا هو المشروع، فإذا رفع رفع جبهته أولاً ثم يديه ثم نهض، هذا هو المشروع الذي جاءت به السنة عن النبي ﷺ وهو الجمع بين الحديثين.\nوأما قوله في حديث أبي هريرة: وليضع يديه قبل ركبتيه، فالظاهر -والله أعلم- أنه انقلاب كما ذكر ذلك ابن القيم رحمه الله، وإنما الصواب أن يضع ركبتيه قبل يديه حتى يوافق آخر الحديث أوله، وحتى يتفق مع حديث وائل وما جاء في معناه.\nوفي هذا السجود يقول: سبحان ربي الأعلى.. سبحان ربي الأعلى، ويكرر ثلاثاً أو خمساً أو أكثر من ذلك، لكن يراعي الإمام المأمومين، إذا كان إماماً يراعيهم حتى لا يشق عليهم، أما المنفرد فهذا لا يضره لو أطال بعض الشيء، كذلك المأموم تابع لإمامه فيسبح ويدعو ربه في السجود حتى يرفع إمامه، والسنة للإمام والمأموم والمنفرد الدعاء في السجود، يقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، وأول الحديث يقول ﷺ: إني نهيت أن أقرأ القرآن راكعاً أو ساجداً  فالركوع والسجود ما فيه قراءة، لا يقرأ في الركوع ولا في السجود، إنما القراءة في حال القيام في حق من قدر، وفي حال القعود في حق من عجز عن القيام يقرأ وهو قاعد، أما السجود والركوع فليس فيهما قراءة، وإنما فيهما تسبيح الرب وتعظيمه وفي السجود زيادة على ذلك الدعاء، فيقول: سبحان ربي الأعلى.. سبحان ربي الأعلى.. سبحان ربي الأعلى ويدعو، وكان النبي ﷺ يدعو في سجوده يقول: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره فيدعو بمثل هذا الدعاء الذي كان يدعو به النبي ﷺ كما رواه مسلم في الصحيح.\nوثبت في صحيح مسلم أيضاً عن أبي هريرة  عن النبي ﷺ أنه كان يقول: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، هذا يدلنا على شرعية كثرة الدعاء في السجود من الإمام والمأموم والمنفرد، فيدعو كل منهم في سجوده مع التسبيح.. مع قوله: سبحان ربي الأعلى.. سبحان ربي الأعلى، ومع قوله: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، لما سبق في حديث عائشة رضي الله عنها عند الشيخين - البخاري ومسلم - رحمة الله عليهما قالت: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك.. اللهم اغفر لي، ويشرع مع هذا الدعاء والجد في الدعاء في المهمات من أمر الدنيا والآخرة، ولا حرج أن يدعو بأمر دنياه كأن يقول: اللهم ارزقني زوجة صالحة، أو تقول المرأة: اللهم ارزقني زوجاً صالحاً، أو ذرية طيبة، أو مالاً حلالاً، أو ما أشبه ذلك من حاجات الدنيا، ويدعو فيما يتعلق بالآخرة وهو الأكثر وهو الأهم كأن يقول: «اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره»، اللهم أصلح قلبي وعملي، وارزقني الفقه في ديني، اللهم إني أسألك الهدى والسداد، اللهم إني أسألك الهدى والتقى والعفاف والغنى، اللهم اغفر لي ولوالدي وللمسلمين، اللهم أدخلني الجنة وأنجني من النار، وما أشبه هذا الدعاء، يكثر في سجوده من الدعاء لكن من غير إطالة تشق على المأمومين، بل يراعي المأمومين حتى لا يشق عليهم إذا كان إماماً، ويقول مع ذلك في سجوده: «سبحانك اللهم ربنا وبحمدك اللهم اغفر لي» -كما تقدم- مرتين أو ثلاثاً كما فعله المصطفى عليه الصلاة والسلام.\nثم يرفع من السجدة قائلاً: (الله أكبر) ويجلس مفترشاً يسراه ناصباً يمناه، فيضع يده اليمنى على فخذه اليمنى أو على الركبة باسطاً أصابعه على ركبته، ويضع يده اليسرى على فخذه اليسرى أو على ركبته ويبسط أصابعه على ركبته هكذا السنة، إذا جلس بين السجدتين يضع اليمنى على فخذه اليمنى أو ركبته اليمنى، ويضع اليسرى على فخذه اليسرى أو ركبته اليسرى، ويقول: رب اغفر لي.. رب اغفر لي.. رب اغفر لي كما كان النبي يقول ﷺ، ويستحب أن يقول مع هذا: اللهم اغفر لي، اللهم اغفر لي، وارحمني، واجبرني، وارزقني، وعافني، يروى هذا عن النبي ﷺ أيضاً مع قوله: رب اغفر لي.. رب اغفر لي، اللهم اغفر لي، وارحمني، واهدني، واجبرني، وارزقني، وعافني، وإن دعا بالزيادة فلا بأس كأن يقول: اللهم اغفر لي ولوالدي، اللهم أدخلني الجنة وأنجني من النار، اللهم أصلح قلبي وعملي.. ونحو ذلك لا بأس، ولكن يكثر من المغفرة.. من طلب المغفرة فيما بين السجدتين اقتداء بالنبي عليه الصلاة والسلام.\nثم بعد ذلك يسجد الثانية قائلاً: الله أكبر، ويسجد الثانية على جبهته وأنفه وعلى كفيه وعلى ركبتيه وعلى أطراف قدميه كما فعل في السجدة الأولى، ويعتدل.. يرفع بطنه عن فخذيه، وفخذيه عن ساقيه، لا يبرك بروكاً كالبهيمة، لا، بل يعتدل في السجود؛ يقول النبي ﷺ: اعتدلوا في السجود ولا يبسط أحدكم ذراعيه انبساط الكلب، وقال عليه الصلاة والسلام: إذا سجد أحدكم فليضع كفيه وليرفع مرفقيه، فالسنة كونه يعتدل يكون واضعاً كفيه على الأرض رافعاً ذراعيه عنها ولا يبسطها كالكلب والذئب ونحو ذلك، لا، بل يرفعها ويرفع بطنه عن فخذيه، ويرفع فخذيه عن ساقيه حتى يعتدل في السجود ويكون مرتفعاً معتدلاً واضعاً كفيه على الأرض رافعاً ذراعيه عن الأرض كما أمر بهذا النبي ﷺ وكما فعل عليه الصلاة والسلام.\nثم يقول في السجود: سبحان ربي الأعلى.. سبحان ربي الأعلى.. سبحان ربي الأعلى، ويدعو -كما تقدم- في السجود الأول، ويقول: سبحانك اللهم ربنا وبحمدك.. اللهم اغفر لي، مثلما قال في السجود الأول.\nثم يكبر رافعاً ناهضاً إلى الركعة الثانية، والأفضل يجلس جلسة خفيفة بعد السجود الثاني جلسة خفيفة يسميها بعض الفقهاء: جلسة الاستراحة، يجلس على رجله اليسرى مفروشة وينصب اليمنى مثل حاله بين السجدتين لكنها خفيفة ليس فيها ذكر ولا دعاء هذا هو الأفضل وإن قام ولم يجلس فلا حرج، لكن الأفضل أن يجلسها كما فعلها النبي صلى الله عليه وسلم، وقال بعض أهل العلم: إن هذا يفعل عند كبر السن وعند المرض، ولكن الصحيح أنها سنة من سنن الصلاة مطلقاً ولو كان المصلي شاباً وصحيحاً، فهي مستحبة على الصحيح لكنها غير واجبة وهي جلسة خفيفة ليس فيها ذكر ولا دعاء، يجلس على رجله اليسرى وينصب اليمنى مثل الجلوس بين السجدتين.\nثم ينهض إلى الثانية مكبراً قائلاً: (الله أكبر) من حين ينهض من سجوده جالساً جلسة الاستراحة، أو حين يفرغ من جلسة الاستراحة ينهض ويقول: الله أكبر، فإن بدأ بالتكبير جلس فينبه الجماعة على ألا يسبقوه حتى يجلسوها ويأتوا بهذه السنة، وإن جلسها قبل أن يكبر ثم رفع بالتكبير فلا بأس، المهم أن هذه جلسة مستحبة وليست واجبة، فإن أتى بالتكبير قبلها وجه المأمومين حتى لا يسبقوه بجلوسها، وإن جلس أولاً ثم رفع بالتكبير فلا حاجة إلى التوجه إليه إلا من باب التعليم من باب تعليم السنة.\nثم يفعل في الثانية كما فعل في الأولى: يقرأ الفاتحة، يتعوذ بالله من الشيطان الرجيم ويسمي الله، وإن ترك التعوذ واكتفى بالتعوذ الأول في الأولى فلا بأس، وإن أعاده فهو أفضل؛ لأنه مع قراءة جديدة، فيتعوذ بالله من الشيطان ويسمي ويقرأ الفاتحة ثم يقرأ معها سورة أو آيات كما فعل في الأولى، لكن تكون السورة في الثانية أقصر من الأولى، تكون قراءته في الثانية أقصر من الأولى كما ثبت ذلك في الصحيحين من حديث أبي قتادة الأنصاري ، فإذا فرغ من القراءة كبر للركوع كما فعل في الركعة الأولى، أن يكبر رافعاً يديه قائلاً: الله أكبر، ثم يضع يديه على ركبتيه مفرجتي الأصابع كما فعل في الأول، ويكون ظهره مستوياً، ويكون رأسه حيال ظهره مستوياً، هكذا كان النبي يفعل عليه الصلاة والسلام، ويقول: سبحان ربي العظيم.. سبحان ربي العظيم.. ثلاثاً أو خمساً أو سبعاً أو أكثر من ذلك لكن بشرط ألا يشق على المؤمنين إذا كان إماماً، ويستحب أن يقول مع ذلك: سبحانك اللهم ربنا وبحمدك.. اللهم اغفر لي، كما تقدم، وإن قال: سبحان ذي الجبروت والملكوت والكبرياء والعظمةفحسن أيضاً، وهكذا: سبوح قدوس رب الملائكة والروح، كل هذا حسن فعله النبي ﷺ، وفعل أيضاً في تهجده في الركوع يقول: اللهم لك ركعت، وبك آمنت، ولك أسلمت، خشع لك سمعي وبصري ومخي وعظمي وعصبي وجميع ما استقلت به قدمي، هذا كان يقوله صلى الله عليه وسلم في الركوع وفي صلاة التهجد تهجده في الليل، فإذا فعله في الليل أو في الفريضة فلا بأس بذلك، ولكن يلاحظ عدم المشقة على المأمومين إذا كان إماماً.\nثم بعدما يأتي بالأذكار المشروعة في الركوع ينهض رافعاً قائلاً: (سمع الله لمن حمده) إذا كان إماماً أو منفرداً كما تقدم في الركعة الأولى، ثم يعتدل بعد الركوع وينتصب ويخشع لله ويقول في ذلك: (ربنا ولك الحمد)، أو اللهم ربنا لك الحمد حمداً كثيراً طيباً مباركاً فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، هذا هو الأفضل، وإن زاد فقال: أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، فكل ذلك حسن فعله النبي عليه الصلاة والسلام، وهذا عام للإمام والمأموم والمنفرد جميعاً، لكن للمأموم عند الرفع لا يقول: سمع الله لمن حمده بل يقول: ربنا ولك الحمد كما سبق في الركعة الأولى.\nثم بعد الفراغ من القراءة يكبر راكعاً كما فعل في الركعة الأولى كما تقدم بعد فراغه من القراءة يركع كما تقدم ويفعل كما تقدم من رفع يديه عند الركوع ووضعهما على ركبتيه ويسوي ظهره ويسوي رأسه مع ظهره كل هذا تقدم.\nوإذا اعتدل بعد الركوع لا يعجل بل يطمئن -كما تقدم- وأن الرسول ﷺ كان يطمئن في ذلك حتى يقول القائل: قد نسي. بعض الناس يعجل في اعتداله ولا يطمئن وهذا غلط لا يجوز، بل يبطل الصلاة إذا عجل ولم يعتدل، فلا بد من اعتداله وطمأنينته بعد الركوع يقول في ذلك: ربنا ولك الحمد.. إلى آخره بعد قوله: (سمع الله لمن حمده) عند الرفع إذا كان إماماً أو منفرداً، أما المأموم فيرفع قائلاً: (ربنا ولك الحمد) رافعاً يديه مع ذلك حيال منكبيه أو حيال أذنيه ثم يكمل: ربنا ولك الحمد حمداً كثيراً طيباً مباركاً فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، ثم ينحط للسجود وإن زاد قبل أن ينحط للسجود:أهل الثناء والمجد أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، كان هذا أكمل وأفضل لفعله ﷺ.\nثم ينحط ساجداً -كما تقدم- في الركعة الأولى ينحط من هذا الاعتدال ساجداً مكبراً من غير رفع يدين بل يكبر عند الانحطاط للسجود من دون رفع اليدين ويسجد كما تقدم، يسجد السجدتين مثل سجوده في الركعة الأولى سواء، يسجد الأولى ويقول فيها: سبحان ربي الأعلى.. سبحان ربي الأعلى، ويدعو فيها بما تيسر ثم يرفع مكبراً ويقول: (رب اغفر لي.. رب اغفر لي) ويعتدل ويطيل هذا الاعتدال حتى ... بين السجدتين ثم يكبر ويسجد الثانية ويدعو فيها ويقول: سبحان ربي الأعلى.. سبحان ربي الأعلى كما تقدم.\nثم يرفع فيجلس للتشهد الأول، إذا كانت الصلاة رباعية كالظهر والعصر والعشاء أو ثلاثية كالمغرب فيأتي بالتشهد: التحيات لله، والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وأشهد أن محمداً عبده ورسوله» . هذا هو الثابت في الصحيحين من حديث عبدالله بن مسعود رضي الله عنه، وإن أتى بغير هذا مما ثبت في الأحاديث الصحيحة كفى، لكن هذا أثبتها، هذا الأفضل الذي قلناه لكم هذا هو أثبتها، ثم بعد هذا يقول: «اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد.\nثم ينهض إلى الثالثة وإن لم يأت بالصلاة على النبي وآله قد نهض بعد الشهادة فلا بأس حين قال: (وأشهد أن محمداً عبده ورسوله) لو نهض ولم يصل على النبي صلى الله عليه وسلم فلا بأس؛ لأن جملة من أهل العلم لا تستحب هنا وإنما هي مشروعة في التشهد الأخير، ولكن ظاهر الأحاديث الصحيحة أنها تشرع هنا وهناك، فيأتي بها أفضل هنا لكن ليست واجبة عليه هنا وإنما تجب في التشهد الأخير عند جمع من أهل العلم.\nفإذا فرغ من التشهد والصلاة على النبي صلى الله عليه وسلم؛ لأنه الأفضل أن يصلي على النبي صلى الله عليه وسلم على الصحيح ينهض بعد مكبراً قائلاً: (الله أكبر) رافعاً يديه كما ثبت هذا من حديث ابن عمر عند البخاري رحمه الله، فيرفع يديه مكبراً قائلاً: (الله أكبر) عند نهوضه من التشهد الأول حتى يأتي بالثالثة في المغرب وحتى يأتي بالثالثة والرابعة في العشاء والظهر والعصر.\nويقرأ الفاتحة هذا هو الأفضل وتكفيه الفاتحة، يقرأ الفاتحة وتكفيه الفاتحة لا زيادة كما ثبت هذا في حديث أبي قتادة «أن النبي صلى الله عليه وسلم كان يقرأ في الركعتين الأخيرتين بفاتحة الكتاب» وهكذا الأخيرة من المغرب، وإن قرأ زيادة في الظهر بعض الأحيان فحسن؛ لأنه ثبت من حديث أبي سعيد رضي الله عنه عن النبي صلى الله عليه وسلم «أنه كان في الظهر يقرأ في الأوليين من العصر مقدار ما يقرأ في الأخريين من الظهر»، فهذا يدل على أنه كان يقرأ في الأخيرتين من الظهر زيادة على الفاتحة، فإذا قرأ زيادة فلا بأس بل هو حسن في بعض الأحيان، وفي بعض الأحيان يقتصر على الفاتحة في الظهر كالعصر والمغرب والعشاء جمعاً بين حديث أبي سعيد وحديث أبي قتادة ، فإذا قرأ في الثالثة والرابعة من الظهر فهذا على حديث أبي سعيد ، وإذا ترك فهذا على حديث أبي قتادة ، فيفعل هذا تارة وهذا تارة، أما في الثالثة والرابعة من العصر والثالثة والرابعة من العشاء والثالثة من المغرب فليس فيها إلا قراءة الفاتحة فقط، لا يقرأ زيادة لعدم الدليل على ذلك.\nثم بعد فراغه من الفاتحة في الثالثة من المغرب والثالثة والرابعة من الظهر والعصر والعشاء ينحط ساجداً قائلاً: (الله أكبر) فيسجد سجدتين مثلما فعل في الركعة الأولى والثانية بعدما يركع.. يركع أولاً -كما هو معلوم- بعد أن فرغ من القراءة يركع الركوع الشرعي مكبراً رافعاً يديه فيركع ويستوي في الركوع ويعتدل في الركوع ويضع يديه على ركبتيه ويجعل رأسه حيال ظهره مستوياً خاشعاً مطمئناً يقول: سبحان ربي العظيم.. سبحان ربي العظيم.. سبحان ربي العظيم، وإن زاد فقال: سبحانك اللهم ربنا وبحمده.. اللهم اغفر لي فحسن كما تقدم في حديث عائشة ، ثم بعدما يأتي بهذا الذكر في الركوع يرفع قائلاً: (سمع الله لمن حمده) إذا كان إمام أو منفرد، أما إن كان مأموماً فعند الرفع يقول: ربنا ولك الحمد، ثم يكمل الإمام والمنفرد والمأموم يكملون: «ربنا ولك الحمد حمداً كثيراً طيباً مباركاً فيه ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد»، هذا هو المشروع، وهكذا في الركعة الرابعة يفعل مثل هذا سواء.\nوينحط للسجود مثل الركوع مثلما فعل في الأولى والثانية، ينحط مكبراً قائلاً: الله أكبر، فيسجد على السبعة الأعضاء كما تقدم ويطمئن في سجوده ولا يعجل، ويعتدل بين السجدتين اعتدالاً كاملاً، وهكذا في الركعة الأخيرة سواء بسواء، وهكذا في الثالثة من المغرب سواء بسواء.\nأما الفجر فليس فيها ثالثة ولا رابعة، الفجر ركعتان، وهكذا الجمعة ركعتان، وهكذا العيد ركعتان يقرأ فيهما بالفاتحة وما تيسر معها من القرآن الكريم كما هو معلوم من سنة النبي عليه الصلاة والسلام، وبهذا تنتهي الصلاة ولا يبقى إلا التشهد.\nفإذا فرغ من الرابعة في الظهر والعصر والعشاء والثالثة من المغرب والثانية من الفجر والجمعة ونحو ذلك إذا فرغ من السجدة الثانية في الركعة الأخيرة جلس للتحيات كما قرأها في التشهد الأول يقرؤها أخيراً، فيقول: التحيات لله، والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وأشهد أن محمداً عبده ورسوله» ثم يصلي على النبي صلى الله عليه وسلم فيقول: «اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، هكذا يجب أن يأتي بها هكذا كما شرع الله، وفي هذا خلاف لكن هذا هو الصواب أنه يجب أن يأتي بالصلاة على النبي ﷺ في الشتهد الأخير؛ لأن الرسول ﷺ لما سألوه: «ماذا نقول في صلاتنا إذا ... ؟ قال: قولوا: اللهم صل على محمد.. إلى آخره، قال: والسلام كما علمتم أي: في قوله: السلام عليك أيها النبي ورحمة الله وبركاته، فدل على أن هذا يقال في الصلاة.\nفبعد هذه الصلاة على النبي ﷺ يدعو بالدعوات المشهورة ويتعوذ بالله من الأربع الأشياء التي كان يتعوذ منها النبي ﷺفيقول: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال كان النبي ﷺ يتعوذ من هذه الأربع..","link":"https://binbaz.org.sa/fatwas/6122/تتمة-صفة-صلاة-النبي-صلى-الله-عليه-وسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_109/10901.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":8338,"question":"الشيخ عبد العزيز ! هذه هي المرة الثالثة التي نعرض فيها رسالة الأخت (مها . ع. ز) من بغداد الرصافة الأعظمية، أختنا تثير سؤالاً ربما يكون مستغرباً بعض الشيء تقول: إننا لم نجد من يدلنا على أداء الصلاة الصحيحة، وقد تفضلتم سماحة الشيخ ووصفتم لها الطريقة الصحيحة المشروعة عن الرسول ﷺ في كيفية أداء الصلاة، ولا أشك أن لسماحة الشيخ بعض التعليقات على ما تقدم، ولاسيما وأن البعض يذكر أن للمرأة صورةً معينة حين تؤدي صلواتها، وأيضاً بالنسبة للجمعة والجماعة بالنسبة للمرأة أيضاً لو تكرمتم سماحة الشيخ، فأرجو أن تتفضلوا بتكملة ما بدأتموه؟","title":"استواء الرجل والمرأة في صفة الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد سبق بيان صفة صلاة النبي ﷺ في حلقتين، ووقفنا في الحلقة الثانية على ما يتعلق بالدعاء في التشهد الأخير من الصلاة، وسبق لنا أن الله جل وعلا شرع لنا على يد رسوله ﷺ أن نقول في آخر الصلاة بعد قراءة التحيات نستعيذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال هذا مشروع للرجال والنساء جميعاً، في الفرض والنفل، ويستحب مع هذا أن يدعو الإنسان بما تيسر؛ لأن النبي ﷺ لما علم الصحابة التشهد قال: ثم ليختر من الدعاء أعجبه .... فيدعو وفي لفظ آخر قال: ثم ليختر من المسألة ما شاء وكان النبي ﷺ يدعو بهذه الدعوات: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال وقال لـمعاذ: يا معاذ ! إني لأحبك فلا تدعن أن تقولل دبر كل صلاة: اللهم أعني على ذكرك وشكرك وحسن عبادتك وثبت عنه ﷺ من حديث علي ، أنه كان يقول في آخر الصلاة قبل أن يسلم: اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني أنت المقدم وأنت المؤخر لا إله إلا أنت وثبت أيضاً في صحيح البخاري عن سعد بن أبي وقاص  أن النبي ﷺ كان يقول في آخر الصلاة: اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا ومن عذاب القبر فهذه دعوات طيبة يشرع أن تقال في آخر الصلاة، بعدما يقرأ التحيات والشهادة والصلاة على النبي ﷺ، يأتي بهذه الدعوات التي ذكرنا هنا وفي ما ذكرنا في آخر الحلقة السابقة.\nوالخلاصة أنه يقول بعد الصلاة على النبي ﷺ: أعوذ بالله من عذاب جهنم، أو اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال وإذا زاد أدعيةً أخرى كما تقدم فذلك حسن مثل ما تقدم: اللهم أعني على ذكرك وشكرك وحسن عبادتك، اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني، أنت المقدم وأنت المؤخر لا إله إلا أنت وهكذا في الدعاء الآخر حديث سعد: اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا ومن عذاب القبر وهكذا الدعاء الوارد في حديث عبد الله بن عمرو في الصحيحين: اللهم إني ظلمت نفسي ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرةً من عندك وارحمني إنك أنت الغفور الرحيم هذا علمه النبي ﷺ علمه الصديق ، روى عبد الله بن عمرو بن العاص رضي الله تعالى عنهما: إن الصديق قال: يا رسول الله! علمني دعاءً أدعو به في صلاتي، قال: قل: اللهم إني ظلمت نفسي ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرةً من عندك وارحمني إنك أنت الغفور الرحيم وإذا كان الصديق يقال له هذا الدعاء، فكيف بحالنا؟! إذا كان الصديق وهو أفضل الصحابة  وهو مشهود له بالجنة!! ومع هذا يعلمه النبي ﷺ يقول: اللهم إني ظلمت نفسي ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرةً من عندك وارحمني إنك أنت الغفور الرحيم ... في أشد الحاجة إلى ذلك، فينبغي الإكثار من هذا الدعاء، قال أنس : كان أكثر دعاء النبي ﷺ: ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار.\nثم ينبغي أن يعلم أن المرأة كالرجل في هذه الأشياء، قال بعض أهل العلم: إن المرأة لها خصوصية، وهذا لا دليل عليه بل ما ورد من السنة يدل على أنه مشترك بين الرجال والنساء، فكما أن الرجل يقرأ الفاتحة وما تيسر معها من سور أو آيات فهي كذلك، وكما أنه يرفع عند الركوع وعند الرفع منه وعند قيامه من التشهد الأول إلى الثالثة، فهي كذلك ترفع يديها مثل الرجل، وكما أنه يضع يديه على صدره هي كذلك تضع يديها على صدرها حال القيام في الصلاة، وكما أنه يقول: (سبحان ربي العظيم) في الركوع هي مثله، ويقول في السجود: (سبحان ربي الأعلى) هي مثله، وتزيد في الركوع والسجود مثل الرجل: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي)، وتضع يديها في الركوع على ركبتيها، مفرجة الأصابع، وتضع في السجود يديها على الأرض حيال منكبيها أو حيال أذنيها كالرجل، وتضع يديها في الجلوس بين السجدتين على فخذيها أو على ركبتيها كالرجل، وتفترش رجلها اليسرى بين السجدتين وفي التشهد الأول، وفي التشهد الأخير تتورك، تجلس على مقعدتها وتجعل رجلها اليسرى تحت رجلها اليمنى عن رجلها اليمنى عن يمينها كالرجل سواء سواء، في هذه الأمور هذا هو الأرجح، وهذا هو المعتمد كما دلت عليه الأحاديث عن رسول الله عليه الصلاة والسلام. نعم.\nباقي عليها السلام، السلام أيضاً كذلك هذا أمر معلوم إذا فرغ من الدعاء يسلم الرجل والمرأة تسلم، فيقول: السلام عليكم ورحمة الله، عن يمينه، والسلام عليكم ورحمة الله، عن يساره، هكذا كان النبي يفعل عليه الصلاة والسلام، وهذا يستوي فيه الرجل والمرأة والفرض والنفل جميعاً، ثم بعدما يسلم يقول: (أستغفر الله ثلاثاً، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام)، يقوله الرجل والمرأة (أستغفر الله ثلاثاً، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام)، ثم ينصرف الإمام إلى الناس إذا كان إمام ينصرف بعد هذا ويعطي الناس وجهه، ويقول بعد هذا لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير وهكذا المأمومون يقول مثلها الرجال والنساء، مثل ما يقول الإمام لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير جاء هذا، تارة يقول: يحيي ويميت وتارةً لا يقول عليه الصلاة والسلام، ثبت هذا وهذا فتارة يقول: يحيي ويميت بيده الخير وتارة لا يقول ذلك والأمر واسع بحمد الله، فيقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير وتارة يزيد: يحيي ويميت بيده الخير وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد كل هذا مستحب بعد كل صلاة، للرجال والنساء، ثم يشرع بعد ذلك أن يقول: سبحان الله والحمد لله والله أكبر ثلاثاً وثلاثين مرة، الرجل والمرأة، سبحان الله والحمد لله والله أكبر ثلاثاً وثلاثين مرة بأصابعه يعقد أصابعه ثلاثاً وثلاثين مرة، فيكون الجميع تسعاً وتسعين، يعني: ثلاثاً وثلاثين تسبيحة، وثلاثاً وثلاثين تحميدة، وثلاثاً وثلاثين تكبيرة، إذا قال: سبحان الله والحمد لله والله أكبروعدها ثلاثاً وثلاثين مرة كانت تسعاً وتسعين، ثم يقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير قال النبي ﷺ: إذا قالها غفرت خطاياه ولو كانت مثل زبد البحروهذا فضل عظيم وخير عظيم، خير عظيم، والمعنى إذا قال هذا مع التوبة والندم والإقلاع، لا مجرد كلام فقط، بل يقول هذا مع الاستغفار والتوبة والندم وعدم الإصرار على الذنوب، ويرجى له هذا الخير العظيم حتى في الكبائر، إذا قاله عن إيمان وعن صدق وعن توبة صادقة وعن ندم على الذنوب، فإن الله يغفر له كبائرها وصغائرها، بتوبته وصدقه وإخلاصه، ويقول بعد ذلك: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] هذا يقوله الرجل والمرأة بعد الفريضة، جاء في الأحاديث عن الرسول ﷺ أنه قال: من قالها بعد كل صلاة لم يمنعه من دخول الجنة إلا أن يموت والحديث فيه كلام لأهل العلم، ولكن بعض طرقه صحيحة، فالأرجح أنه ثابت، وأن هذه القراءة مستحبة، وهذه الآية يقال لها: آية الكرسي، وهي أعظم آية في كتاب الله، هي أفضل آية وأعظم آية في كتاب الله: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُُّ الْقَيُّومُ [البقرة:255] هذه يقال لها: آية الكرسي، وهي أعظم آية وأفضل آية، يستحب أن تقال بعد الصلاة بعد السلام بعد هذا الذكر، ويستحب أن تقال أيضاً عند النوم، وهي من أسباب حفظ الله للعبد من الشيطان، فهي آية عظيمة ينفع الله بها العبد، وهي من أسباب دخول الجنة إذا قالها بعد كل صلاة في الفريضة، بعد الظهر والعصر والمغرب والعشاء والفجر، وهكذا يقولها عند النوم وتكون من أسباب حفظه، يقول النبي ﷺ: من قالها لم يزل عليه من الله حافظ، ولا يقربه الشيطان حتى يصبح وهذا فضل عظيم، كذلك يستحب له بعد هذا أن يقرأ: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين المصلي الإمام والمنفرد والمأموم بينه وبين نفسه: قُلْ هُوَ اللَّهُُ أَحَدٌ [الإخلاص:1] .. قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] .. قُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] مرةً واحدة، بعد الظهر والعصر والعشاء.\nأما بعد المغرب والفجر فيقولها ثلاثاً يقرأ هذه السور الثلاث ثلاثاً: قُلْ هُوَ اللَّهُ أَحَدٌ ثلاثاً: قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ثلاثاً: قُلْ أَعُوذُ بِرَبِِّ النَّاسِ ثلاثاً بعد الفجر والمغرب.\nويستحب أيضاً فيها بعد الفجر والمغرب زيادة أن يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير عشر مرات زيادة بعد الفجر والمغرب، جاء في ذلك عدة أحاديث عن النبي ﷺ، والله جل وعلا هو المسؤول أن يوفقنا جميعاً للتأسي به ﷺ، والمحافظة على سنته، والاستقامة على دينه حتى نلقاه سبحانه.","link":"https://binbaz.org.sa/fatwas/6154/استواء-الرجل-والمراة-في-صفة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_112/11201.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":8651,"question":"في آخر رسالة الأخ عيظة محمد يقول: ما حكم من صلى بالدخان في جيبه وهو ساه أو متعمد؟","title":"حكم الدخان وحكم من صلى وهو في جيبه","answer":"الجواب: الدخان من المحرمات الضارة بالإنسان، وهو من الخبائث التي حرمها الله عز وجل، وهكذا بقية المسكرات من سائر أنواع الخمور لما فيها من المضرة العظيمة واغتيال العقول، وهكذا القات المعروف في اليمن محرم لما فيه من المضار الكثيرة، وقد نص الكثير من أهل العلم على تحريمه، والدخان فيه خبث كثير، وضرر كثير فلا يجوز شربه ولا بيعه ولا شراؤه ولا التجارة فيه، وقد قال جل وعلا في كتابه العظيم: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] فأمر الله نبيه ﷺ أن يقول للناس: أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] فلم يحل الله لنا الخبائث، والدخان ليس من الطيبات بل هو خبيث الطعم وخبيث الرائحة.. عظيم الضرر بالإنسان، وهو من أسباب موت السكتة، ومن أسباب أمراض كثيرة فيما ذكر الأطباء منها السرطان.\nفالمقصود: أنه مضر جداً وخبيث وحرام البيع والشراء، وحرام التجارة، أما الصلاة وهو في الجيب فلا يضر الصلاة، الصلاة صحيحة؛ لأنه شجر ليس بنجس، ولكنه محرم ومنكر كما سبق، ولكن لو صلى وهو في جيبه عامداً أو ساهياً فصلاته صحيحة، لكن يجب عليه الحذر منه والتوبة إلى الله مما سلف من تعاطيه، رزق الله المسلمين العافية منه ومن سائر ما يغضبه سبحانه.\nومما جاء في هذا المعنى قوله سبحانه في وصف النبي ﷺ: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157] فصرح سبحانه في هذه الآية أن نبينا ﷺ يحرم علينا الخبائث وهي ضد الطيبات، والطيبات أباحها الله لنا ويسرها لنا فضلاً منه سبحانه وتعالى، والخبائث من الخمور والميتات والخنازير والكلاب وأشباهها مما حرم الله، ومن ذلك الدخان وأشباهه، هذه خبائث حرمها الله على عباده تطهيراً لهم وحماية لهم مما يضرهم، فالحمد لله على ذلك. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6788/حكم-الدخان-وحكم-من-صلى-وهو-في-جيبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21303.mp3","categories":["مسائل متفرقة في الصلاة","الأطعمة والأشربة"]},{"id":8939,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمعة (هـ. ف. م) من المنطقة الشرقية أختنا تسأل مجموعة من الأسئلة من بينها سؤال يقول: ما حكم الصلاة بالملابس المطبوع عليها صور؟","title":"حكم الصلاة بالملابس المطبوع عليها صور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالصلاة في الملابس التي فيها صور من صور الحيوانات لا تجوز؛ لأن الرسول ﷺ لما رأى عند عائشة رضي الله عنها سترًا فيه تصاوير غضب وهتكه، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم ولما رأى صورًا في جدران الكعبة محاها عليه الصلاة والسلام ونهى عن الصور في البيت وقال لـعلي: لا تدع صورة إلا طمستها ولا قبرًا مشرفًا إلا سويته.\nفالخلاصة: أنه لا يجوز للمؤمن ولا للمؤمنة الصلاة في ثوب فيه تصاوير، ولا يجوز أيضًا للمؤمنة أن تجعل لأولادها وأطفالها ملابس فيها تصاوير كل هذا لا يجوز، وإذا أزيل الرأس كفى، إذا جعل على الرأس رقعة خيط على الرأس رقعة تخفيه فلا بأس زال المحذور والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7097/حكم-الصلاة-بالملابس-المطبوع-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17201.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":9123,"question":"السؤال الثالث في رسالة الأخ (ن. م) من مدينة الرمادي يقول فيه: ما حكم من استمع إلى الغناء ثم صلى أفيدونا جزاكم الله خيراً؟","title":"حكم صلاة من استمع إلى الغناء قبلها","answer":"الجواب: الاستماع إلى الغناء منكر لا يجوز، ولكنه لا يمنع صحة الصلاة فقد جمع بين شر وخير، فإذا استمع الغناء أو آلات الملاهي ثم صلى فقد جمع شراً وخيراً فصلاته إذا استوفت شروطها صحيحة إذا أداها كما أمر الله صحيحة وعليه التوبة من استماعه للغناء، قال الله : وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ [لقمان:6] قال أكثر المفسرين رحمة الله عليهم: إن لهو الحديث هو: الغناء، قال بعضهم: ويلحق به آلات اللهو وكل صوت منكر، فالله جل وعلا ذم من فعل هذا قال: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ [لقمان:6] وهذا على سبيل الذم والعيب لهم والتحذير من هذا العمل.\nفلا يجوز للمسلم أن يتسمع الغناء لأنه يمرض القلوب ويصدها عن ذكر الله ويسبب تثاقلها عن سماع القرآن، ويسبب أيضاً الاستهزاء بآيات الله، فالخطر فيه عظيم.\nفالواجب على المؤمن والمؤمنة أن يحذرا ذلك، وأن يبتعدا عن استماع الأغاني وآلات الملاهي، حذراً من مرض القلوب وحذراً من غضب الله ، ولكن الصلاة مع هذا صحيحة، فالمغني والمستمع للغناء صلاتهما صحيحة إذا أدياها كما أمر الله عز وجل. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7281/حكم-صلاة-من-استمع-الى-الغناء-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_228/28806.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":9327,"question":"وهذه رسالة وردت إلى البرنامج من السائل فضل عبد القادر يمني الجنسية، يقول في رسالته: هل يجوز للرجل أن يصلي في قميص مصور عليه صور حيوانات كالخيول أو رسوم أخرى وما شابه ذلك، أفيدونا أفادكم الله؟","title":"حكم الصلاة بثياب عليها تصاوير","answer":"الجواب: ليس للمسلم أن يصلي في ملابس فيها صور، سواء كانت صور بني آدم ، أو كانت صوراً أخرى من ذوات الأرواح كالخيل أو الإبل أو الطيور، الرسول ﷺ قال: لا تدع صورة إلا طمستها، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم، ولما رأى ستراً على باب عائشة فيه تصاوير هتكه وقطعه عليه الصلاة والسلام وتغير وجهه عليه الصلاة والسلام، فلا يجوز للمسلم ولا للمسلمة لبس المصورات من ذوات الأرواح، لا قمص ولا أردية ولا عمامة ولا غير ذلك، ولا جعلها ستور على البيوت، كل هذا ممنوع.\nوأما إذا كان الذي فيه صور يوطأ ويمتهن كالبسط التي تفرش في المنازل فلا بأس أن توضع مما فيها صور، وهكذا الوسائد والمتكآت، كل هذه يعفا عنها؛ لأنها ممتهنة غير معظمة، وهكذا الكنبات التي يجلس عليها والكراسي كلها ممتهنة. نعم.\nالمقدم: بارك الله فيكم، لكن لو صلى في هذا القميص، هل تبطل صلاته؟\nالشيخ: فيه خلاف بين العلماء منهم من قال: تبطل؛ لأنه لبس شيئاً منهي عنه، والقول الآخر: لا تبطل. وهو الصحيح؛ لأنه منهي عنه مو هو بالصلاة وحدها، منهي عنه دائماً، لا يلبسه دائماً، والشيء الذي نهي عنه لا لأجل الصلاة بل لأنه في نفسه محرم لا يبطل الصلاة، وهكذا الثوب المغصوب، الصحيح لا يبطل الصلاة، ما دام ساتر العورة لا تبطل به الصلاة، لكن صاحبه يأثم في لبسه ولو ما صلى به، يأثم، فهو منهي عنه مطلقا في الصلاة وغيرها، بخلاف الشيء المنهي عنه في الصلاة فقط، كالثوب الذي فيه نجاسة إذا صلى فيه متعمداً بطلت صلاته؛ لأنه منهي عنه في الصلاة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7493/حكم-الصلاة-بثياب-عليها-تصاوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23710.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":9799,"question":"له استفسار ثانٍ يقول فيه: رجل أصم أبكم يصلي لا يعرف شروط الصلاة، هل تصح صلاته؟","title":"حكم صلاة أصم أبكم لا يعرف شروط الصلاة","answer":"الجواب: يصلي على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فإن أمكن تعليمه بالإشارة أو بأي شيء يعلم، أما إذا لم يمكن فلا يلزمه إلا ما علم والله يقول سبحانه: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15]، وإذا أمكن تعليمه بالكتابة إذا كان ينظر ويقرأ يعلم بالكتابة؛ لأن هذا أمر لازم تعليم الجاهل أمر لازم على المسلمين وعلى طلبة العلم فيعلم بالطريقة التي تمكن من كتابة أو إشارة حتى تبرأ الذمة وحتى يعرف دينه، وإذا لم يتيسر أنه يعلم شيئًا من ذلك لأنه لا يقرأ ولأنه لا يفهم الإشارة فالمسلمون الذين حوله معذورون، وهو قد يعذر إذا كان ما فرط سابقًا وأنه خلق على هذه الحال فقد يعذر لكونه لم يستطع إلا ما رآه وشاهده من الناس.نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7966/حكم-صلاة-اصم-ابكم-لا-يعرف-شروط-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19615.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":10043,"question":"المستمعة فيحاء المطيري من عفيف في المملكة بعثت تسأل وتقول: هل تجوز الصلاة بالثوب الأبيض الذي فيه قليل من ألوان الأخرى والذي تتحجب به المرأة عند صلاتها؟","title":"حكم الصلاة في الثوب الأبيض الملون بغيره","answer":"الجواب: نعم تصح الصلاة في الثوب، لكن إذا كان يشبه ملابس الرجال فالواجب عليها تركه، أما إذا كان من ملابس النساء ومن اللباس اللاتي يعتدنه فلا بأس بذلك صلاتها صحيحة ..... صحيح، أما إذا كان لا، فيه تشبه فالصلاة صحيحة لكن ينبغي لها أن تبتعد عن ذلك وأن تترك الشيء الذي يشبه لباس الرجال؛ لأن الرسول ﷺ قال: لعن الله المرأة تلبس لبسة الرجل ولعن الله الرجل يلبس لبسة المرأة فالتشبه من الرجال بالنساء ممنوع وهكذا النساء بالرجال ممنوع، فالواجب على الجميع تقوى الله وعدم التشبه. نعم.\nالمقدم: جزاكم الله خيرًا، إذا صنع هذا القماش خصيصًا للنساء؟\nالشيخ: إذا كان لا يلبسه الرجال فلا يضر، إن كان على طريقة خاصة للنساء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8212/حكم-الصلاة-في-الثوب-الابيض-الملون-بغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33211.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":10310,"question":"يخلط مع كثير من الناس بين صلاة الفجر وصلاة الصبح، كأنهم يجعلونها قسمين، فهل من توجيه جزاكم الله خيراً؟","title":"الفرق بين صلاة الفجر وصلاة الصبح","answer":"الجواب: صلاة الصبح هي صلاة الفجر، فليس هناك فرق صلاة الصبح هي صلاة الفجر، ليس هناك صلاتان، صلاة الفجر هي صلاة الصبح وهي ركعتان فريضة بإجماع المسلمين بعد طلوع الفجر وقبل طلوع الشمس ركعتان، والأفضل أن تؤدى بغلس قبل الإسفار الكامل، يؤديها الرجل في الجماعة إلا المريض الذي لا يستطيع يصليها في بيته والمرأة كذلك تصليها في البيت قبل الشمس ولا يجوز تأخيرها إلى بعد طلوع الشمس، بل يجب أن تؤدى قبل طلوع الشمس والأفضل في أول الوقت، في وقت الغلس مع بيان الفجر واتضاح الفجر وانشقاقه، يقال لها: صلاة الفجر ويقال لها: صلاة الصبح. ويجب على المسلم أن يعتني بها ويحافظ عليها في وقتها ولا يجوز تأخيرها إلى طلوع الشمس كما يفعل بعض الناس، يؤخرها حتى يقوم للعمل هذا منكر عظيم وهو كفر عند جمع من أهل العلم نسأل الله العافية.\nفالواجب الحذر وأن يحافظ عليها في وقتها الرجل والمرأة جميعاً.\nويشرع أن يؤدي قبلها ركعتين سنة راتبة قبلها ركعتين سنة راتبة، كان النبي ﷺ يفعلها ويحافظ عليها عليه الصلاة والسلام، تقول عائشة رضي الله عنها : لم يكن النبي ﷺ على شيء من النوافل أشد تعهداً منه على ركعتي الفجر وكان يقول ﷺ: ركعتا الفجر خير من الدنيا وما عليها.\nفينبغي المحافظة عليها سنة الفجر ركعتين خفيفتين يقرأ فيهما بالفاتحة وقل يا أيها الكافرون في الأولى وفي الثانية الفاتحة وقل هو الله أحد هذا هو الأفضل، أو يقرأ بآية البقرة : قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى إِبْرَاهِيمَ ... [البقرة:136] الآية، في الأولى، وفي الثانية آية آل عمران : قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ ... [آل عمران:64] إلى آخرها، فعل النبي هذا وهذا عليه الصلاة والسلام، وإن قرأ بغير ذلك فلا بأس، إن قرأ مع الفاتحة بغير ذلك فلا حرج، لكن كونه يقرأ بما قرأ به النبي ﷺ هذا أفضل، ويقرأ بهاتين السورتين أيضاً في سنة المغرب بعد الفاتحة قل يا أيها الكافرون في الأولى وقل هو الله أحد في الثانية، ويقرأ بهما أيضاً في ركعتي الطواف، كل هذا فعله النبي عليه الصلاة والسلام، يقرأ بهاتين السورتين بعد الفاتحة في سنة الفجر وسنة المغرب وسنة الطواف، وإن قرأ في بعض الأحيان في سنة الفجر بآية ثانية في البقرة : قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا ... [البقرة:136] وبآية آل عمران في الثانية وهي قوله سبحانه: قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ ... [آل عمران:64] الآية، فهذا أيضاً سنة فعله النبي ﷺ وإن قرأ في هذه الركعات بغير ذلك فلا حرج؛ لقوله تعالى: فَاقْرَءُوا مَا تَيَسَّرَ مِنَه [المزمل:20]. نعم.","link":"https://binbaz.org.sa/fatwas/8486/الفرق-بين-صلاة-الفجر-وصلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31312.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":10326,"question":"يقول: إذا كان الإنسان إماماً، فهل يجوز له الدعاء في سجوده مثل: رب اغفر لي ذنبي كله دقه وجله أوله وآخره وغير ذلك، كذلك الدعاء بعد التشهد الأخير مثل قوله: أعوذ بالله من عذاب جهنم وعذاب القبر وفتنة المحيا وفتنة المسيح الدجال ؟ وهل يستحب للإمام وغيره في الصلاة المفروضة الدعاء في السجود وبعد التشهد الأخير والزيادة في التسبيح في الركوع والسجود أم أنه يقتصر على أدنى الكمال؟","title":"ما يستحب من الدعاء في الصلاة ومواطنه","answer":"الجواب: المشروع للجميع الإمام والمنفرد والمأموم، يشرع للجميع الدعاء في السجود يقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم، يعني: حري أن يستجاب لكم، رواه مسلم في الصحيح، ويقول أيضاً عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء خرجه مسلم في الصحيح أيضاً. فالسنة للجميع الإمام والمأموم والمنفرد والرجل والمرأة الإكثار من الدعاء في السجود، ومن دعائه ﷺ في السجود: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره رواه مسلم في الصحيح من دعاء النبي عليه الصلاة والسلام. ومن الدعاء الحسن في السجود أن يقول: اللهم اغفر لي ولوالدي ولجميع المسلمين، ويقول: اللهم أصلح قلبي وعملي وارزقني الفقه في ديني، ويقول: اللهم يا مقلب القلوب! ثبت قلبي على دينك، ومن التسبيح: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي.. سبوح قدوس رب الملائكة والروح ويكرر ذلك ما تيسر. ويقول في السجود أيضاً: سبحان ربي الأعلى، سبحان ربي الأعلى، لا يقتصر على الواجب مرة بل يزيد ثلاثاً أو خمساً أو سبعاً هذا أفضل وهكذا في الركوع يقول: سبحان ربي العظيم سبحان ربي العظيم سبحان ربي العظيم، وأدنى الكمال ثلاثة وإن زاد فهو أفضل خمساً وسبعاً وعشراً فهو أفضل، لكن يتحرى الإمام ألا يشق على الناس تكون صلاته وسطاً ليس فيها تطويل يشق على الناس ولا تخفيف يخل بالواجب ولكن بين ذلك. ويكثر من قوله في الركوع والسجود: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، سبوح قدوس رب الملائكة والروح، تقول عائشة رضي الله عنها: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي متفق على صحته، ويقول ﷺ في السجود والركوع: سبوح قدوس رب الملائكة والروح، ويدعو في التشهد الأخير بعد الصلاة على النبي ﷺ يدعو: اللهم إني أعوذ بك من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال اللهم أعني على ذكرك وشكرك وحسن عبادتك اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني أنت المقدم وأنت المؤخر لا إله إلا أنت، ومن الدعاء المشروع: اللهم إني ظلمت نفسي ظلماً كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرةً من عندك وارحمني إنك أنت الغفور الرحيم هذا دعاء عظيم مشروع في السجود وفي التشهد قبل السلام، ومن الدعاء المشروع قبل السلام: اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ من فتنة الدنيا ومن عذاب القبر. وإن دعا بغير هذه من الدعوات الطيبة فكله حسن قبل أن يسلم. لكن إذا كان إماماً لا يطول تطويلاً كثيراً على الناس حتى لا يشق عليهم، أما المأموم تبع إمامه يدعو حتى يسلم إمامه، والمنفرد له أن يطول ما شاء؛ لأنه ليس خلفه ما يشق عليه، فله أن يصلي كيف شاء مع مراعاة الأمر الشرعي في كل شيء. نعم. المقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8493/ما-يستحب-من-الدعاء-في-الصلاة-ومواطنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31406.mp3","categories":["مسائل متفرقة في الصلاة","الأدعية والأذكار"]},{"id":10379,"question":"هل ترشدون المستمعين سماحة الشيخ إلى كتب معينة يقرءون فيها صفة صلاة النبي ﷺ؟","title":"ما الكتب التي ألفت في صفة صلاة النبي؟","answer":"الجواب: نعم، في كتاب لـابن القيم رحمه الله في صفة الصلاة، كتاب جيد، وفي صفة الصلاة للإمام أحمد بن حنبل رحمه الله وفي مثل الترغيب والترهيب، ورياض الصالحين، والجواب الكافي، أرشد إلى أشياء كثيرة رحمة الله عليهم، لكن المؤمن يتحرى كتب الحديث، كتب الحديث مثل رياض الصالحين يعتني، ومثل الصحيحين البخاري ومسلم، ومثل السنن الأربع، لأن هذه اعتنت بالأحاديث، ورياض الصالحين نقل منها، وهكذا مثل الترغيب والترهيب ومثل غيره مثل صفة الصلاة للشيخ ناصر الدين الألباني، ومثل أشباهه الذين اعتنوا بالأحاديث.\nالمقدم: أذكر أن لسماحتكم رسالة في هذا الباب سماحة الشيخ؟\nالشيخ: لنا رسالة في هذا، بل رسائل في هذا.\nالمقدم: رسائل في هذا الموضوع؟\nالشيخ: نعم.\nالمقدم: في صفة صلاة النبي ﷺ؟\nالشيخ: نعم وهي مطبوعة وتوزع.\nمداخلة: الحمد لله، منتشرة من أرادها يجدها سماحة الشيخ.\nالشيخ: نعم. نعم.\nالمقدم: بارك الله فيكم وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8551/ما-الكتب-التي-الفت-في-صفة-صلاة-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28004.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":10386,"question":"يقول: بعض أفراد عائلتي يصلون في البيت دون المساجد، وفي بعض الأوقات وأحياناً تكون هناك مناسبة غداء فيحين وقت الصلاة متزامناً مع وقت الغداء فماذا نفعل، أنقدم الأكل أم الصلاة جزاكم الله خيرًا؟","title":"حكم الصلاة بحضرة الطعام","answer":"الجواب: الواجب تقديم الصلاة إذا كان الغداء ما قدم، تقدمون الصلاة ثم ترجعون، صلاة العصر أو صلاة الظهر، أما إذا كان قد قدم بين أيديكم ابدءوا به، لكن كونكم تتحرون الوقت هذا ثم يقدم لا، ابدءوا بالصلاة، لكن لو كان قدم بين أيديكم ثم أذن المؤذن ابدءوا به مثل ما قال ﷺ: إذا قدم العشاء فابدءوا به قبل أن تصلوا المغرب، وقال ﷺ: لا صلاة بحضرة الطعام ولا هو يدافعه الأخبثان، فإذا قدم فالمشروع البداءة به، أما إذا كان ما قدم فابدءوا بالصلاة ثم اطلبوه بعد ذلك.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8558/حكم-الصلاة-بحضرة-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28011.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":10494,"question":"رسالة بعثت بها إحدى الأخوات المستمعات تقول المرسلة (م. م. م) تسأل وتقول: هل يجوز أن يتكلم شخص مع المصلي أثناء صلاته بأن يوصيه مثلًا أن يفعل كذا أو لا يفعل شيء جزاكم الله خيرًا؟","title":"حكم التحدث مع المصلي للحاجة","answer":"الجواب: لا حرج في ذلك، إذا دعت الحاجة إلى هذا كأن يقول له: اتق الله لا تعجل في صلاتك، اطمئن في صلاتك، أو يقول: إذا صليت فلا تخرج سوف يأتي فلان وفلان، أو ما أشبه ذلك من الحاجات العارضة لا بأس أن يتكلم معه وهو يصلي. نعم.\nالمقدم: الحمد لله، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8669/حكم-التحدث-مع-المصلي-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28202.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":10600,"question":"هل يجوز للمرأة أن تصلي وهي متزينة بالذهب والمكياج؟","title":"حكم صلاة المرأة حال تزينها بالذهب والمكياج","answer":"الجواب: نعم، لها أن تصلي وهي متزينة بالذهب، والملابس الجميلة، والمكياج إذا كان المكياج نظيفاً طاهراً ليس به نجاسة فلا حرج في ذلك، لها أن تصلي مع الخشوع ومع الإقبال على الله عز وجل، الله جل وعلا يقول سبحانه في كتابه العظيم: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] فالمؤمن مشروع له أن يصلي بزينته في المساجد بالملابس الحسنة والعمامة الحسنة، وهكذا المرأة إذا صلت في ملابس جميلة لا حرج .. إذا كانت مستورة عن الرجال الأجانب ما عندها أجانب فلا حرج في ذلك والحمد لله، والمكياج زينة للوجه جمال للوجه إذا كان لا يضره، يعني: مسحت وجهها بشيء مزين وينوره ولكنه لا يضره فلا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8782/حكم-صلاة-المراة-حال-تزينها-بالذهب-والمكياج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32609.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":10609,"question":"هل يجوز للمرأة أن تصلي وهي متزينة بالذهب والمكياج؟","title":"حكم صلاة المرأة حال تزينها بالذهب والمكياج","answer":"الجواب: نعم، لها أن تصلي وهي متزينة بالذهب، والملابس الجميلة، والمكياج إذا كان المكياج نظيفاً طاهراً ليس به نجاسة فلا حرج في ذلك، لها أن تصلي مع الخشوع ومع الإقبال على الله عز وجل، الله جل وعلا يقول سبحانه في كتابه العظيم: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] فالمؤمن مشروع له أن يصلي بزينته في المساجد بالملابس الحسنة والعمامة الحسنة، وهكذا المرأة إذا صلت في ملابس جميلة لا حرج .. إذا كانت مستورة عن الرجال الأجانب ما عندها أجانب فلا حرج في ذلك والحمد لله، والمكياج زينة للوجه جمال للوجه إذا كان لا يضره، يعني: مسحت وجهها بشيء مزين وينوره ولكنه لا يضره فلا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8782/حكم-صلاة-المراة-حال-تزينها-بالذهب-والمكياج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32609.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":10779,"question":"سؤاله الثاني يقول: هل يجوز الصلاة في الظلام؟الشيخ: إيش؟المقدم: هل تجوز الصلاة في الظلام؟","title":"حكم الصلاة في الظلام","answer":"الشيخ: نعم، لا بأس لا بأس أن يصلي الإنسان في محل مظلم لا بأس، كان النبي صلى الله عليه وسلم يصلي في حجرته وليس فيها مصابيح. نعم.","link":"https://binbaz.org.sa/fatwas/8956/حكم-الصلاة-في-الظلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35002.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":11043,"question":"السائل لافي علي من العلا يقول: بأنني كنت مريضًا، وكتب لي أحد الإخوان حجابًا ولبسته، هل تصح صلاتي في ذلك وأنا أرتدي الحجاب؟ وهل الحجاب محرم يا سماحة الشيخ؟","title":"حكم صلاة من تعلق تميمة","answer":"الجواب: الصلاة صحيحة، والحجاب يقطع ويزال، الرسول ﷺ نهى عن التمائم، وهذا من التمائم، يقول ﷺ: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له والتميمة: يسمونها الحجاب، ويسمونها الجامعة، ويسمونها أسماء أخرى. فالمقصود: أنه لا يعلق، لا خيط ولا خرقة، ولا شيء يقرأ ويعلق، كل هذا يسمى حجابًا، ويسمى تميمة، لا يجوز تعليقه، بل الواجب قطع ذلك أما الصلاة صحيحة.","link":"https://binbaz.org.sa/fatwas/9221/حكم-صلاة-من-تعلق-تميمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28725.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":11550,"question":"أخيرًا يسأل ويقول: رجل يشرب الخمر بحجة أنها غذاء للدم كما يزعم، وهي لا تسكره، وهو يصلي فما حكم صلاته؟ وما حكم ما يفعل؟ جزاكم الله خيرًا.","title":"حكم من شرب الخمر بحجة عدم الإسكار وحكم صلاته","answer":"الجواب:  إذا كانت تسكر غيره فيها مادة السكر، فإنه يحرم عليه شربها ولو كانت لا تسكره؛ لأن بعض الناس إذا اعتادها قد لا يسكر؛ فهي محرمة عليه سكر أو لم يسكر، إذا كانت من شأنها الإسكار لغيره؛ لأنها خمر، فالواجب عليه تركها والحذر منها. الشيخ: تعيد سؤاله. المقدم: يقول: رجل يشرب الخمر بحجة أنها غذاء للدم، وهي لا تسكره، وهو يصلي، فما حكم صلاته؟ وما حكم ما يفعل؟ الشيخ: وليست غذاء للدم، ولا غيره، سئل النبي ﷺ قال له رجل: يا رسول الله! إني أصنع الخمر للدواء، قال -عليه الصلاة والسلام-: إنها ليست بدواء، ولكنها داء خرجه مسلم في صحيحه، ولكن هذه أوهام يتوهمون أنها تنفعهم، وهذا من تزيين الشيطان، حتى ولو فرضنا أنه قال طبيب، قول النبي مقدم -عليه الصلاة والسلام- فلا يجوز شربها، لا للدواء، ولا لغير الدواء، ولو قال ألف طبيب: إنها تنفع، لا يجوز شربها لا للتداوي ولا غيره، هي داء عضال، ومنكر عظيم، ومن كبائر الذنوب، وليس لأحد أن يشربها لا للتداوي، ولا لغير التداوي، أسكرته، أو لم تسكره، إذا كانت من شأنها أن تسكر بغيره، ولكنه بسبب اعتياده لها قد لا تسكره بعض الأحيان، هذا لا يحلها له، هي حرام عليه مطلقًا، ولو لم تسكره، نسأل الله السلامة. نعم. المقدم: إذًا صلاته؟ الشيخ: صلاته صحيحة إذا كان صلى وهو عاقل، قد ذهب عنه السكر يتوضأ ويصلي، أما في حال السكر صلاته غير صحيحة؛ لأنه غير عاقل.","link":"https://binbaz.org.sa/fatwas/9733/حكم-من-شرب-الخمر-بحجة-عدم-الاسكار-وحكم-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_296/29606.mp3","categories":["مسائل متفرقة في الصلاة","الأطعمة والأشربة"]},{"id":11658,"question":"يسأل ويقول: سمعت من يقول: بجواز الصلاة بالأحذية فهل هذا صحيح؟","title":"حكم الصلاة بالأحذية والخفاف","answer":"الجواب:  نعم، قد صح عن رسول الله ﷺ أنه صلى في نعليه، وكان يصلي في خفيه أيضًا يمسح عليهما، ويصلي فيهما يوم وليلة -عليه الصلاة والسلام- وفي السفر ثلاثة أيام بلياليها، والخفان: مثل النعلين. وكان يصلي في نعليه -عليه الصلاة والسلام-: وفي بعض الصلوات صلى وفي نعليه خبث لم يعلمه، فجاءه جبرائيل، وأخبره بذلك؛ فخلع نعليه، واستمر في صلاته، وخلع الناس نعالهم لما خلع نعليه، فلما سلم سألهم، قال: لماذا خلعتم نعالكم؟ قالوا: رأيناك يا رسول الله خلعت نعليك؛ فخلعنا نعالنا، قال: إن جبريل أتاني فأخبرني أن بهما قذرًا، فإذا أتى أحدكم المسجد؛ فلينظر في نعليه وفي لفظ: فليقلب نعليه، فإن رأى فيهما قذرًا فيمسحه، ثم ليصل فيهما. فدل ذلك على أنه لا حرج في الصلاة فيهما، لكن بعد أن يعتني بهما قبل المسجد، يعتني قبل دخول المسجد، وينظر فإن كان فيهما أذى أزاله، ونقاهما ونظفهما بالتراب، ثم يصلي فيهما، ولا حرج في ذلك. لكن في هذه الأوقات التي صار الناس يفرشون المساجد بفرش يخشى أن يوسخها بالنعلين، فإذا جعلهما عند باب المسجد حتى لا يوسخ الفرش كان هذا أحسن -إن شاء الله- درءًا للمفسدة؛ لأن الكثير من الناس، أو أكثرهم قد لا ينظر في نعليه، وقد لا يعتني، فينبغي في هذا أن يحتاط، ويجعلها خارج الفرش، ويصلي مكشوف القدمين، إلا إذا كان عليه الخفان وقد مسح عليهما، فيصلي فيهما، ولكن يعتني بهما قبل دخول المسجد، يعني إذا كان قد مسح عليهما لو خلعهما بطلت طهارته؛ فلا يخلعهما، يصلي فيهما، ولكن قبل ذلك يعتني بهما عند دخول المسجد، حتى لا يكون فيهما أذى يوسخ الفرش، لا تراب ولا طين، ولا غير ذلك مما يؤذي، مما يوسخ، يعتني بذلك، أما النعل فبالإمكان خلعها، وسهل خلعها، وإن نظفها وصلى فيها؛ فلا حرج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9841/حكم-الصلاة-بالاحذية-والخفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29810.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":11693,"question":"إحدى الأخوات رمزت إلى اسمها بالحروف: (ن. ز. ر) تقول: هل يجوز للمرأة أن تصلي وشعرها ملفوف؟","title":"حكم صلاة المرأة معقودة الشعر","answer":"الجواب:  الأحاديث في النهي عن عقد الشعر عامة، والأحوط لها ترك العقد، ترخي رآملها وتترك العقد، هذا هو الأحوط أخذًا بالعموم، أخذًا بعموم الأحاديث التي فيها النهي عن عقد الرأس وقت الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9878/حكم-صلاة-المراة-معقودة-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39108.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":11981,"question":"المستمع محمد صالح أحمد من جيزان بعث يسأل ويقول: أرجو أن توضحوا لنا كيفية صلاة الرسول ﷺ؟ لتعم الفائدة، ولأننا نرى أناسًا يزيدون أقوالًا، أو أفعالًا، فنرجو التوضيح، جزاكم الله خيرًا.","title":"صفة صلاة النبي ﷺ من التكبير إلى التسليم","answer":"الجواب:  صلاة الرسول ﷺ أعدل صلاة، وأكمل صلاة -عليه الصلاة والسلام- فيقول: صلوا كما رأيتموني أصلي كان يصلي صلاة فيها الطمأنينة، وفيها الركود، والخشوع، عليه الصلاة والسلام: يبدؤها بالتكبير: الله أكبر، ثم يستفتح قبل القراءة، والأغلب يستفتح بقوله: اللهم باعد بيني وبين خطاياي، كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالماء والثلج والبرد، هكذا جاء في الصحيحين من حديث أبي هريرة  أنه سأله عن سكوته بعد التكبير؛ فقال: إنه يقول هذا الدعاء، في صلاة الفريضة، وهكذا النوافل، وإن استفتح بالحديث الآخر: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك فحسن، كله طيب. ثم يقول: أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ثم يقرأ الحمد، الفاتحة يقرؤها قراءة مرتلة ومطمئنة، يعطي الحروف حقها، فإذا قال: وَلا الضَّالِّينَ [الفاتحة:7] قال: آمين، في الجهرية، يجهر كالمغرب والعشاء والفجر والجمعة، وفي السر يسرها بينه وبين نفسه، ثم يقرأ ما تيسر من السور، أو الآيات، كان يطول في الفجر، يقرأ من طوال المفصل، وربما قرأ بالستين آية والمائة الآية في الركعتين، وربما قرأ بـ(ق) وأشباهها كالطور والذاريات في الفجر، وربما قرأ بـ قَدْ أَفْلَحَ الْمُؤْمِنُونَ [المؤمنون:1] في الركعتين، وفي المغرب تارة بالطوال، فقد قرأ بالطور في المغرب، وقد قرأ بالأعراف في الركعتين في بعض الأحيان، وقرأ بالمرسلات في المغرب، والغالب يقرأ بالقصار، قصار المفصل، مثل: إِذَا زُلْزِلَتِ وَالْعَادِيَاتِ وإِذَا السَّمَاءُ انفَطَرَتْ وَالسَّمَاءِ وَالطَّارِقِ وما أشبه ذلك: وَالشَّمْسِ وَضُحَاهَا فالمؤمن يفعل كما فعل النبي ﷺ تارة يطول، وتارة يقرأ بالقصار في المغرب. وفي العشاء والظهر والعصر بالأوساط، يقرأ بالأوساط مثل: لَمْ يَكُنِ، مثل: وَالسَّمَاءِ ذَاتِ الْبُرُوجِ إِذَا الشَّمْسُ كُوِّرَتْ عَبَسََ وَتَوَلَّى، وأشباه ذلك، في العشاء، وفي الظهر وفي العصر، وتكون الظهر أطول بعض الشيء من العصر، هذه سنته، عليه الصلاة والسلام. وفي الركوع يطمئن ولا يعجل، ويأتي بالتسبيح: (سبحان ربي العظيم، سبحان ربي العظيم) خمس مرات، سبع مرات، (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) في الركوع، (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) (سبوح قدوس رب الملائكة والروح) ويركد يضع يديه على ركبتيه، يسوي رأسه مع ظهره معتدلًا مطمئنًا، ثم يرفع رأسه قائلًا: (سمع الله لمن حمده) إذا كان إمامًا، أو منفردًا، وإن كان مأمومًا يرفع يقول: (ربنا ولك الحمد) أو (اللهم ربنا لك الحمد) ثم يكمل: (حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد) وربما زاد -عليه الصلاة والسلام- بعد هذا: «أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد» يعني: يطول في هذا الركن يعتدل، ويطمئن. ثم يسجد، ويعتدل في السجود على أعضائه السبعة: أطراف قدميه وركبتيه وكفيه ووجهه، يجعل جبهته وأنفه على الأرض، ويعتدل، يرفع بطنه عن فخذيه، يجافي عضديه عن جنبيه، يرفع ذراعيه عن الأرض يعتمد على كفيه، يطمئن ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ويكررها خمسًا، أو سبعًا، أو عشرًا، ويقول: (اللهم اغفر لي وارحمني واهدني واجبرني وارزقني) (اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره) (اللهم يا مقلب القلوب ثبت قلبي على دينك) . يدعو في السجود، كان النبي ﷺ يدعو في السجود، ويقول -عليه الصلاة والسلام-: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، ويقول -عليه الصلاة والسلام-: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء. فالسنة أن يطمئن في السجود، ويكثر من الدعاء في السجود مع قوله: سبحان ربي الأعلى، سبحان ربي الأعلى ثلاث مرات، خمس مرات، سبع مرات، في الركوع: سبحان ربي العظيم، في السجود: سبحان ربي الأعلى، مع الدعاء مع قوله: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) (سبوح قدوس رب الملائكة والروح) (سبحان ذي الجبروت والملكوت والكبرياء والعظمة) لا يعجل. ثم يجلس بين السجدتين، ويطمئن، ويركد، ولا يعجل، يقول: (رب اغفر لي، رب اغفر لي، رب اغفر لي، اللهم اغفر لي وارحمني، واهدني واجبرني وارزقني وعافني). بين السجدتين يطمئن، ويجلس على رجله اليسرى، يفرشها، ويجلس عليها، وينصب اليمنى إذا استطاع ذلك، ثم يسجد الثانية مثل الأولى، يطمئن فيها، ويقول فيها مثلما قال في الأولى، هكذا صلاة النبي -عليه الصلاة والسلام- وفي آخرها بعد الثنتين يجلس للتحيات يقرأ التحيات إلى قوله: (أشهد أن لا إله إلا الله، وأشهد أن محمدًا عبده ورسوله) ثم ينهض إلى الثالثة، وإن صلى على النبي ﷺ فهو أفضل، النبي ﷺ ربما نهض، وربما صلى على النبي ﷺ ثم نهض إلى الثالثة. ثم يقرأ في الثالثة الحمد فقط، هكذا روى أبو قتادة الأنصاري عن النبي ﷺ: أنه كان يقرأ في الثالثة والرابعة في الظهر والعصر بفاتحة الكتاب في الثالثة والرابعة، وهكذا في الثالثة من المغرب، والثالثة والرابعة من العشاء بالفاتحة، وإن قرأ في الثالثة والرابعة من الظهر بعض الشيء زيادة بعض الأحيان؛ فلا بأس؛ لحديث أبي سعيد الوارد في ذلك. المقدم: في الظهر خاصة؟ الشيخ: خاصة، لكن الأفضل والأكثر يكون الفاتحة وحدها، لكن إن زاد في بعض الأحيان في الثالثة والرابعة من الظهر بعض الآيات، أو بعض السور؛ فلا بأس؛ لأنه ورد في صحيح مسلم من حديث أبي سعيد ما يدل على أنه ربما زاد في الثالثة والرابعة من الظهر بعد الفاتحة، بعض الشيء، عليه الصلاة والسلام. ثم يجلس بعد الثالثة في المغرب، وبعد الرابعة في الظهر والعصر والعشاء، وبعد الثانية في الفجر، يقرأ التحيات ويصلي على النبي ﷺ، ويقول: أعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ويكثر من الدعاء أيضًا، يكثر من الدعاء: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم اللهم أعني على ذكرك، وشكرك، وحسن عبادتكاللهم إني أعوذ بك من البخل وأعوذ بك من الجبن وأعوذ بك أن أرد إلى أرذل العم،ر وأعوذ بك من فتنة الدنيا، ومن عذاب القبر وإن دعا بغير ذلك؛ فالحمد لله، يدعو ما تيسر، اللهم اغفر لي ما قدمت، وما أخرت، وما أسررت، وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر لا إله إلا أنت. النبي ﷺ قال: ثم يدعو، ثم يتخير من الدعاء أعجبه إليه وهذا من دعواته -عليه الصلاة والسلام- في التشهد الأخير قبل أن يسلم، بعد التحيات، وبعد الصلاة على النبي ﷺ وبعد قوله: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال. بعد هذا يجتهد في الدعاء بما تيسر، ثم يسلم تسليمتين: (السلام عليكم ورحمة الله) عن يمينه (السلام عليكم ورحمة الله) عن يساره، هذا تمام الصلاة، يفتحها بالتكبير، ويختمها بالتسليم، هكذا كان -عليه الصلاة والسلام- فينبغي للمؤمن والمؤمنة تحري هذا، وأن يصلي كما صلى النبي ﷺ؛ لأنه قال: صلوا كما رأيتموني أصلي اللهم صل عليه وسلم. المقدم: اللهم صل عليه. الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10166/صفة-صلاة-النبي-ﷺ-من-التكبير-الى-التسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43004.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":12578,"question":"هل هناك أي فرق بين صلاة الرجل والمرأة في الأفعال، مثلًا: رفع اليد إلى الأذن، ووضع اليد على الصدر؟","title":"هل هناك فروق بين صلاة الرجل والمرأة؟","answer":"الجواب:  الصواب أنها كالرجل؛ لقوله ﷺ: صلوا كما رأيتموني أصلي ولم يستثن النساء، فما شرع للرجال من رفع اليدين، ووضع اليدين على الصدر، ووضعها في الركوع على الركبتين، ووضعها في السجود حيال المنكبين، أو حيال الأذنين كله في حق الرجل والمرأة جميعًا.  وهكذا كونها تقرأ الفاتحة، وما تيسر معها في الأولى والثانية من الظهر والعصر والمغرب والعشاء، وهكذا في الفجر تقرأ مع الفاتحة ما تيسر، وفي الثالثة من المغرب تقرأ الفاتحة فقط، وفي الثالثة والرابعة من العشاء والظهر والعصر تقرأ الفاتحة. المقصود: أنها كالرجل. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10795/هل-هناك-فروق-بين-صلاة-الرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41210.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":12614,"question":"هل يجوز أن يفكر المصلي وهو في صلاته في القبر، وفي عذابه، وفي الجنة، والنار والموت؟","title":"التفكر بالجنة والنار وعذاب القبر في الصلاة","answer":"الجواب:  لا مانع من ذلك إذا لم يشغله عما شرع الله له، هذه يعني تفكير عارض لا يشغله عن واجباته، ولا عن سننه. نعم.","link":"https://binbaz.org.sa/fatwas/10833/التفكر-بالجنة-والنار-وعذاب-القبر-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41421.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":12675,"question":"تسأل أختنا وتقول: هل يجوز للمرأة أن تصلي وهي لابسة قفازين، وهي غير محرمة، ولا سيما إذا كانت معرضة لرؤية الرجال، ولو من بعيد، كأن تكون في المسجد الحرام؟ ثم أرجو توجيه نصيحة لنا نحن النساء فيما يتعلق بالصلاة في المسجد الحرام، وخاصة عند الزحام في العشر الأواخر من رمضان، وفي الحج، جزاكم الله خيرًا.","title":"حكم لبس القفازين للمرأة في الصلاة وصلاتها عند الزحام","answer":"الجواب: لا حرج في لبس القفازين في الصلاة وغيرها للمرأة، إلا إذا كانت محرمة؛ فإنها لا تلبسهما، أما إذا كانت غير محرمة، فلا مانع من لبسهما في الصلاة وغيرها، وأنصح جميع النساء بأن بيوتهن خير لهن، والصلاة في بيوتهن أفضل في مكة، وفي المدينة، وفي كل مكان، بيوتهن أفضل، وأبعد لهن عن الفتنة، فإذا صلين في المسجد؛ فليحرصن على التستر، والبعد عن الرجال، والاختلاط بهم. ولا شك أن صلاتهن في المسجد قد تدعو لها حاجة لسماع الحديث والمواعظ، فإذا جاءت من أجل هذا، أو لأنها في البيت قد تكسل، ولا تصلي قيام رمضان، فتحضر لأجل النشاط، هذا كله لا بأس به، والنبي ﷺ قال : لا تمنعوا إماء الله مساجد الله وقال: بيوتهن خير لهن فإذا كانت تستطيع أن تصلي في بيتها كما ينبغي؛ فهو أفضل لها، وإن صار خروجها إلى المسجد فيه مصلحة لسماع العلم والفقه في الدين، أو للنشاط؛ لأنها قد تكسل عن قيام رمضان؛ فهذا كله لا بأس به، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10885/حكم-لبس-القفازين-للمراة-في-الصلاة-وصلاتها-عند-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41704.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":12877,"question":"أيضًا يسأل أخونا ويقول: هناك أناس بعد انتهاء الصلاة يضع الواحد يده على جبينه بعض الوقت، ويقولون: إن هذا من السنة، هل ما قالوه صحيح؟","title":"حكم وضع اليد على الجبهة بعد الانصراف من الصلاة","answer":"الجواب: ليس له أصل فيما نعلم، وضع يده على جبينه بعد الصلاة، هذا لا أصل له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11092/حكم-وضع-اليد-على-الجبهة-بعد-الانصراف-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46609.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":13085,"question":"هذه السائلة دلال من اليمن تقول في هذا  ما حكم لبس الخاتم الذي يوجد عليه ثعبان، وهل تجوز الصلاة فيه، وجهونا بذلك؟","title":"حكم لبس الحلي والثياب التي عليها صور","answer":"الجواب:  لا يجوز لبسه، ولا يجوز الصلاة فيه إلا إذا قطع رأسه، رأس الثعبان، يقطع، يحك رأسه؛ حتى يزول الرأس، وإلا فلا يجوز لبسه، سواء كان خاتمًا، أو حلية، مثل الحلق، أو غيره، كثعبان، أو طير، أو حيوان آخر حتى يقطع الرأس، وإلا فالواجب عدم لبسه. لكن الصلاة صحيحة.. الصلاة صحيحة على الصحيح، لكن لا يجوز استعماله ولو في غير الصلاة، مثل: الخاتم الذي فيه صورة ثعبان أو غيره أو حزام، أو قميص، أو غير ذلك، لا يجوز حتى يقطع الرأس، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11302/حكم-لبس-الحلي-والثياب-التي-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50717.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":13117,"question":"سؤاله الأخير: ما حكم قراءة آية الكرسي في دبر كل صلاة، وكذلك مسح الوجه بعد الفراغ من الدعاء؟","title":"حكم قراءة آية الكرسي بعد الصلاة ومسح الوجه بعد الدعاء","answer":"الجواب:  قراءة آية الكرسي بعد كل صلاة سنة، جاءت فيها عدة أحاديث، فيستحب للمؤمن قراءتها بعد الصلاة، بعد السلام، وبعد الذكر، يقرؤها بينه وبين نفسه، هذا هو الأفضل. أما مسح الوجه باليدين فقد اختلف فيه العلماء، وورد فيه أحاديث ضعيفة، فالأفضل ترك ذلك، وإن مسح؛ فلا حرج؛ لأن بعض أهل العلم رآها من باب الحسن لغيره، وأجاز المسح، فالأمر في هذا واسع. لكن الأحاديث الصحيحة الكثيرة تدل على أن الترك أفضل؛ لأن الرسول ﷺ ما كان يمسح لما دعا في الاستسقاء، لم ينقل عنه أحد أنه مسح بيديه بعدما فرغ من دعاء الاستسقاء، والناس يسمعونه، وينظرونه، عليه الصلاة والسلام. وهكذا لا نعلم في الأحاديث الصحيحة أنه مسح -عليه الصلاة والسلام- لكن جاء في أحاديث فيها ضعف أنه مسح، قال الحافظ -رحمه الله- ابن حجر في البلوغ: إن مجموعها يقضي بأنه حديث حسن، يعني: حسن لغيره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11334/حكم-قراءة-اية-الكرسي-بعد-الصلاة-ومسح-الوجه-بعد-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47312.mp3","categories":["الأدعية والأذكار","مسائل متفرقة في الصلاة"]},{"id":13341,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الجمهورية اليمنية، وباعثتها إحدى الأخوات من هناك تقول المستمعة (ج. ع) أختنا عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها بعض الأسئلة من بينها سؤال يقول: إذا كان في الحلي بعض صور الحيوانات، فهل يجوز لبسه؟","title":"حكم لبس النساء الحلي التي عليها صور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا يجوز للمرأة أن تلبس حليًا، أو ملابس أخرى فيها صور الحيوانات، لا أسود، ولا نمور، ولا ذئاب، ولا رجال، ولا نساء، الواجب أن يزال الرأس، فإذا أزيل الرأس بأي طريقة؛ جاز اللبس؛ لأن الرسول ﷺ أمر بإزالة الرأس حتى يكون كهيئة الشجرة، ولما رأى سترًا عند عائشة فيه صورة؛ هتكه، وغضب -عليه الصلاة والسلام- وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم فالواجب أن تزال هذه الصورة بالطريقة الممكنة، ويكفي أن يزال الرأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11627/حكم-لبس-النساء-الحلي-التي-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47701.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":13741,"question":"السائل الذي رمز لاسمه بـ (أ. أ) يقول في هذا  هل الصلاة تقبل من الذي ثوبه مسبل؟","title":"حكم صلاة المسبل إزاره","answer":"الجواب: على خطر، على خطر من ذلك، لكن تصح .. تجزئه؛ لأن الرسول ﷺ ما أمره بالإعادة، الذي صلى وهو مسبل لم يأمره بالإعادة، فصلاته ناقصة، لا يؤمر بالإعادة، لكن لا يجوز له الإسبال مطلقًا، لا في الصلاة، ولا في خارجها. نعم.","link":"https://binbaz.org.sa/fatwas/12126/حكم-صلاة-المسبل-ازاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53519.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":13746,"question":"السائل الذي رمز لاسمه بـ (أ. أ) يقول في هذا  هل الصلاة تقبل من الذي ثوبه مسبل؟","title":"حكم صلاة المسبل إزاره","answer":"الجواب: على خطر، على خطر من ذلك، لكن تصح .. تجزئه؛ لأن الرسول ﷺ ما أمره بالإعادة، الذي صلى وهو مسبل لم يأمره بالإعادة، فصلاته ناقصة، لا يؤمر بالإعادة، لكن لا يجوز له الإسبال مطلقًا، لا في الصلاة، ولا في خارجها. نعم.","link":"https://binbaz.org.sa/fatwas/12126/حكم-صلاة-المسبل-ازاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53519.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":13828,"question":"هذا السائل (محمد . أ. أ) يقول: سماحة الشيخ! ما حكم قطع الصلاة؟ وذلك لأن بعض الأولاد في الصف الثاني يسببون صخبًا شديدًا ويتكلمون وينتظرون ركوع الإمام، فهل لي أن ألتفت إليهم وأقوم بإرشادهم وتأديبهم على ذلك الفعل؟","title":"حكم قطع الصلاة لإسكات الأطفال","answer":"الجواب: لا، يكفي الإشارة، لا تقطع صلاتك استمر، تكفي الإشارة لهم بالهدوء، ولا تقطع الصلاة استمر في صلاتك، وبعد السلام تنصحهم وتوجههم، ولا تقطع الصلاة، يلزمك ..... إن دخلت فيها فأتمها، ولكن بالإشارة لا بأس أن تشير إليهم بيدك حتى يهدءوا. نعم.","link":"https://binbaz.org.sa/fatwas/12193/حكم-قطع-الصلاة-لاسكات-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53005.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":13931,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة (ح. ع. أ)، أختنا تسأل في أحد أسئلتها وتقول: هل يجوز للمرأة أن تصلي بالثوب الذي يوجد به صور؟ نرجو التوضيح في هذه المسألة، وإفادتنا بالخير جزاكم الله خيرًا.","title":"حكم الصلاة في ثوب فيه صور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفقد دلت الأحاديث الصحيحة عن رسول الله ﷺ على تحريم التصوير وعلى لعن المصورين، ولما رأى عند عائشة رضي الله عنها سترًا فيه تصاوير هتكه وغضب عليه الصلاة والسلام وقال: يا عائشة إن أصحاب هذه الصور يعذبون يوم القيامة ويقال: أحيوا ما خلقتم. فلا يجوز للمرأة أن تصلي في ثوب فيه تصاوير سواءً كانت تصاوير لبني آدم أو لحيوانات أخرى، لكن لو صلت صحت الصلاة مع الإثم، الصحيح: أنها تصح الصلاة لكن مع الإثم، لا تعيد الصلاة لكن عليها التوبة إلى الله، ولا تعود تصلي في ثوب فيه تصاوير لا في فنيلة ولا في قميص ولا في سراويل ولا في خمار يجب ترك ذلك. وهكذا الرجل لا يصلي في ثوب فيه تصاوير لا فنيلة ولا قميص ولا غترة ولا سراويل ولا بشت، يجب ترك ذلك؛ لأن هذا أعظم من الستر اللي على الجدار، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12318/حكم-الصلاة-في-ثوب-فيه-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48206.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":13937,"question":"المستمع أبو جابر من تبوك بعث بسؤال يقول فيه: ما حكم رفع اليدين بعد الصلاة بالدعاء؟ وما حكم مسح الوجه بعد الانتهاء من الدعاء؟ جزاكم الله خيرًا.","title":"حكم رفع اليدين بالدعاء بعد الصلاة ومسح الوجه بهما","answer":"الجواب: رفع اليدين في الدعاء من أسباب الإجابة، ولكن المواضع التي ما رفع فيها النبي ﷺ لا نرفع فيها، وإلا رفع اليدين من أسباب الإجابة، يقول النبي ﷺ: إن ربكم حيي كريم يستحي من عبده إذا رفع يديه إليه أن يردهما صفرًا، فإذا دعا في آخر الليل أو في أي وقت ورفع يديه كان هذا من أسباب الإجابة، لكن بعد الفريضة لا يرفع يديه؛ لأن الرسول ﷺ ما كان يرفع، إذا دعا بعد الفريضة الظهر أو العصر أو المغرب أو العشاء أو الفجر أو الجمعة لا يرفع يديه؛ لأن النبي ﷺ ما كان يرفع في هذا، وهكذا في خطبة الجمعة، خطبة العيد ما كان يرفع إلا في الاستسقاء إذا استسقى طلب الغيث رفع يديه ولو في خطبة الجمعة أو في أي مكان إذا استسقى يرفع يديه ويدعو.\nهكذا إذا كان في غير صلاة ودعا يرفع يديه لا بأس، يرفع يديه ويدعو، هكذا بعد النافلة إذا رفع يديه بعض الأحيان ودعا لا بأس، لكن لا يكون مستمرًا؛ لأنه لم يحفظ عن النبي ﷺ أنه كان يستمر في رفع يديه بعد النافلة، فإذا رفع بعض الأحيان ودعا لا بأس.\nأما مسح الوجه باليدين: اختلف فيه العلماء: منهم من رأى استحبابه ومنهم من رأى عدم استحبابه؛ لأن الأحاديث الصحيحة ليس فيها مسح الوجه، في الأحاديث الصحيحة المعروفة عن النبي ﷺ ليس فيها مسح الوجه بعد الدعاء، وجاء في أحاديث ضعيفة أنه مسح يديه.. مسح بيديه وجهه، فإن فعل فلا حرج وإن ترك فهو أفضل إن شاء الله، إن ترك فهو أفضل وإن فعل فلا حرج؛ لأن بعض أهل العلم جعلها حسنة، جعل الأحاديث التي فيها مسح الوجه جعلها متعاونة ومتعاضدة، وجعلها من قسم الحسن واستحب مسح الوجه منهم الحافظ ابن حجر رحمه الله في البلوغ ذكر أنها يشد بعضها بعضًا، وقال آخرون: لا يستحب لأنها ضعيفة.\nفالحاصل: أن الأمر في هذا واسع إن شاء الله، فمن مسح فلا حرج ومن ترك فلعله أفضل وأولى؛ لأن الأحاديث الصحيحة ليس فيها مسح. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12337/حكم-رفع-اليدين-بالدعاء-بعد-الصلاة-ومسح-الوجه-بهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48210.mp3","categories":["الأدعية والأذكار","مسائل متفرقة في الصلاة"]},{"id":13972,"question":"السائل من الجزائر، حسين من الجزائر بعث بمجموعة من الأسئلة، في سؤاله الأول يقول: سماحة الشيخ! كيف كانت صلاة المصطفى ﷺ؟ وجهونا في ضوء سؤالنا.","title":"صفة صلاة النبي صلى الله عليه وسلم","answer":"الجواب: كانت صلاته ﷺ تخفيفًا في تمام كما قال أنس : \"ما صليت خلف أحد أتم صلاة ولا أخف صلاة من النبي عليه الصلاة والسلام\" كانت صلاته تخفيفًا في تمام؛ يتم ركوعها وسجودها واعتدالها بعد الركوع وبين السجدتين ولكن لا يطيل إطالة تمل الناس وتشق عليهم، وهكذا السنة أن يصلي المؤمن تخفيفًا في تمام، يعني: الإمام والمنفرد، أما المأموم فهو تابع لإمامه، ويقول ﷺ: أيكم أم الناس فليخفف، فإن فيهم الصغير والكبير والضعيف وذا الحاجة ويقول: صلوا كما رأيتموني أصلي عليه الصلاة والسلام، فالتخفيف: أن تتأسى بصلاته ﷺ وهي تخفيف في تمام، كان يقرأ في الظهر من أوساط المفصل، وفي العصر أقل من ذلك أخف من الظهر، وفي المغرب من قصاره، وتارة من طواله، وتارة من أوساطه، والغالب في المغرب أن يقرأ بالقصار، وكان يقرأ في العشاء بأوساط المفصل، وفي الفجر بطوال المفصل مثل: ق، والطور، والذاريات ونحوها، وكان يركع ركوعًا فيه إتمام وفيه تخفيف، ربما سبح سبع تسبيحات .. عشر تسبيحات: سبحان ربي العظيم .. سبحان ربي العظيم، ويقول في ركوعه: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي .. سبوح قدوس رب الملائكة والروح. وكان إذا اعتدل بعد الركوع يطمئن حتى يرجع كل فقار إلى مكانه، وكان يعتدل بعد الركوع حتى يقول القائل: قد نسي، وهكذا بين السجدتين، يعتدل بين السجدتين ويقول: رب اغفر لي .. رب اغفر لي اللهم اغفر لي وارحمني واهدني واجبرني وارزقني وعافني ولا يعجل حتى يرجع كل فقار إلى مكانه.\nوكان في السجود أيضًا يطمئن ويسبح عدة تسبيحات .. عشر تسبيحات، أو سبع تسبيحات، وكان أنس  صلى خلف بعض الأئمة فقال: إنه أشبه صلاة بالنبي ﷺ وكان يعد له في الركوع والسجود عشر تسبيحات، فإذا سبح عشرًا أو سبعًا أو خمسًا فكل هذا حسن، سبحان ربي العظيم في الركوع سبحان ربي الأعلى في السجود رب اغفر لي بين السجدتين، لكن مع الطمأنينة حتى يرجع كل فقار إلى مكانه. هكذا كان ﷺ يصلي تخفيفًا في تمام، والسنة للأئمة أن يتأسوا به؛ لقوله ﷺ: صلوا كما رأيتموني أصلي وهكذا الأفراد إذا صلى الإنسان فردًا لمرض أو غيره يتأسى بالنبي ﷺ، وهكذا النساء يصلون كما كان النبي يصلي عليه الصلاة والسلام تخفيفًا في تمام، وقد سمعت صفة صلاته عليه الصلاة والسلام، كان يتم ركوعه وسجوده، وكان يعتدل بين السجدتين ويعتدل بعد الركوع ولا يعجل، وكان يقرأ في الظهر والعصر من أوساط المفصل لكن العصر أخف، وفي المغرب من قصار المفصل وربما قرأ من طواله كالطور وغيرها وربما قرأ بالمرسلات عليه الصلاة والسلام، فتارة يطيل في المغرب وتارة يقصر في المغرب عليه الصلاة والسلام، وفي العشاء بأوساط المفصل مثل : هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ[الغاشية:1] مثل: وَالْفَجْرِ[الفجر:1]، مثل: سَبِّحِ[الأعلى:1] مثل: وَالسَّمَاءِ ذَاتِ الْبُرُوجِ[البروج:1] وفي الفجر يقرأ بطوال المفصل مثل: الذاريات وق وَالْقُرْآنِ الْمَجِيدِ[ق:1] مثل: الطور، مثل: اقْتَرَبَتِ السَّاعَةُ[القمر:1] مثل : تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ[الملك:1] وأشباه ذلك. نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12388/صفة-صلاة-النبي-صلى-الله-عليه-وسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53903.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":14367,"question":"السائل الذي رمز لاسمه بـ (ح. م. ح) من الرياض، يقول: ما حكم الشرع في نظركم فضيلة الشيخ في خروج المصلي من الصلاة بسبب رؤيته أشياء ضارة، مثل ثعبان أو حيوان مفترس، أو غير ذلك؟","title":"حكم خروج المصلي من الصلاة للضرورة","answer":"الجواب: خروجه من الصلاة فيه تفصيل: إن خاف على نفسه خرج منها حتى يتخلص منها، مثل إنسان يريد قتله، أو مثل ثعبان وصل إليه يخشى من شرهن ولا يتيسر قتله وهو يصلي، يحتاج إلى طلب شيء يقتله به، فلا بأس. وأما إذا أمكن أن يقتله وهو في الصلاة فلا بأس، يقول النبي ﷺ: اقتلوا الأسودين في الصلاة: الحية والعقرب إذا كان عنده عصا وهو يصلي وضربها، وهو يصلي ما يضر، والحمد لله، أما إذا احتاج إلى قطعها يقطعها، للتخلص من ثعبان، أو من عدو يريد الفتك به، أو سبع، أو ما أشبه ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/12847/حكم-خروج-المصلي-من-الصلاة-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55109.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":14376,"question":"يقول السائل (ن. ح. م): هل الصلاة لا تصح إذا لم يزِل المسلم أو المسلمة شعر الإبط والعانة؟أفيدونا بذلك.","title":"هل من شروط الصلاة إزالة شعر الإبط والعانة؟","answer":"الجواب: الصلاة صحيحة، ليس من شرطها زوال الإبط والعانة، لكن سنة للإنسان أن يتعاهد عانته وإبطه، وألا يتركها أكثر من أربعين، يقول أنس : «وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة، ألا نترك ذلك أكثر من أربعين ليلة» وفي لفظ: «وقّت لنا رسول الله ﷺ ذلك».\nفالسنة للمؤمن أن يتعاهدها قبل كمال الأربعين، نعم.","link":"https://binbaz.org.sa/fatwas/12857/هل-من-شروط-الصلاة-ازالة-شعر-الابط-والعانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55119.mp3","categories":["سنن الفطرة","مسائل متفرقة في الصلاة"]},{"id":14401,"question":"هل هناك صلاة قبل الإسلام؟ وما هي سماحة الشيخ؟","title":"هل هناك صلاة قبل الإسلام؟","answer":"الجواب: لا أعرف عن الجاهلية شيئًا من صلاتهم، الأنبياء لهم صلاة، جاؤوا بالصلاة، الصلاة جاء بها الأنبياء، لكن كون الجاهلية يصلون صلاة لا أعرف شيئًا عن صلاتهم، أما الأنبياء جاؤوا بالصلوات، جاء بها إبراهيم، وجاء بها إسماعيل، وجاء بها غيرهم من الأنبياء، نعم.","link":"https://binbaz.org.sa/fatwas/12883/هل-هناك-صلاة-قبل-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55220.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":14427,"question":"أخيرًا السائلة يا سماحة الشيخ عبدالعزيز تستفسر عن معنى هذا الحديث؛ قال رسول الله ﷺ: من قرأ آية الكرسي دبر كل صلاة مكتوبة لم يمنعه من دخول الجنة إلا أن يموت ما معنى هذا الحديث؟","title":"ما معنى «من قرأ آية الكرسي دبر كل صلاة..»؟","answer":"الجواب: هذا جاء له طرق، وبعضها لا بأس به، وهو يستحبن يدل على أنه يستحب أن تقرأ هذه الآية بعد كل صلاة: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] وهي أعظم آية في القرآن، يستحب أن تقرأ بعد كل صلاة من الصلوات الخمس؛ لأن بعض الطرق صحيح جيد لا بأس به، ومعناه الوعد بالخير، وأن هذا من أسباب دخول الجنة إن لم يمنع مانع من وجود كبائر من الذنوب، مثلما في الأحاديث الأخرى التي فيها الوعد بالجنة لمن صام عرفة من صام يوم عرفة، أو صام يوم العاشوراء، أو صام الإثنين والخميس، يعني: إن لم يصر على الكبائر. الحديث هذا وعد إن لم يقم على الكبائر، أما من أقام على الكبائر ما تغفر له ذنوبه، يقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفارات لما بينهن إذا اجتنب الكبائر والله يقول في كتابه العظيم يخاطب المؤمنين وغيرهم: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا[النساء:31]. فشرط في تكفير السيئات، ودخول الجنات اجتناب الكبائر، أما من لم يجتبنها مات وهو مقيم عليها من الزنا أو العقوق للوالدين أو أكل الربا أو قطيعة الرحم، أو ما أشبه ذلك، فهذا معلق أمره وعلى خطر، لا تكن حسناته مكفرة، بل هو على خطر حتى يجتنب الكبائر.  إذا كانت الصلاة وهي عمود الإسلام لا تكفر إلا باجتناب الكبائر، وهكذا صوم رمضان فكيف بغير ذلك؟ يقول ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن إذا اجتنب الكبائر وفي لفظ: ما لم تغش الكبائر أخرجه مسلم في الصحيح، فهذا يدل على أن أحاديث الوعد بالمغفرة والرحمة لمن استغفر أو فعل كذا وكذا مشروط باجتناب الكبائر، ونص الآية واضح في ذلك، يقول سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31]. فالأحاديث التي فيها تكفير السيئات، وحط الخطايا لمن فعل كذا، أو فعل كذا، يعني: ما لم يصر على كبيرة، ما لم يكن عنده إصرار على كبيرة من الكبائر، فإذا أصر على الكبيرة لم تكفر له الذنوب بذلك العمل، نسأل الله لنا ولجميع المسلمين العافية، نعم.","link":"https://binbaz.org.sa/fatwas/12906/ما-معنى-من-قرا-اية-الكرسي-دبر-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55320.mp3","categories":["مسائل متفرقة في الصلاة","شروح الحديث"]},{"id":14441,"question":"أخيرًا السائلة يا سماحة الشيخ عبدالعزيز تستفسر عن معنى هذا الحديث؛ قال رسول الله ﷺ: من قرأ آية الكرسي دبر كل صلاة مكتوبة لم يمنعه من دخول الجنة إلا أن يموت ما معنى هذا الحديث؟","title":"ما معنى «من قرأ آية الكرسي دبر كل صلاة..»؟","answer":"الجواب: هذا جاء له طرق، وبعضها لا بأس به، وهو يستحبن يدل على أنه يستحب أن تقرأ هذه الآية بعد كل صلاة: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] وهي أعظم آية في القرآن، يستحب أن تقرأ بعد كل صلاة من الصلوات الخمس؛ لأن بعض الطرق صحيح جيد لا بأس به، ومعناه الوعد بالخير، وأن هذا من أسباب دخول الجنة إن لم يمنع مانع من وجود كبائر من الذنوب، مثلما في الأحاديث الأخرى التي فيها الوعد بالجنة لمن صام عرفة من صام يوم عرفة، أو صام يوم العاشوراء، أو صام الإثنين والخميس، يعني: إن لم يصر على الكبائر. الحديث هذا وعد إن لم يقم على الكبائر، أما من أقام على الكبائر ما تغفر له ذنوبه، يقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفارات لما بينهن إذا اجتنب الكبائر والله يقول في كتابه العظيم يخاطب المؤمنين وغيرهم: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا[النساء:31]. فشرط في تكفير السيئات، ودخول الجنات اجتناب الكبائر، أما من لم يجتبنها مات وهو مقيم عليها من الزنا أو العقوق للوالدين أو أكل الربا أو قطيعة الرحم، أو ما أشبه ذلك، فهذا معلق أمره وعلى خطر، لا تكن حسناته مكفرة، بل هو على خطر حتى يجتنب الكبائر.  إذا كانت الصلاة وهي عمود الإسلام لا تكفر إلا باجتناب الكبائر، وهكذا صوم رمضان فكيف بغير ذلك؟ يقول ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن إذا اجتنب الكبائر وفي لفظ: ما لم تغش الكبائر أخرجه مسلم في الصحيح، فهذا يدل على أن أحاديث الوعد بالمغفرة والرحمة لمن استغفر أو فعل كذا وكذا مشروط باجتناب الكبائر، ونص الآية واضح في ذلك، يقول سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31]. فالأحاديث التي فيها تكفير السيئات، وحط الخطايا لمن فعل كذا، أو فعل كذا، يعني: ما لم يصر على كبيرة، ما لم يكن عنده إصرار على كبيرة من الكبائر، فإذا أصر على الكبيرة لم تكفر له الذنوب بذلك العمل، نسأل الله لنا ولجميع المسلمين العافية، نعم.","link":"https://binbaz.org.sa/fatwas/12906/ما-معنى-من-قرا-اية-الكرسي-دبر-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55320.mp3","categories":["مسائل متفرقة في الصلاة","شروح الحديث"]},{"id":14626,"question":"لديه إشكال حول موضوع الصلاة في الحذاء سماحة الشيخ، ويرجو توجيهه لو تكرمتم.الشيخ: ماذا؟المقدم: إشكال في موضوع الصلاة في الحذاء.","title":"جواب من أشكل عليه حكم الصلاة في الحذاء","answer":"الجواب: الصلاة في الحذاء مشروعة، النبي ﷺ كان يصلي في نعله -عليه الصلاة والسلام-، كما في الصحيحين عن أنس، قال: \"كان النبي يصلي في نعليه -عليه الصلاة والسلام-\" فإذا صلى في نعليه وهما نظيفتان لا حرج في ذلك، وقال: صلى ذات يوم -عليه الصلاة والسلام- في نعليه فجاءه جبرائيل وأخبره أن بهما قذرًا فخلعهما، فخلع الناس نعالهم، فلما سلم سألهم: لماذا خلعتم نعالكم؟ قالوا: رأيناك خلعت نعليك فخلعنا نعالنا، فقال: إن جبريل أتاني فقال: إن بهما قذرًا فخلعتهما، فإذا أتى أحدكم المسجد فلينظر فإن رأى في نعله أذىً فليمسحه، ثم يصلي فيهما وفي لفظ آخر: فليقلب نعليه، فإن رأى فيهما أذى فليمسحه، ثم يصلي فيهما وهو حديث صحيح، وهو يدل على أن الأفضل صلاة النعال والخفاف، وهكذا حديث: إن اليهود والنصارى لا يصلوا في نعالهم فخالفوهم وهو يدل على شرعية الصلاة في النعال. لكن إذا كان المسجد مفروشًا، ويخشى أن يقذره؛ لأن بعض الناس لا يبالي، ولا ينظر في نعليه، فإذا خلعهما وصلى حافيًا حتى لا يوسخ الفرش، وحتى لا ينفر الناس من الصلاة في المسجد، فهذا لعله أحسن -إن شاء الله-، من باب رعاية المصالح، وعدم تنفير الناس من المساجد، ونظرًا إلى أن أكثر الناس إلا من شاء ربك لا يهتم بالنعلين، ولا يحرص على سلامتهما، فإذا جعل نعليه في مكان خاص حتى يصلي أو جعلهما بين رجليه حتى يصلي فلا بأس بذلك.  ولعل هذا أصلح -إن شاء الله- حرصًا على سلامة المساجد، وحرصًا أيضًا على عدم تنفير المصلين، فإن كثيرًا من الناس قد ينفر من المساجد إذا رآها توطأ بالنعال، هذه الفرش التي تتأثر بأقل شيء، بخلاف ما لو كان المسجد من الحصباء أو الرمل فإنه لا يتأثر كثيرًا، والأمر فيه واسع، كما كان الحال في عهد النبي ﷺ وعهد الصحابة ، نعم. المقدم: جزاكم الله خيرًا. المقدم: سماحة الشيخ، هل تتكرمون بإعادة الكيفية لتطهير الأحذية؟ الشيخ: نعم يطهرها بالمسح، يعني: يحكها في الأرض، أو يحكها باللبن ونحوه، حتى يزول الأذى بالكلية، فإذا زال ولم يبق له أثر صار طهورًا لها، كما في الحديث: إذا وطأ أحدكم الأذى بخفيه فطهورهما التراب وفي اللفظ الآخر: فليمسحه ثم ليصل فيهما. فالمقصود: أن حكها بالأرض وحكها بالتراب حتى يزول الأذى ولا يبقى له أثر فإنه يكون طهرًا لهما، نعم.\nالمقدم: جزاكم الله خيرًا، هذا إذا كان الأذى له جسم أو ليس له جسم؟ الشيخ: إذا كان له جسم، أما إذا كان لا، ما له جسم فالأمر أسهل، مسحه في الأرض يكفي، لكن إذا كان له جسم لا بد من حكه حتى يسقط، كالعذرة والروث، ونحو ذلك. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13122/جواب-من-اشكل-عليه-حكم-الصلاة-في-الحذاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62611.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":14788,"question":"إذا عطس المصلي أثناء الصلاة فهل يحمد الله أم كيف؟","title":"هل يحمد الله من عطس في الصلاة؟","answer":"الجواب: نعم يحمد الله لفظًا، فقد ثبت عن النبي ﷺ أنه سمع من عطس، وحمد الله، فقال: لقد رأيت كذا وكذا من الملائكة كلهم يبتدرونها أيهم يكتبها أو كما قال -عليه الصلاة والسلام- فلا بأس؛ لأن الحمد من جنس أعمال الصلاة، فإذا حمد الله عند العطاس كان فعل السنة، نعم. المقدم: ولو في الصلاة؟ الشيخ: نعم. المقدم: أما التشميت فلا؟ الشيخ: لا يشمت، لا؛ لأن التشميت من كلام بني آدم، يحصل فيه خطاب (يرحمك) وهذا من كلام بني آدم لا يشمت، من كان في الصلاة لا يشمت، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13275/هل-يحمد-الله-من-عطس-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63807.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":15067,"question":"تقول السائلة: ما معنى الموالاة في الصلاة؟","title":"معنى الموالاة في الصلاة","answer":"الجواب: الموالاة في الصلاة أن يصليها كما شرع الله، فيركع كما شرع الله، ويرفع ويعتدل كما شرع الله، ويسجد كما شرع الله، ويعتدل ويطمئن ويجلس بين السجدتين كما شرع الله، ويطمئن، ولا يعجل، هذه يقال لها: الطمأنينة، يقال لها: الطمأنينة والخشوع في الصلاة، تسميتها موالاة تسمية غير ظاهرة. أما إن كان المقصود الموالاة بين الصلاتين، هذا شيء آخر، الموالاة بينهما: أن كل صلاة تصلى في وقتها، إلا إذا جمع بين الظهر والعصر، أو بين المغرب والعشاء؛ والى بينهما، صلى هذه بعد هذه. أما في الصلاة الواحدة، فالمعنى أنه يصلي أركانها، يأتي بأركانها في محلها مع الطمأنينة، ويسمى هذا خشوع وطمأنينة، يركد في قراءته، وإذا ركع ركد، واعتنى واطمأن حتى يرجع كل فقار إلى مكانه، وإذا رفع اطمأن واعتدل، حتى يرجع كل فقار إلى مكانه، وإذا سجد سجد واطمأن حتى يرجع كل فقار إلى مكانه، وإذا جلس بين السجدتين اعتدل واطمأن، حتى يرجع كل فقار إلى مكانه؛ هذه طمأنينة، هذا الخشوع، هذا لا بد منه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13554/معنى-الموالاة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56316.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":15262,"question":"أم محمد من الرياض، بعثت بثلاثة أسئلة، تقول في السؤال الأول: سماحة الشيخ، لقد عودت أطفالي منذ سن الخامسة بالوقوف إلى جانبي بالصلاة، وتعليمهم كيفية الصلاة، مما أضطر إلى رفع صوتي قليلًا؛ ليستطيعوا تقليدي، وسؤالي: هل علي إثم في رفع الصوت قليلًا بتعليم أبنائي؟ مع العلم بأنني ما زلت أرفع صوتي حتى أعلم الصغار منهم.","title":"حكم رفع الصوت في الصلاة من أجل تعليم الأولاد","answer":"الجواب: لا حرج في ذلك -إن شاء الله-، لا حرج؛ لكن إذا أمكن تعليمهم خارج الصلاة يكون أكمل، خارج الصلاة حتى إذا دخلوا في الصلاة، إذ هم قد تعلموا، وإذا رفعت الصوت بعض الشيء حتى يفهموا فلا بأس.  وإذا بلغ السبع تأمرونه يروح المسجد يصلي مع الناس، والجارية تصلي معكم، تتعلم منكم، وما دون السبع ابن خمس وابن ست لا بأس إذا تعلم، وإلا فصلاته غير صحيحة حتى يبلغ السبع، لكن إذا تعلم لا بأس. أما الواجب فهو العناية بمن بلغ سبعًا حتى يتعلم ويستفيد، المرأة تصلي معكم وتعلمونها، والولد إذا صلى معكم فلا بأس، وإن أمرتوه بالذهاب إلى الصلاة مع الرجال فهو السنة، وإذا بلغ عشرًا يضرب حتى يصلي مع الناس، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13754/حكم-رفع-الصوت-في-الصلاة-من-اجل-تعليم-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56510.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":15986,"question":"من اليمن السائل عبدالرحمن محمد يقول: سماحة الشيخ، هل يجوز للمرأة أن تصلي بثوب من حرير؟","title":"حكم صلاة المرأة في ثوب من حرير","answer":"الجواب: الحرير مباح للنساء، الذهب والحرير مباح للنساء محرم على الرجال؛ فلا بأس أن تصلي في ثوب من حرير إذا كان ساترًا لها لا حرج في ذلك؛ لأنه يجوز لها لبس الحرير، فإذا كان عليها ملابس من الحرير ساترة فلا بأس. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14589/حكم-صلاة-المراة-في-ثوب-من-حرير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57815.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":16245,"question":"تقول: هل يجوز أن أصلي وأنا متطيبة بالطيب؟ جزاكم الله خيرًا.","title":"حكم صلاة المرأة وعليها طيب","answer":"الجواب: نعم، الصلاة بالطيب لا بأس بها، بل الطيب مشروع للمؤمن والمؤمنة، لكن المؤمنة تطيب في بيتها، المؤمنة تطيب في بيتها، وعند زوجها، وليس لها التطيب عند الخروج إلى الأسواق، ولا إلى المساجد، أما المؤمن فيتطيب في بيته، وفي أسواقه، وفي المسجد الطيب مطلوب، وهو من سنة المرسلين. فإذا صلت المرأة في بيتها متطيبة بدهن العود، أو الورد، أو العنبر، ونحو ذلك كله طيب، لا شيء في ذلك، ولا حرج في ذلك، بل هو مطلوب، لكن لا تخرج بالطيب الذي يجد الناس رائحته، لا تخرج به إلى الأسواق، ولا إلى المساجد؛ لأن الرسول نهى عن هذا -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14938/حكم-صلاة-المراة-وعليها-طيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80708.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":16374,"question":"السائلة (م. ع) استعرضنا بعضًا من أسئلتها، وتقول في هذا السؤال يا سماحة الشيخ: ما حكم الصلاة بالقفازات؟","title":"حكم صلاة المرأة بالقفازين","answer":"الجواب: لا حرج، القفازان إذا كانت ليست محرمة لا حرج، أما إذا كانت محرمة لا، لا تلبس القفازين.","link":"https://binbaz.org.sa/fatwas/15072/حكم-صلاة-المراة-بالقفازين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58117.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":16751,"question":"يقول في سؤال آخر: مصلٍ جلس مع الإمام في الجلوس الأوسط، وعندما قام الإمام للركعة الثالثة لم يقم المصلي معه؛ لأنه كان نعسانًا، ونام نومًا خفيفًا أثناء قراءة التشهد، وظل نائمًا حتى أتم الإمام الركعة الثالثة، وهي سرية طبعًا، وعندما كبر الإمام للركوع؛ انتبه المصلي، وقام واقفًا، فوجد الإمام قد رفع من الركوع، كيف يكمل هذا المصلي صلاته؟","title":"ما يعمل من نعس في الصلاة وفاته بعضها؟","answer":"الجواب: إذا نعس، وبقي في جلوسه حتى ركع الإمام، يقوم، ويركع مع الإمام فإن سبقه الإمام يركع، ثم يلحق الإمام، ويسجد معه يركع، ثم يرفع، ويعتدل، ثم يلحق الإمام، ويجزئه، وإذا كان نعاسًا ما أزال الشعور عنده بعض اليقظة، بعض الانتباه، لكن لم ينتبه للتكبير، وإلا فلم يستغرق في النوم. أما إذا استغرق في النوم؛ تبطل صلاته، يعني يستأنفها من أولها؛ لأن النوم ينقض الوضوء إذا استغرق فيه، أما إذا كان نعاسًا، نومًا خفيفًا، ما استغرق يتابع الإمام، وتسقط عنه الفاتحة؛ لأنه في هذه الحالة لم يتعمد تركها، بل أخذه النوم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15493/ما-يعمل-من-نعس-في-الصلاة-وفاته-بعضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71812.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":16797,"question":"هل تجوز صلاة فروض بدلًا من التي يمكن أن تكون لم تقبل، فلقد وجدت أختًا تصلي من الفروض التي عسى أن تكون لم تقبل لكثرة سهوها، أو أي شيء آخر؟","title":"هل يجوز إعادة الصلاة مخافة عدم قبولها؟","answer":"الجواب: هذا بدعة لا يجوز، الأصل الإجزاء، فليس لها، ولا للرجل أن يأتي بصلوات احتياطًا؛ مخافة أن الصلاة الأولى ما قبلت، هذا وساوس، وشكوك لا وجه لها، أما إذا علم أن صلاته باطلة؛ لأنه أحدث فيها، أو صلاها بغير طهارة، هذا يعيد، أما مجرد أنه وسوس، هذا من الشيطان، والأصل السلامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15580/هل-يجوز-اعادة-الصلاة-مخافة-عدم-قبولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82311.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":16805,"question":"هل تجوز صلاة فروض بدلًا من التي يمكن أن تكون لم تقبل، فلقد وجدت أختًا تصلي من الفروض التي عسى أن تكون لم تقبل لكثرة سهوها، أو أي شيء آخر؟","title":"هل يجوز إعادة الصلاة مخافة عدم قبولها؟","answer":"الجواب: هذا بدعة لا يجوز، الأصل الإجزاء، فليس لها، ولا للرجل أن يأتي بصلوات احتياطًا؛ مخافة أن الصلاة الأولى ما قبلت، هذا وساوس، وشكوك لا وجه لها، أما إذا علم أن صلاته باطلة؛ لأنه أحدث فيها، أو صلاها بغير طهارة، هذا يعيد، أما مجرد أنه وسوس، هذا من الشيطان، والأصل السلامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15580/هل-يجوز-اعادة-الصلاة-مخافة-عدم-قبولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82311.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":16813,"question":"السؤال الأخير لأخينا يقول فيه: هل تجوز الصلاة في الأحذية، أجلكم الله؟","title":"هل تجوز الصلاة في الأحذية","answer":"الجواب: نعم، بل مستحبة؛ لأن الرسول ﷺ كان يصلي في نعليه -عليه الصلاة والسلام- وأمر بالصلاة في النعلين، وأمر بمخالفة اليهود؛ لأنهم لا يصلون في نعالهم، ولا في خفافهم، لكن بعد أن ينظر فيها قبل دخول المسجد، حتى تكون سليمة، ليس فيها أذى، فإذا كانت سليمة ليس فيها أذى؛ فالأفضل الصلاة فيها.  لكن بالنظر إلى المساجد التي فرشت بالفرش قد يكون فيها شيء من الأوساخ، أو شيء يؤذي المصلين، فالأولى أن تجعل في مكان آخر عند الباب، أو في مكان آخر حتى لا يتأذى بها الناس، وما يكون فيها من أوساخ، وأتربة، ونحو ذلك؛ مراعاةً للمصلين، وللفرش التي وضعت في المساجد، حتى لا يحصل لها تقذير، ولا يحصل للمصلين تنفير لهم من الصلاة في الجماعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15567/هل-تجوز-الصلاة-في-الاحذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76309.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":16893,"question":"من المستمعة (م. أ. ب. س) من ليبيا رسالة، وضمنتها جمعًا من الأسئلة في أحد أسئلتها تقول: هل أنه صحيح لا تجوز الصلاة بخواتم، وسلاسل النحاس؟ أفيدونا أفادكم الله، وجزاكم الله خيرًا.","title":"حكم الصلاة بخواتم الحديد والنحاس","answer":"الجواب: ليس بصحيح، ولا حرج في الصلاة بخواتم الذهب بحق المرأة، وخاتم الفضة بحق الجميع، وخاتم الحديد بحق الجميع، لا حرج في ذلك، والحديث الذي فيه التحريم من هذا حديث ضعيف، شاذ، مخالف للأحاديث الصحيحة، وقال -عليه الصلاة والسلام- للذي أراد الزواج، وليس عنده شيء، قال له: التمس ولو خاتمًا من حديد رواه الشيخان، البخاري ومسلم في الصحيحين؛ فدل على جواز لبس الخاتم من الحديد. وأما الحديث الذي فيه أنه رأى على إنسان خاتمًا من حديد، فقال: ما لي أرى عليك حلة أهل النار ورأى آخر عليه خاتم من صفر قال: ما لي أرى عليك ريح الأصنام فهو حديث ضعيف، شاذ، مخالف للأحاديث الصحيحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15652/حكم-الصلاة-بخواتم-الحديد-والنحاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76510.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":17036,"question":"يسأل ويقول: ما حكم صلاة المسبل إزاره؟ مع الدليل؟ جزاكم الله خيرًا.","title":"حكم صلاة المسبل إزاره","answer":"الجواب: الإسبال محرم، لا يجوز الإسبال، وهو كون الملابس تنزل عن الكعب، سواء كان اللباس سراويل، أو إزارًا، أو قميصًا، أو بشتًا، وهو العباءة، أو غير ذلك، هذا في حق الرجل، لقول النبي ﷺ في الحديث الصحيح: ما أسفل من الكعبين من الإزار فهو في النار أخرجه البخاري في صحيحه، ولقول النبي ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب خرجه مسلم في الصحيح، وإذا كان مع الكبر؛ صار الإثم أكبر لقوله ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة. فمع الكبر يكون الإثم أكبر، ومن دون كبر، بل تساهل يكون آثمًا، ولا يجوز على الصحيح، ولكن لا يكون مثل من جره خيلاء، يكون إثمه أقل، والغالب أنه يجره خيلاء حتى ولو ما نوى الخيلاء، فالغالب أنه يجره لذلك، إذا تساهل به جره ذلك إلى التكبر والتعاظم، ثم هو أيضًا إسراف في الملابس، وتعريض لها للنجاسات، والأوساخ، كذلك لا يجوز مطلقًا. أما المرأة فلا حرج أن ترخي ثوبها شبرًا، أو ذراعًا؛ لأنها بهذا تستر قدميها. والصلاة صحيحة مع الإثم، هو آثم، لكن الصلاة صحيحة؛ لأن الرسول ﷺ ما أمر المسبل أن يعيد، بل الصلاة صحيحة، وهكذا كلما يتعلق بالمعاصي التي يفعلها الإنسان في ثوب، أو غيره، أن يكون هناك ثوبًا من حرام، أو مغصوبًا، أو فيه إسبال؛ فالصلاة صحيحة، لكن مع الإثم، أو الصلاة في أرض مغصوبة، هذا الصواب من أقوال العلماء، بعض أهل العلم يرى أن الصلاة غير صحيحة. المقدم: في الأرض المغصوبة خاصة، أو في كل هذا؟ الشيخ: في الكل: الثوب المغصوب، والمسبل، ولكن الصواب أنه لا تعاد الصلاة، الصلاة صحيحة، الصواب أنها صحيحة؛ لأن هذا النهي ليس خاصًا بالصلاة، بل هو عام ليس له أن يسبل لا في الصلاة، ولا في خارجها، وليس له أن يغصب لا في الصلاة، ولا في غيرها، وليس له أن يدخل الأرض المغصوبة، ولا يصلي فيها، ولا يجلس فيها، فالنهي عام، ما هو بخاص بالصلاة، والصلاة تبطل بالشيء الذي يخصها، مثل الثوب النجس يبطل الصلاة؛ لأنه خاص بالصلاة، مثل كشف العورة، وما أشبه ذلك، الشيء الخاص بالصلاة يبطلها إذا كشف عورته تعمدًا، أو صلى في ثوب نجس؛ لأن هذا يخص الصلاة يبطلها، مثل تكلم فيها، مثل انحرف عن القبلة، وما أشبهه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، هذا الحديث الذي تفضلتم بذكره يتضمن ما يتضمن من الوعيد الشديد، وهذا الوعيد قد لا يذكر في معاصٍ أكبر مما ذكر هنا، ما هو توجيه سماحتكم للمستمعين الكرام تجاه هذا الوعيد الشديد في هذا الحديث، وما ماثله في الأحاديث، أو الآيات؟ جزاكم الله خيرًا. الشيخ: لا شك أن هذا الوعيد يوجب النفرة من هذه المسائل، والحذر منها، ولعل الحكمة في ذلك -والله أعلم- أن الدوافع قوية، الدوافع للإسبال، والمن في العطية، والأيمان الكاذبة لأجل ... السلع، الدوافع قوية، فكان من حكمة الله أن جعل الوعيد الشديد حتى يردع عن هذه المعاصي، ويكون ذلك أقوى في الردع؛ لأن كثيرًا من الناس قد يحمله حب المال على الأيمان الكاذبة، وتنفيق السلعة بأيمان كاذبة، فمن رحمة الله أن جعل زجره الشديد عن ذلك؛ حتى لا يضر العالم بأيمانه الكاذبة. وكذلك الإنسان قد يكون عنده تساهل في المن بالعطية، يعطي ويمن على الناس، وهذا من قلة المروءة، ومن صغار النفس، فمن رحمة الله أن جعل الوعيد؛ حتى يحذر المؤمن من هذا الخلق الذميم، وهو كونه يمنُّ على من أعطى: فعلت بك، وأعطيتك، وأحسنت إليك، يمنُّ عليه، وكذلك الدوافع للإسبال كثيرة: للتكبر، والتساهل، ولهذا جاء الوعيد الشديد للتحذير من هذا الخلق الذميم، وهو الإسبال. نعم. المقدم: جزاكم الله خيرًا إذًا هذا الوعيد على ظاهره أو له وجهة أخرى؟ الشيخ: على ظاهره، لكن لا يلزم من ذلك الكفر، بل الوعيد، قد يعفو الله، ولا ينفذ الوعيد، نعم، مثلما توعد كثيرًا من العصاة: توعد القاتل بالنار، توعد الزاني، توعد السارق، ولكن قد يعفو سبحانه، نعم، وهذا ما لم يتب، ومن تاب تاب الله عليه. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15831/حكم-صلاة-المسبل-ازاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76711.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":17200,"question":"تقول السائلة: ما حكم الإسبال في الصلاة؟ حيث إنه يوجد كثير من الناس يسبلون، ويقولون: بأن الرسول ﷺ قد سبل في الصلاة، فما صحة هذا القول؟","title":"ما حكم الإسبال في الصلاة؟","answer":"الجواب: الإسبال إذا كان يعنى به إرخاء اليدين فهذا خلاف السنة، السنة أن يضع اليدين على صدره، هذا السنة، هذا المحفوظ عن النبي ﷺ يضع اليمنى على اليسرى على صدره، ولا يرخيها، يرسلها، يسمى إرسالًا ما يسمى إسبالًا، يسمى إرسالًا. أما الإسبال: فهو إرخاء الثياب تحت الكعبين، الملابس، والإزار، والبشت، هذا يسمى إسبالًا، ما يجوز إرخاء الملابس تحت الكعبين للرجل، أما المرأة؛ لا بأس، أما إسبال الثياب للرجل تحت الكعب؛ إزار، أو سراويل، أو قميص، أو بشت كل هذا لا يجوز. أما إرسال اليدين وهو يصلي هذا ما يسمى إسبالًا يسمى: إرسالًا، إرسال اليدين، والأفضل أن يضمهما، يضمهما على صدره وقت الصلاة، قبل الركوع وبعده، هذا هو السنة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16022/ما-حكم-الاسبال-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59028.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":17278,"question":"تقول: سمعت أن الصلاة لا تجوز، والمرأة ترتدي، أو تلبس خواتم، وسلاسلًا من النحاس، هل هذا القول صحيح، أو لا؟","title":"حكم صلاة المرأة وعليها خواتم وسلاسل من النحاس","answer":"الجواب: ليس بصحيح، لا حرج تصلي وعليها حلي من الذهب، أو الفضة، أو سلاسل من معدن، أو غيره، لا حرج في ذلك. نعم. المقدم: حتى ولو كان من النحاس المسؤول عنه؟ الشيخ: ولو من النحاس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16119/حكم-صلاة-المراة-وعليها-خواتم-وسلاسل-من-النحاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76811.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":17856,"question":"هذه الأخت السائلة (زينب . ح. ع) من الرومنة تقول سماحة الشيخ: قال الله تعالى في الحديث القدسي: يا ابن آدم لو بلغت ذنوبك عنان السماء، ثم استغفرتني؛ غفرت لك ولا أبالي هل معنى هذا هو الاستغفار أن أقول: أستغفر الله؟ أم أنه بشكل آخر؟","title":"معنى قوله \"ثم استغفرتني...\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه أجمعين.\nأما بعد:\nفالاستغفار المطلوب هو طلب المغفرة، يقول: اللهم اغفر لي، كما قال تعالى: وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ [البقرة:199] اللهم اغفر لي، أستغفر الله وأتوب إليه، لكن مع توبة، الكلام بغير التوبة ما ينفع، لابد توبة، لابد مع التوبة والندم والإقلاع، كما قال تعالى: وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ۝  أُوْلَئِكَ جَزَاؤُهُمْ مَغْفِرَةٌ مِنْ رَبِّهِمْ وَجَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ [آل عمران:135-136]. فالاستغفار يكون معه توبة، ومعه ندم، ومعه إقلاع؛ حتى ينفع ويحصل به المطلوب من محو الذنوب وغفرانها، أما قول باللسان مع الإقامة على المعاصي فلا ينفع، نسأل الله العافية.\nالمقدم: نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/16862/معنى-قوله-ثم-استغفرتني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59801.mp3","categories":["الأدعية والأذكار","شروح الحديث","مسائل متفرقة في الصلاة"]},{"id":18062,"question":"سؤاله الآخر يقول: كنا نصلي جماعة بالمزرعة، وكان أمام أنظارنا بالمزرعة ماكينة رفع مياه، ترفع المياه من البئر وتصبها بحوض بجوارنا، وفجأة وأثناء تأديتنا للصلاة رأينا دخانًا كثيفًا يخرج من جميع أجزاء تلك الماكينة، فإن تركناها فسوف يكون ضررًا جسيمًا، فهل يجوز لأحد منا قطع الصلاة ليطفئها؟ أم ماذا نفعل؟","title":"قطع الصلاة لدفع الضرر","answer":"الجواب: نعم، إذا وقع مثل هذا الحادث،، فإنه يقطع الصلاة أحد الجماعة لإزالة الخطر، ثم يعود فيصلي معهم ما بقي والحمد لله؛ لأن خطر هذا الدخان كبير، وقطع الصلاة لمصلحة مهمة أو لدرء خطر مثل إنقاذ حريق، أو إنقاذ غريق، أو دفع صائل، أو ما أشبه ذلك كل هذا لا بأس به، وهذا فيه في الحقيقة إنقاذ من حرق قد يهلك الماكينة، أو يتعدى ضرره إلى غير ذلك، فلا حرج في قطع الصلاة، ثم يعود فيبتدئ الصلاة من جديد مع الإمام فيما بقي، أو يقضيها بعدهم إذا سلموا قبله. نعم. المقدم: وإذا لم يكف واحد لإطفائها، فهل يجوز للجميع أن يقطعون الصلاة؟ الشيخ: لا بأس إذا دعت الحاجة إلى قطعهم الصلاة ليتعاونوا فلا بأس. المقدم: جميعًا؟ الشيخ: إذا كان الخطر عظيمًا فليقطعوها، ثم يزيلوا الخطر، ثم يرجعوا فيصلوا . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17097/قطع-الصلاة-لدفع-الضرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90105.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":18117,"question":"أيضًا أخونا يسأل بطريقته الخاصة ويقول ما معناه: هل لي أن أقطع الصلاة عندما أسمع عن حادث حريق، أو غرق أو ما أشبه ذلك؟","title":"قطع الصلاة في حالة وقوع حادث أو غرق","answer":"الجواب: نعم، إذا وجد حادثًا، غرقًا أو حرقًا؛ تخشى منه على أولادك أو على المسلمين تقطعها وتساهم في إنقاذ المسلمين أو إنقاذ أهلك، ثم تعود إلى الصلاة تصلي تبدأ فيها من جديد، أما غرق أو حرق لا يضرك ولا يضر المسلمين بل غرق أشياء ما لك فيها حيلة أو حرق أشياء من المتاع الذي لا حيلة فيه أو لا يضر تركه فاستمر في صلاتك. الحاصل إذا كان قطع الصلاة ينفع المسلمين أو ينفع أهلك فاقطعها لإنقاذ من أصيب بالغرق والحرق ثم تعود إلى الصلاة والحمد لله، نعم؛ لأن هذا يفوت الغرق والحرق يفوت الخطر والصلاة لا تفوت في الإمكان قضاؤها. نعم. المقدم: جزاكم الله خيرًا، هل يقاس على هذا أشياء أخرى سماحة الشيخ؟ الشيخ: نعم، مثل الأشياء التي يخشى منها، مثل إنسان رأى أعمى حول قليب أو حول حفرة يخشى يسقط فيها أو حوله ذئب أو أسد يخشى عليه منه، أو كلب عقور، فيقطع وينقذه ثم يعود إلى صلاته من أولها. المقدم: أخونا يذكر العقارب والحيات وما أشبه ذلك؟ الشيخ: وما أشبه ذلك إذا كان يخشى على أحد منها فلا بأس. أما إذا أمكنه قتلها وهو في الصلاة لأنها قريبة يمكن ضربها وهو في الصلاة فلا بأس، يضربها وهو في الصلاة. المقدم: ولو تقدم بخطوات أو انحرف يمينًا أو شمالًا؟ الشيخ: ولو تقدم بخطوات لكن إلى القبلة، يكون إلى القبلة. المقدم: إلى القبلة فقط. الشيخ: لقوله ﷺ: اقتلوا الأسودين في الصلاة: الحية والعقرب. المقدم: اللهم صل عليه، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17147/قطع-الصلاة-في-حالة-وقوع-حادث-او-غرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90502.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":18302,"question":"رسالة وصلت إلينا من أحد الإخوة المستمعين يقول: آدم سمسم فيما يبدو آدم سمسم برينو سوداني، أخونا رسالته أيضًا من الرسائل المطولة يقول فيها بعد التحية والاحترام: الصلاة واجبة على كل إنسان، وهذا أمر مفروغ منه إلا أنه اختلط لدينا الحابل بالنابل، هذا تعبيره شيخ عبد العزيز اختلط لدينا الحابل بالنابل في كيفية أدائها، وذلك من ناحية أقوال العلماء والمشايخ في كيفية الأداء، ولكي يكون الإنسان على علم بذلك أي الطريقة الصحيحة لأدائها كما يؤديها رسول الله ﷺ أرجو من سماحة الشيخ أن يتفضل بإيضاح ما يلي:أولاً: طريقة الرسول ﷺ في أداء الصلاة.- الأدعية التي يقولها الرسول ﷺ بعد إتمام الركعات في كل صلاة وقبل التشهد الأخير.- ما يقوله الرسول بعد التسليم وطريقة التسليم.- الدعاء للميت أي شيء يتعلق بكيفية الصلوات الخمس.- الاعتكاف ووقته وكيفيته.كما أرجو أن يكون ذلك واضحًا جليًا مختصرًا حتى أستطيع تسجيله وفهمه، جزاكم الله عنا خيرًا.","title":"ما صفة صلاة النبي ﷺ؟","answer":"الجواب: قد كتبنا في هذا رسائل فيما يتعلق بكيفية صلاة النبي ﷺ وفي عظم شأن الصلاة وأداء الصلاة في الجماعة أرجو أنها وصلت إليك أيها السائل! ولا مانع من إرسالها إليك. أما ما يتعلق بمعرفة ذلك من طريق هذا البرنامج فنوصيك أيها السائل! وسائر الإخوة بالعناية بسنة الرسول ﷺ ومراجعة الأحاديث الصحيحة الواردة في ذلك في الصحيحين وفي غيرهما وفي مثل المنتقى للمجد ابن تيمية وبلوغ المرام للحافظ ابن حجر رحمه الله ومثل عمدة الحديث للشيخ العلامة عبد الغني بن عبد الواحد بن علي بن سرور المقدسي رحمه الله، وهكذا الكتب التي جمعت في الحديث الشريف مثل رياض الصالحين ومثل جامع الأصول. والخلاصة أنه عليه الصلاة والسلام كان إذا قام إلى الصلاة كبر ورفع يديه حيال منكبيه وربما رفعهما إلى أذنيه عليه الصلاة والسلام قائلًا الله أكبر في أول الصلاة، في الظهر والعصر والمغرب والعشاء والفجر والنوافل يقول: الله أكبر هذا أول شيء للصلاة، وفي الحديث: تحريمها التكبير. ثم يأتي بالاستفتاح وهو دعوات يقولها قبل القراءة، وربما كانت أذكارًا فمن ذلك: سبحانك اللهم وبحمدك، وتبارك اسمك وتعالى جدك ولا إله غيرك، وهذا الاستفتاح كله ذكر. ومن ذلك: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم! نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم! اغسلني من خطاياي بالثلج والماء والبرد، وهذا أصح ما ورد في هذا الباب، وكله دعاء. ومنها: اللهم! رب جبريل و ميكائيل و إسرافيل فاطر السموات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم، وهذا من أجمع أنواع الاستفتاح. وهناك استفتاحات أخرى تجدها في محلها من كتب الحديث، ولكن هذه الثلاثة من أخصرها، ومن أثبتها. ثم بعد هذا تقول أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ثم تقرأ الفاتحة، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ [الفاتحة:2] إلى آخرها، والفاتحة هي أعظم سورة في القرآن الكريم، وهي ركن الصلاة، كما قال النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فيقرؤها الإمام ويقرؤها المنفرد ويقرؤها المأموم، لكنها في حق الإمام والمنفرد آكد وأوجب، واختلف العلماء في وجوبها على المأموم على أقوال: أحدها: أنها تجب على المأموم مطلقًا في السر والجهر. والثاني: أنها تجب عليه في السرية لا في الجهرية. والثالث: أنها لا تجب عليه لا في السرية ولا في الجهرية ويتحملها عنه الإمام. والأرجح أنها واجبة عليه في السر والجهر لعموم الأحاديث الدالة على ذلك، لكن إذا لم يأت إلا والإمام في الركوع فإنه تجزئه الركعة؛ لأنه لم يحضر وقت القيام فهو معذور لما صح عن رسول الله عليه الصلاة والسلام في صحيح البخاري رحمه الله أن أبا بكرة الثقفي جاء والنبي ﷺ في الركوع، فدخل فركع ثم دخل في الصف، ركع وحده ثم دخل في الصف، من الحرص، فلما فرغ النبي ﷺ قال له: زادك الله حرصًا ولا تعد يعني: لا تعد في الركوع دون الصف بل اصبر حتى تدخل في الصف، ولم يأمره بقضاء الركعة، فاحتج العلماء وهم الأئمة الأربعة على أنها تجزئه هذه الركعة؛ لأن الرسول ﷺ لم يأمره بالإعادة، فدل على سقوط الفاتحة عن من جاء والإمام راكع. وهكذا لو نسي المأموم أو جهل سقطت عنه فليس مثل الإمام والمنفرد، والفاتحة لها شأن عظيم كما تقدم فإنها أعظم سورة في كتاب الله . فالمشروع للمؤمن عند قراءتها أن يتدبرها وأن يتعقلها في الصلاة وخارجها، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: يقول الله : قسمت الصلاة بيني وبين عبدي نصفين -يعني: الفاتحة سماها صلاة-  فإذا قال: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ [الفاتحة:2]، قال الله: حمدني عبدي، وإذا قال: الرَّحْمَنِ الرَّحِيمِ [الفاتحة:3]، قال الله: أثنى علي عبدي، وإذا قال: مَالِكِ يَوْمِ الدِّينِ [الفاتحة:4]، قال الله: مجدني عبدي، فإذا قال: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] قال الله سبحانه: هذا بيني وبين عبدي ولعبدي ما سأل -يعني: إياك نعبد حق الله، وإياك نستعين حاجة العبد، يستعين بربه- فإذا قال: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:6-7] قال الله سبحانه: هذا لعبدي ولعبدي ما سأل يعني: هذا سؤال من عبدي يطلب الهداية وله ما سأل. وهذا وعد من الله أنه يعطيه الهداية وهذه أشرف مطلوب الهداية فينبغي لك -أيها القارئ.. أيها المؤمن.. أيها المؤمنة- ينبغي لكل منكما تدبر هذه السورة والعناية بها والخشوع فيها والإقبال عليها عند قراءتها، وهكذا عند قراءة جميع القرآن، كما قال الله سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]. وإذا قال: وَلا الضَّالِّينَ [الفاتحة:7] يقول: آمين، سواء كان في الصلاة أو في خارجها السنة أن يقول: آمين الإمام والمأموم والمنفرد في الصلاة وخارجها آمين، معناها: استجب يا ربنا. ثم بعد ذلك يقرأ الإمام والمنفرد سورة بعد الفاتحة أو آيات بعد الفاتحة كما كان النبي يفعل عليه الصلاة والسلام ويطيل في الفجر مثل سورة ق مثل والطور والنجم إذا هوى اقتربت الساعة، المسبحات وما أشبهها من السور، والظهر كذلك قريب من الفجر يطيل في الأولى والثانية وتكون الثانية أقصر من الأولى بعض الشيء، وتكون العصر أخف من الظهر، يقرأ سورة أو آيات بعد الفاتحة في الظهر والعصر في الأولى والثانية لكن تكون العصر أخف من الظهر، كما فعل النبي عليه الصلاة والسلام، وفي الثالثة والرابعة يقرأ الفاتحة فقط، الثالثة والرابعة في الظهر والعصر والعشاء الفاتحة فقط، وفي المغرب في الثالثة يقرأ الفاتحة فقط، وربما قرأ النبي ﷺ في الظهر زيادة على الفاتحة في الثالثة والرابعة فإذا قرأ بعض الأحيان في الثالثة والرابعة زيادة على الفاتحة بعض الآيات أو بعض السور القصيرة فهو حسن ومستحب في بعض الأحيان تأسيًا بالنبي عليه الصلاة والسلام، فقد ثبت عنه هذا في صحيح مسلم من حديث أبي سعيد الخدري . ثم يركع رافعًا يديه مثلما رفع عند الأولى يرفعهما حيال منكبيه أو حيال أذنيه تارة وتارة، تأسيًا برسول الله عليه الصلاة والسلام، ثم يسوي ظهره ورأسه في ركوعه، ويضع يديه على ركبتيه وفرد في الأصابع ويجافي عضديه عن جنبيه لا يلصقهما في جنبيه خاشعًا لربه مطمئنًا يقول: سبحان ربي العظيم، سبحان ربي العظيم، سبحان ربي العظيم، وإذا زاد على ذلك فقالها خمسًا أو ستًا أو سبعًا أو أكثر من ذلك فهو حسن لكن لا يطيل إذا كان إمامًا إطالة تشق على المأمومين. وقد ثبت عن أنس  ما يدل على أنه عليه الصلاة والسلام كان يطيل في الركوع والسجود وجاء عن غير أنس أيضًا، وجاء في بعض أحاديث أنس أنه كان يعد له في الركوع والسجود ما يقرب من عشر تسبيحات، فهذا يدل على أن السنة الطمأنينة وعدم العجلة في الركوع والسجود، فيقول: سبحان ربي العظيم سبحان ربي العظيم في الركوع سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، قالت عائشة رضي الله عنها: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده سبحانك اللهم ربنا وبحمدك اللهم اغفر لي متفق عليه. ثم يرفع من الركوع رافعًا يديه حيال منكبيه أو حيال أذنيه كما فعل عند الركوع وكما فعل عند الإحرام قائلًا: سمع الله لمن حمده إن كان إمامًا أو منفردًا، ثم بعد هذا يقول: ربنا ولك الحمد بعد انتصابه قائمًا يقول: ربنا ولك الحمد، أو ربنا لك الحمد بدون واو، أو اللهم ربنا لك الحمد، أو اللهم ربنا ولك الحمد كله جاء عن النبي عليه الصلاة والسلام. ثم يكمل حمدًا كثيرًا طيبًا مباركًا فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، هذا هو الأفضل، ولو اقتصر على ربنا ولك الحمد كفى، لكن كونه يكمل أولى وأفضل، ويطيل هذا الركن ولا يعجل؛ لأن الرسول كان يطيلها عليه الصلاة والسلام، حتى يقول القائل: قد نسي، وزاد في بعض الأحاديث -بعد وملء ما شئت من شيء بعد-: أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، كل هذا وهو واقف بعد الركوع. هذا هو الكمال إذا انتصب قائمًا الإمام والمنفرد بعد قوله: سمع الله لمن حمده، يقول: ربنا ولك الحمد، حمدًا كثيرًا طيبًا مباركًا فيه، ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم! لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، وإن اقتصر على البعض كفاه ذلك. أما المأموم فعند الرفع يقول: ربنا ولك الحمد المأموم عند رفعه من الركوع يقول: ربنا ولك الحمد، أو ربنا لك الحمد، أو اللهم! ربنا لك الحمد، أو اللهم! ربنا ولك الحمد يقول هذا تارة وهذا تارة، كله حسن؛ لأن الرسول عليه السلام قال: إذا قال الإمام سمع الله لمن حمده فقولوا: ربنا ولك الحمد، ولم يأمرهم أن يقولوا: سمع الله لمن حمده، بل يقولون: ربنا ولك الحمد.\nقال بعض أهل العلم إنه يقول: سمع الله لمن حمده ربنا ولك الحمد يجمع بينهما كالإمام، ولكن هذا قول ضعيف مرجوح، والصواب أن المشروع أن يقول: ربنا ولك الحمد، ولا يحتاج إلى أن يقول: سمع الله لمن حمده، بل هذا خاص بالإمام والمنفرد. ثم يكمل بعد انتصابه يقول: حمدًا كثيرًا طيبًا مباركًا فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، أهل الثناء والمجد، أحق ما قال العبد وكلنا لك عبد، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، وإن كبر إمامه قبل أن يكمل كبر مع إمامه وترك الباقي، إذا كبر الإمام قبل أن يكمل كبر وركع مع إمامه. نعم.","link":"https://binbaz.org.sa/fatwas/17362/ما-صفة-صلاة-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_858/nour_85803.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":18304,"question":"رسالة وصلت إلينا من أحد الإخوة المستمعين يقول: آدم سمسم فيما يبدو آدم سمسم برينو سوداني، أخونا رسالته أيضًا من الرسائل المطولة يقول فيها بعد التحية والاحترام: الصلاة واجبة على كل إنسان، وهذا أمر مفروغ منه إلا أنه اختلط لدينا الحابل بالنابل، هذا تعبيره شيخ عبد العزيز اختلط لدينا الحابل بالنابل في كيفية أدائها، وذلك من ناحية أقوال العلماء والمشايخ في كيفية الأداء، ولكي يكون الإنسان على علم بذلك أي الطريقة الصحيحة لأدائها كما يؤديها رسول الله ﷺ أرجو من سماحة الشيخ أن يتفضل بإيضاح ما يلي:أولاً: طريقة الرسول ﷺ في أداء الصلاة.- الأدعية التي يقولها الرسول ﷺ بعد إتمام الركعات في كل صلاة وقبل التشهد الأخير.- ما يقوله الرسول بعد التسليم وطريقة التسليم.- الدعاء للميت أي شيء يتعلق بكيفية الصلوات الخمس.- الاعتكاف ووقته وكيفيته.كما أرجو أن يكون ذلك واضحًا جليًا مختصرًا حتى أستطيع تسجيله وفهمه، جزاكم الله عنا خيرًا.","title":"ما صفة صلاة النبي ﷺ؟","answer":"الجواب: قد كتبنا في هذا رسائل فيما يتعلق بكيفية صلاة النبي ﷺ وفي عظم شأن الصلاة وأداء الصلاة في الجماعة أرجو أنها وصلت إليك أيها السائل! ولا مانع من إرسالها إليك. أما ما يتعلق بمعرفة ذلك من طريق هذا البرنامج فنوصيك أيها السائل! وسائر الإخوة بالعناية بسنة الرسول ﷺ ومراجعة الأحاديث الصحيحة الواردة في ذلك في الصحيحين وفي غيرهما وفي مثل المنتقى للمجد ابن تيمية وبلوغ المرام للحافظ ابن حجر رحمه الله ومثل عمدة الحديث للشيخ العلامة عبد الغني بن عبد الواحد بن علي بن سرور المقدسي رحمه الله، وهكذا الكتب التي جمعت في الحديث الشريف مثل رياض الصالحين ومثل جامع الأصول. والخلاصة أنه عليه الصلاة والسلام كان إذا قام إلى الصلاة كبر ورفع يديه حيال منكبيه وربما رفعهما إلى أذنيه عليه الصلاة والسلام قائلًا الله أكبر في أول الصلاة، في الظهر والعصر والمغرب والعشاء والفجر والنوافل يقول: الله أكبر هذا أول شيء للصلاة، وفي الحديث: تحريمها التكبير. ثم يأتي بالاستفتاح وهو دعوات يقولها قبل القراءة، وربما كانت أذكارًا فمن ذلك: سبحانك اللهم وبحمدك، وتبارك اسمك وتعالى جدك ولا إله غيرك، وهذا الاستفتاح كله ذكر. ومن ذلك: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم! نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم! اغسلني من خطاياي بالثلج والماء والبرد، وهذا أصح ما ورد في هذا الباب، وكله دعاء. ومنها: اللهم! رب جبريل و ميكائيل و إسرافيل فاطر السموات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم، وهذا من أجمع أنواع الاستفتاح. وهناك استفتاحات أخرى تجدها في محلها من كتب الحديث، ولكن هذه الثلاثة من أخصرها، ومن أثبتها. ثم بعد هذا تقول أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ثم تقرأ الفاتحة، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ [الفاتحة:2] إلى آخرها، والفاتحة هي أعظم سورة في القرآن الكريم، وهي ركن الصلاة، كما قال النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فيقرؤها الإمام ويقرؤها المنفرد ويقرؤها المأموم، لكنها في حق الإمام والمنفرد آكد وأوجب، واختلف العلماء في وجوبها على المأموم على أقوال: أحدها: أنها تجب على المأموم مطلقًا في السر والجهر. والثاني: أنها تجب عليه في السرية لا في الجهرية. والثالث: أنها لا تجب عليه لا في السرية ولا في الجهرية ويتحملها عنه الإمام. والأرجح أنها واجبة عليه في السر والجهر لعموم الأحاديث الدالة على ذلك، لكن إذا لم يأت إلا والإمام في الركوع فإنه تجزئه الركعة؛ لأنه لم يحضر وقت القيام فهو معذور لما صح عن رسول الله عليه الصلاة والسلام في صحيح البخاري رحمه الله أن أبا بكرة الثقفي جاء والنبي ﷺ في الركوع، فدخل فركع ثم دخل في الصف، ركع وحده ثم دخل في الصف، من الحرص، فلما فرغ النبي ﷺ قال له: زادك الله حرصًا ولا تعد يعني: لا تعد في الركوع دون الصف بل اصبر حتى تدخل في الصف، ولم يأمره بقضاء الركعة، فاحتج العلماء وهم الأئمة الأربعة على أنها تجزئه هذه الركعة؛ لأن الرسول ﷺ لم يأمره بالإعادة، فدل على سقوط الفاتحة عن من جاء والإمام راكع. وهكذا لو نسي المأموم أو جهل سقطت عنه فليس مثل الإمام والمنفرد، والفاتحة لها شأن عظيم كما تقدم فإنها أعظم سورة في كتاب الله . فالمشروع للمؤمن عند قراءتها أن يتدبرها وأن يتعقلها في الصلاة وخارجها، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: يقول الله : قسمت الصلاة بيني وبين عبدي نصفين -يعني: الفاتحة سماها صلاة-  فإذا قال: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ [الفاتحة:2]، قال الله: حمدني عبدي، وإذا قال: الرَّحْمَنِ الرَّحِيمِ [الفاتحة:3]، قال الله: أثنى علي عبدي، وإذا قال: مَالِكِ يَوْمِ الدِّينِ [الفاتحة:4]، قال الله: مجدني عبدي، فإذا قال: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] قال الله سبحانه: هذا بيني وبين عبدي ولعبدي ما سأل -يعني: إياك نعبد حق الله، وإياك نستعين حاجة العبد، يستعين بربه- فإذا قال: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:6-7] قال الله سبحانه: هذا لعبدي ولعبدي ما سأل يعني: هذا سؤال من عبدي يطلب الهداية وله ما سأل. وهذا وعد من الله أنه يعطيه الهداية وهذه أشرف مطلوب الهداية فينبغي لك -أيها القارئ.. أيها المؤمن.. أيها المؤمنة- ينبغي لكل منكما تدبر هذه السورة والعناية بها والخشوع فيها والإقبال عليها عند قراءتها، وهكذا عند قراءة جميع القرآن، كما قال الله سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]. وإذا قال: وَلا الضَّالِّينَ [الفاتحة:7] يقول: آمين، سواء كان في الصلاة أو في خارجها السنة أن يقول: آمين الإمام والمأموم والمنفرد في الصلاة وخارجها آمين، معناها: استجب يا ربنا. ثم بعد ذلك يقرأ الإمام والمنفرد سورة بعد الفاتحة أو آيات بعد الفاتحة كما كان النبي يفعل عليه الصلاة والسلام ويطيل في الفجر مثل سورة ق مثل والطور والنجم إذا هوى اقتربت الساعة، المسبحات وما أشبهها من السور، والظهر كذلك قريب من الفجر يطيل في الأولى والثانية وتكون الثانية أقصر من الأولى بعض الشيء، وتكون العصر أخف من الظهر، يقرأ سورة أو آيات بعد الفاتحة في الظهر والعصر في الأولى والثانية لكن تكون العصر أخف من الظهر، كما فعل النبي عليه الصلاة والسلام، وفي الثالثة والرابعة يقرأ الفاتحة فقط، الثالثة والرابعة في الظهر والعصر والعشاء الفاتحة فقط، وفي المغرب في الثالثة يقرأ الفاتحة فقط، وربما قرأ النبي ﷺ في الظهر زيادة على الفاتحة في الثالثة والرابعة فإذا قرأ بعض الأحيان في الثالثة والرابعة زيادة على الفاتحة بعض الآيات أو بعض السور القصيرة فهو حسن ومستحب في بعض الأحيان تأسيًا بالنبي عليه الصلاة والسلام، فقد ثبت عنه هذا في صحيح مسلم من حديث أبي سعيد الخدري . ثم يركع رافعًا يديه مثلما رفع عند الأولى يرفعهما حيال منكبيه أو حيال أذنيه تارة وتارة، تأسيًا برسول الله عليه الصلاة والسلام، ثم يسوي ظهره ورأسه في ركوعه، ويضع يديه على ركبتيه وفرد في الأصابع ويجافي عضديه عن جنبيه لا يلصقهما في جنبيه خاشعًا لربه مطمئنًا يقول: سبحان ربي العظيم، سبحان ربي العظيم، سبحان ربي العظيم، وإذا زاد على ذلك فقالها خمسًا أو ستًا أو سبعًا أو أكثر من ذلك فهو حسن لكن لا يطيل إذا كان إمامًا إطالة تشق على المأمومين. وقد ثبت عن أنس  ما يدل على أنه عليه الصلاة والسلام كان يطيل في الركوع والسجود وجاء عن غير أنس أيضًا، وجاء في بعض أحاديث أنس أنه كان يعد له في الركوع والسجود ما يقرب من عشر تسبيحات، فهذا يدل على أن السنة الطمأنينة وعدم العجلة في الركوع والسجود، فيقول: سبحان ربي العظيم سبحان ربي العظيم في الركوع سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، قالت عائشة رضي الله عنها: كان النبي ﷺ يكثر أن يقول في ركوعه وسجوده سبحانك اللهم ربنا وبحمدك اللهم اغفر لي متفق عليه. ثم يرفع من الركوع رافعًا يديه حيال منكبيه أو حيال أذنيه كما فعل عند الركوع وكما فعل عند الإحرام قائلًا: سمع الله لمن حمده إن كان إمامًا أو منفردًا، ثم بعد هذا يقول: ربنا ولك الحمد بعد انتصابه قائمًا يقول: ربنا ولك الحمد، أو ربنا لك الحمد بدون واو، أو اللهم ربنا لك الحمد، أو اللهم ربنا ولك الحمد كله جاء عن النبي عليه الصلاة والسلام. ثم يكمل حمدًا كثيرًا طيبًا مباركًا فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، هذا هو الأفضل، ولو اقتصر على ربنا ولك الحمد كفى، لكن كونه يكمل أولى وأفضل، ويطيل هذا الركن ولا يعجل؛ لأن الرسول كان يطيلها عليه الصلاة والسلام، حتى يقول القائل: قد نسي، وزاد في بعض الأحاديث -بعد وملء ما شئت من شيء بعد-: أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، اللهم لا مانع لما أعطيت، ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، كل هذا وهو واقف بعد الركوع. هذا هو الكمال إذا انتصب قائمًا الإمام والمنفرد بعد قوله: سمع الله لمن حمده، يقول: ربنا ولك الحمد، حمدًا كثيرًا طيبًا مباركًا فيه، ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، أهل الثناء والمجد، أحق ما قال العبد، وكلنا لك عبد، اللهم! لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، وإن اقتصر على البعض كفاه ذلك. أما المأموم فعند الرفع يقول: ربنا ولك الحمد المأموم عند رفعه من الركوع يقول: ربنا ولك الحمد، أو ربنا لك الحمد، أو اللهم! ربنا لك الحمد، أو اللهم! ربنا ولك الحمد يقول هذا تارة وهذا تارة، كله حسن؛ لأن الرسول عليه السلام قال: إذا قال الإمام سمع الله لمن حمده فقولوا: ربنا ولك الحمد، ولم يأمرهم أن يقولوا: سمع الله لمن حمده، بل يقولون: ربنا ولك الحمد.\nقال بعض أهل العلم إنه يقول: سمع الله لمن حمده ربنا ولك الحمد يجمع بينهما كالإمام، ولكن هذا قول ضعيف مرجوح، والصواب أن المشروع أن يقول: ربنا ولك الحمد، ولا يحتاج إلى أن يقول: سمع الله لمن حمده، بل هذا خاص بالإمام والمنفرد. ثم يكمل بعد انتصابه يقول: حمدًا كثيرًا طيبًا مباركًا فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، أهل الثناء والمجد، أحق ما قال العبد وكلنا لك عبد، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، وإن كبر إمامه قبل أن يكمل كبر مع إمامه وترك الباقي، إذا كبر الإمام قبل أن يكمل كبر وركع مع إمامه. نعم.","link":"https://binbaz.org.sa/fatwas/17362/ما-صفة-صلاة-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_858/nour_85803.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":18316,"question":"شيخ عبد العزيز نبدأ هذه الحلقة لو تكرمتم بالعودة إلى إجابة أخينا آدم سمسم برينو السوداني؛ حيث سأل عن الكيفية الصحيحة للصلاة، وقد شرعتم جزاكم الله خيرًا، وبينتم الوصف الذي يحسن بالمسلم أن يسير عليه، ووصلتم إلى القيام من الركوع، فحبذا لو تفضلتم، وأكملتم ما بدأتم جزاكم الله خيرًا.","title":"صفة صلاة النبي ﷺ بعد الرفع من الركوع","answer":"الجواب:\n\nبسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\n\nفقد سبق لنا أن تكلمنا على صفة صلاة النبي عليه الصلاة والسلام تحقيقًا لما سأل عنه السائل المذكور، وانتهينا إلى ما كان يفعله ﷺ بعد رفعه من الركوع، وما كان يقوله عليه الصلاة والسلام، وانتهينا إلى أن المأموم إذا رفع يقول: ربنا ولك الحمد ولا يزيد سمع الله لمن حمده، هذا هو المختار، وهذا هو الأرجح، ويكمل على الحمد، فيقول: حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد، أهل الثناء والمجد، أحق ما قال العبد -وكلنا لك عبد-: اللهم لا مانع لما أعطيت ولما معطي لما منعت ولا ينفع ذا الجد منك الجد، إن تيسر له ذلك، فإن كبر الإمام تابعه وترك البقية، لقول النبي ﷺ: وإذا ركع فاركعوا.\n\nثم بعد ذلك الإمام والمنفرد والمأموم إذا فرغوا من هذا القيام، ومن ذكر هذا القيام يخرون سجدًا، فيكبر كل منهم عند السجود، يقول: الله أكبر الإمام والمأموم والمنفرد عند السجود بعد القيام بعد الركوع، وذكر القيام الذي تقدم، بعد ذلك يخر الإمام ساجدًا، وهكذا المأموم وهكذا المنفرد، لكن المأموم يخر بعد إمامه فإذا انتهى إمامه وهو ساجد سجد بعده، قائلاً كل منهم: الله أكبر عند سجوده من دون رفع اليدين، ليس في هذا رفع يدين، بل يخر كل منهم ساجدًا من دون رفع اليدين، كما فعل عليه الصلاة والسلام.\n\nويقول في سجوده: سبحان ربي الأعلى... كما ثبت عنه عليه الصلاة والسلام، سبحان ربي الأعلى، سبحان ربي الأعلى، والواجب مرة واحدة، وهكذا في الركوع الواجب مرة، سبحان ربي العظيم، وإذا كرر ثلاثًا فهو أدنى الكمال ومستحب، وإن زاد خمسًا أو سبعًا أو عشرًا كله مستحب، والإمام يراعي عدم المشقة على الناس، والمأموم تبعًا لإمامه، والمنفرد لا حرج عليه في الزيادة التي لا تشق عليه ولا تسبب له نعاسًا أو أفكارًا لا تناسب.\n\nويستحب للإمام والمنفرد والمأموم أن يقولوا في السجود: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي كالركوع، لما ثبت عن عائشة رضي الله عنها أم المؤمنين، قالت: كان رسول الله ﷺ يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، ويكثر من الدعاء أيضًا في السجود يقول عليه الصلاة والسلام: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم، يعني: حري أن يستجاب لكم.\n\nويقول عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، فيشرع للمؤمن والمؤمنة في السجود الإكثار من الدعاء، سواء كان إمامًا أو مأمومًا أو منفردًا، يدعو بما تيسر، ومن دعاء النبي ﷺ في ذلك: اللهم اغفر لي ذنبي كله دقه وجله، وأوله وآخره وعلانيته وسره، هذا من دعائه عليه الصلاة والسلام: اللهم اغفر لي ذنبي كله دقه وجله وأوله وآخره، وعلانيته وسره.\n\nومن الدعاء الذي يحسن في هذا المقام، ما ثبت في الصحيحين عن الصديق  أن النبي ﷺ علمه أن يقول في صلاته: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم، هذا من أفضل الدعاء، في السجود بين السجدتين في آخر الصلاة، في غير الصلاة: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم.\n\nالصديق سأل النبي ﷺ قال: يا رسول الله: علمني دعاءً أدعو به في صلاتي؟ -وفي رواية-: وفي بيتي، قال: قل: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم، فإذا دعا بهذا في السجود أو بين السجدتين أو في آخر الصلاة فكله حسن.\n\nومن الدعاء أيضًا الحسن في هذا المقام: اللهم يا مقلب القلوب ثبت قلبي على دينك، ويا مصرف القلوب صرف قلبي على طاعتك، كان من دعاء النبي ﷺ في الجملة، كان هذا من دعائه المعروف -اللهم صل عليه وسلم-، وإذا دعا له الإنسان في السجود أو في آخر الصلاة، وهكذا في خارجها، فهو دعاء عظيم، والعبد في أشد الحاجة إليه: اللهم يا مقلب القلوب ثبت قلبي على دينك، ويا مصرف القلوب صرف قلبي على طاعتك، ويدعو الإنسان بما تيسر، سوى ما ذكر من الدعوات الطيبة حتى يرفع إمامه -إن كان مأموم- والإمام يدعو على وجه لا يشق على المأمومين والمنفرد كذلك.\n\nوالسنة للساجد: أن يجافي عضديه عن جنبيه، وبطنه عن فخذيه، وفخذيه عن ساقيه، يكون معتدلًا في السجود، ويرفع ذراعيه عن الأرض يعتمد على كفيه، يبسط كفه في الأرض ويمد أصابعه إلى جهة القبلة، ضامًا بعضها إلى بعض، رافعًا ذراعيه مفرجًا عضده عن جنبه، رافعًا بطنه عن فخذه، وفخذيه عن ساقيه، هكذا السنة، معتمدًا على بطون الأصابع -أصابع رجليه- مادًا للأصابع إلى جهة القبلة، هكذا كان يسجد عليه الصلاة والسلام.\n\nوالواجب عليه أن يسجد على الأعظم السبعة، يعني: على وجهه وكفيه وركبتيه وقدميه، هذا ركن لابد منه، لقول النبي ﷺ: أمرت أن أسجد على سبعة أعظم على الجبهة وأشار إلى أنفه، واليدين والركبتين وأطراف القدمين، فلابد من هذا في السجود للرجل والمرأة، للإمام والمأموم والمنفرد جميعًا.\n\nأما كيف ينحط إلى السجود، فقد جاء في هذا سنتان عن النبي ﷺ: إحداهما: أنه: ينحط على ركبتيه ثم يضع يديه ثم جبهته وأنفه في الأرض، هذا جاء من حديث وائل بن حجر عند أهل السنن بإسناد حسن، وله شاهد من حديث أنس، وله شاهد من حديث أبي هريرة في النوع الثاني.\n\nوالنوع الثاني: أنه ينحط على يديه أولًا، ثم ركبتيه بعد ذلك، وهذا جاء في حديث أبي هريرة عن النبي ﷺ أنه قال: لا يبرك أحدكم كما يبرك البعير وليضع يديه قبل ركبتيه، قال جماعة من العلماء ما معناه: أنه يبدأ بيديه؛ لأن البعير يبدأ بركبتيه وهي في يديه، هذه سنة وهذه سنة، ولا مشاحة في ذلك إن سجد على ركبتيه فحسن، وإن سجد على يديه فحسن، لمجيء الحديثين بذلك.\n\nلكن الأظهر والأقرب: أن الأفضل السجود على ركبتيه، ثم يديه، ثم جبهته وأنفه، هذا هو الأفضل والأقرب، وهو المخالف لهيئة البعير، وهو الموافق لأول الحديث: لا يبرك كما يبرك البعير؛ فإن بروك البعير يبرك على يديه، فإذا قدم المؤمن يديه فقد شابه البعير، فالأفضل أن يقدم ركبتيه التي في رجليه، ثم يديه، ثم جبهته وأنفه، هذا هو الأفضل وهذا أرجح السنتين.\n\nوأما قوله في حديث أبي هريرة: وليضع يديه قبل ركبتيه، هذا صريح، لكن قال بعض أهل العلم: لعله وقع فيه انقلاب، وأن الصواب: وليضع ركبتيه قبل يديه، فانقلب على بعض الرواة، وهو محتمل؛ لأن آخره، لا يوافق صدر الحديث العجز لا يوافق الصدر، فإن في الصدر لا يبرك كما يبرك البعير والبعير يبرك على يديه، وقوله: وليضع يديه قبل ركبتيه، ظاهره مخالفة صدر الحديث فيظهر من هذا أن الحديث فيه انقلاب، وهو أن الصواب: وليضع ركبتيه قبل يديه، فيكون بهذا موافقًا لحديث وائل، وينتهي الخلاف والإشكال.\n\nوبكل حال فالحمد لله الأمر واسع؛ إن سجد على ركبتيه كما دل عليه حديث وائل فحسن، وإن سجد على يديه فالأمر واسع في ذلك، والحمد لله.\n\nولا ينبغي في هذا المشاحة والمشاقة والنزاع، ولكن الأفضل والأرجح والأقرب: أنه يسجد على ركبتيه، ثم يديه، ثم جبهته، وأنفه، على حديث وائل ، والأقرب والأظهر أن حديث أبي هريرة لا يخالف حديث وائل، ولكنه يوافقه في المعنى، ولكن حصل في عجزه انقلاب، ويظهر أن الحديث: \"وليضع ركبتيه قبل يديه\"، وبهذا يجتمع الحديثان، وهذا أظهر قولي العلماء في الموضوع.\n\nثم يرفع من السجود جالسًا على رجله اليسرى ناصبًا اليمنى بين السجدتين، ويقول: رب اغفر لي، رب اغفر لي، اللهم اغفر لي، اللهم اغفر لي وارحمني واهدني واجبرني وارزقني يدعو بما تيسر ومن ذلك: رب اغفر لي، رب اغفر لي، اللهم اغفر لي وارحمني واهدني واجبرني وارزقني كما جاء في الأحاديث، يفرش اليسرى ويجلس عليها وينصب اليمنى، هذا هو الأفضل، وكيفما قعد أجزأ.\n\nوإن جلس على عقبيه فرش رجليه وجلس على عقبيه فلا بأس، كما جاء في حديث ابن عباس: وهذا إقعاء لا بأس بالجلوس عليه، إقعاء خاص، وهو الجلوس على العقبين، ولكن الأفضل وهو الذي جاء في الأحاديث الكثيرة: أنه يفرش اليسرى ويجلس عليها وينصب اليمنى، هذا هو الأفضل ويضع يديه على فخذيه وأطرافها على ركبتيه يقول: رب اغفر لي، رب اغفر لي، اللهم اغفر لي وارحمني واهدني واجبرني وارزقني كيفما دعا بالمغفرة جاز، اللهم اغفر لي ولوالدي، اللهم اغفر لي وللمسلمين، اللهم إني ظلمت نفسي ظلمًا كثيرًا.. إلخ.\n\nكان النبي ﷺ يطيل هذه الجلسة كما كان يطيل ما بعد الركوع عليه الصلاة والسلام، حتى يقول القائل: قد نسي، ولكن يلاحظ الإمام ألا يشق على الناس، لكن لا ينبغي أن يفعل مثل بعض الناس من جهة العجلة بعض الناس يعجل ولا يستقر، بعد الركوع، ولا بين السجدتين وهذا غلط.\n\nالمشروع أن يطمئن ولا يعجل بين السجدتين وبعد الركوع حال قيامه بعد الركوع اقتداءً بالمصطفى عليه الصلاة والسلام، وتأسيًا به عليه الصلاة والسلام، ثم يسجد الثانية قائلًا: الله أكبر، من دون رفع اليدين في السجود، فيسجد كما سجد في الأولى، ويضع يديه حيال منكبيه أو حيال أذنيه مادًا أصابعهما إلى القبلة ضامًا بعضها إلى بعض رافعًا بطنه عن فخذيه وفخذيه عن ساقيه، مجافيًا عضديه عن جنبيه كما تقدم، في هذه السجدة كالتي قبلها ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، ويدعو بما تيسر في سجوده كما تقدم.\n\nوناسب هنا: ربي الأعلى؛ لأنه حال خضوع وذل وتسفل حتى وضع وجهه على الأرض، فناسب أن يقول: سبحان ربي الأعلى، الذي فوق العرش  فوق جميع الخلق، وهو فوق العرش، وعلمه في كل مكان  وهو في جهة العلو عند أهل السنة والجماعة، فوق جميع الخلق، كما قال سبحانه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، والله  هو العلي العظيم، فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] يَا عِيسَى إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ [آل عمران:55]، بَلْ رَفَعَهُ اللَّهُ إِلَيْهِ [النساء:158].\n\nفي آيات كثيرة كلها دالة على علوه  فوق جميع الخلق فوق العرش، وأنه استوى عليه استواء يليق بجلاله وعظمته، لا يشابه خلقه في شيء من صفاته، والاستواء هو العلو والارتفاع، وعند أهل السنة أنه استواء يليق بالله لا يشابه الخلق في شيء من صفاته، كما قال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ  [الشورى:11]، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4].\n\nوفي الركوع يقول: سبحان ربي العظيم، لما كان الركوع حال ذل وخضوع، ناسب أن يقول: سبحان ربي العظيم، الذي هو أعظم شيء  وهو العزيز وهو الجبار وهو العظيم وهو القدوس، فناسب في الركوع أن يقول: سبحان ربي العظيم تنزيهًا لربه عن الذل وأنه العزيز الذي لا أعز منه  العظيم الذي لا أعظم منه.\n\nوفي السجود يقول: سبحان ربي الأعلى؛ لأنه العالي فوق جميع الخلق .\n\nثم يرفع إلى الركعة الثانية، ويفعل كما فعل في الأولى كما تقدم، لكن ليس فيها استفتاح، الاستفتاح في الأولى فقط، أما هذه يرفع ثم يقرأ الفاتحة، يسمي الله ويقرأ الفاتحة، وإن تعوذ فلا بأس، والاستعاذة في الأولى كافية، لكن إن عاد للاستعاذة فلا بأس، ثم يسمي ويقرأ الفاتحة، ثم يقرأ سورة أو آيات دون الأولى كما تقدم، وثم يركع كما ركع في الأول كما تقدم، ثم يجلس، ثم يسجد سجدتين كما تقدم.\n\nثم يجلس للتشهد الأول على رجله اليسرى ينصب اليمنى، مثل جلوسه بين السجدتين، ويقرأ التحيات، التحيات لله والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وأشهد أن محمدًا عبده ورسوله.\n\nوإن قال: أشهد أن لا إله إلا الله وحده لا شريك له، فلا بأس جاء هذا وهذا، جاء ذكر وحده لا شريك له، وجاء أحدها أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله.\n\nفإن شاء رفع وإن صلى على النبي ﷺ فهو أفضل، يصلي على النبي ﷺ ثم يرفع، يقوم للثالثة؛ لأن الأحاديث عامة في الصلاة على النبي ﷺ، وبعض أهل العلم قال: يكتفي بالشهادة ويقوم، ولكن الأفضل أن يصلي على النبي ﷺ فيقول: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وآل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وآل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد.\n\nثم يرفع قائلاً: الله أكبر، ويرفع يديه مثلما رفع عند الإحرام وعند الركوع، والرفع منه يرفع يديه قائلاً: الله أكبر إلى الثالثة، ثم بعد استتمامه قائمًا يقرأ الفاتحة وحدها ثم يركع كما فعل في السابق، ثم يسجد كما في السابق هكذا، وهكذا في الرابعة من الظهر والعصر والعشاء وفي الثالثة من المغرب، يقرأ الفاتحة ويركع كما تقدم، ويقول في الركوع كما تقدم، ويرفع كما تقدم، ويقول في الرفع ما تقدم، ويسجد في السجود كما تقدم، ويقول في السجود كما تقدم سواءً بسواء.\n\nلكن في الظهر والعصر والعشاء ركعتين بعد التشهد الأول، وفي المغرب ركعة واحدة، وفي الفجر الصلاة ركعتان فقط ليس فيها تشهد أول أو آخر، بل ليس فيها إلا تشهد واحد، الفجر والجمعة والعيد، والاستسقاء، كل منها ركعتان، ليس فيها إلا تشهد واحد يأتي بالتشهد ويصلي على النبي ﷺ ثم يدعو، وهكذا في التشهد الأخير في المغرب والعشاء والظهر والعصر، يأتي بالتحيات كما تقدم، ويصلي على النبي ﷺ كما تقدم ثم يدعو، يتعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات ومن فتنة المسيح الدجال كما جاء به الخبر عن النبي ﷺ أنه كان يفعل ذلك.\n\nوجاء عنه ﷺ أنه أمر بذلك أيضًا فيقول: أعوذ بالله من عذاب جهنم ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ، ويدعو بما أحب فيها: اللهم أعني على ذكرك وشكرك وحسن عبادتك، اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم مني أنت المقدم وأنت المؤخر لا إله إلا أنت اللهم أني أعوذ بك من البخل وأعوذ بك من الجبن وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر، كل هذا جاء عن النبي ﷺ في آخر الصلاة.\n\nوعلم النبي ﷺ معاذًا أن يقول: اللهم أعني على ذكرك وشكرك وحسن عبادتك قال: يا معاذ ! إني لأحبك، يقول له ﷺ: يا معاذ ! إني لأحبك، فلا تدعن أن تقولن دبر كل صلاة: اللهم أعني على ذكرك وشكرك وحسن عبادتك، فيستحب هذا الدعاء، هذه الأدعية في آخر الصلاة لكل مصلي مأموم أو إمام أو منفرد رجل أو امرأة، هذا مشروع.\n\nوالواجب قراءة التحيات مع الصلاة على النبي ﷺ هذا هو الواجب هذا الفرض هذا الركن، وما زاد فهو سنة ومستحب وبعض أهل العلم أوجب التعوذ بالله من أربع، لكن الذي عليه جمهور أهل العلم أنها سنة، ولكن ينبغي ألا يدعها، ينبغي للمسلم وللمسلمة ألا يدع هذه التعوذات الأربع: اللهم! إني أعوذ بك من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال؛ لأن المصطفى عليه الصلاة والسلام أمر بها، وكان يفعلها بنفسه عليه الصلاة والسلام، ويقول: صلوا كما رأيتموني أصلي، فالأولى بالمؤمن وبالمؤمنة ألا يدع كل منهما هذه الدعوات الطيبة، ويدعو معها بما تيسر من الدعوات، ويداه على فخذيه، وأطرافه على ركبتيه، ويشير بالسبابة في التشهد الأول والثاني يرفع السبابة ويقبض الجميع إشارة إلى التوحيد، يقبض الجميع ويرفع السبابة، إشارة للتوحيد، وإن حلق الإبهام مع الوسطى، وقبض الخنصر والبنصر ورفع السبابة كله حسن، هذا سنة وهذا سنة، وعند الدعاء يحرك سبابته قليلاً عند الدعاء، هذا جاءت به السنة عن النبي عليه الصلاة والسلام.\n\nثم يسلم عن يمينه وشماله تسليمتين، السلام عليكم ورحمة الله -هذا المحفوظ- السلام عليكم ورحمة الله، ورد في بعض الروايات: وبركاته، لكن اختلف العلماء في صحتها، فالأولى والأفضل أن يقتصر على السلام عليكم ورحمة الله فقط، هذا هو المحفوظ من حديث ابن مسعود ومن حديث جابر بن سمرة، وأحاديث أخرى فيها الدلالة على أن يقول: السلام عليكم ورحمة الله، السلام عليكم ورحمة الله، يمينًا وشمالًا، يلتفت يمينًا وشمالًا، ويبالغ في السلام، يبالغ في الالتفات هذا هو الأفضل.\n\nثم يقول بعد السلام: أستغفر الله، أستغفر الله، أستغفر الله، ثلاث مرات، ثم يقول: اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، ثبت هذا عن رسول الله عليه الصلاة والسلام أنه كان يقوله إذا سلم.\n\nثم ينصرف إلى الناس ويعطيهم وجهه إذا كان إمامًا، وإذا أعطاهم وجهه يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه له النعمة وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون: اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، يقوله الإمام والمأموم والمنفرد، ويستحب للجميع أيضًا أن يأتوا بالتسبيح والتحميد والتكبير ثلاثًا وثلاثين مرة (سبحان الله، والحمد لله، والله أكبر) ثلاثًا وثلاثين مرة، ويختم المائة بقوله: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.\n\nويستحب مع هذا أن يقرأ آية الكرسي أيضًا بعد كل صلاة، وقل هو الله أحد والمعوذتين: قل أعوذ برب الفلق وقل أعوذ برب الناس مرة واحدة، بعد الظهر والعصر والعشاء، وثلاث مرات بعد المغرب والفجر.\n\nوأسأل الله أن يوفق الجميع لما يرضيه، وأن يوفق جميع المسلمين للأخذ بالسنة، والاستقامة عليها والسير عليها، والتواصي بها إنه سميع قريب.\n\nالمقدم: اللهم آمين، جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17368/صفة-صلاة-النبي-ﷺ-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_859/nour_85901.mp3","categories":["مسائل متفرقة في الصلاة"]},{"id":18627,"question":"رسالة وصلت إلى البرنامج من الرياض، وباعثها مستمع رمز إلى اسمه بالحروف (ن. ج) يسأل سماحتكم فيقول: هل صلاة المرأة تختلف عن صلاة الرجل؛ وذلك من حيث المجافاة؟","title":"هل صلاة المرأة تختلف عن صلاة الرجل؟","answer":"الجواب: الصواب أنها كالرجل، بعض أهل العلم يفرق بينهما، والصواب: أنها كالرجل، تجلس على رجلها اليسرى تفترشها بين السجدتين، وفي التشهد الأول، وتورك في الأخير، هذا هو السنة؛ لأن الرسول -عليه الصلاة والسلام- قال: صلوا كما رأيتموني أصلي ولم يقل للنساء: افعلن كذا، وافعل كذا، أطلق. فالسنة التأسي به ﷺ في الصلاة للرجال والنساء جميعًا، وليس هناك دليل على الفرق، بل السنة أن تفعل كما يفعل الرجل، صلوا كما رأيتموني أصلي ترفع يديها عند الإحرام، وعند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول، تفترش بين السجدتين، في التشهد الأول، تتورك في التشهد الأخير مثل الرجل سواء هذا هو السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17736/هل-صلاة-المراة-تختلف-عن-صلاة-الرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73415.mp3","categories":["مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":18703,"question":"هذا السائل (أ. أ) يقول في سؤاله: عملية تطهير الطفل الذي تجرى للأطفال هل صحيح بأن الذي لا يجري هذه العملية وهي التطهير لا تصح صلاته ولا يكتمل إسلامه؟","title":"حكم صلاة غير المختون","answer":"الجواب: ليس بصحيح، لكنه واجب تطهير الصبي وهو الختان، الرسول ﷺ قال: الفطرة خمس: الختان، والاستحداد، وقص الشارب، وقلم الظفر، ونتف الآباط وذهب جمع من أهل العلم إلى وجوب الختان؛ وذلك بقطع القلفة التي في طرف الذكر؛ لأنه قد يكون بعدها البول يتحجر فيها البول والوسخ. فالواجب قطعها قبل البلوغ في حال الصغر هذا الختان، وهو سنة بلا ريب، وذهب جمع من أهل العلم إلى وجوب ذلك، وأن الواجب قطع هذه القلفة حتى يبرز طرف الذكر، وحتى يسلم من وجود أشياء في هذه القلفة من الأوساخ والنجاسات، لكن صلاته صحيحة، لو بلغ ولم يختن صلاته صحيحة، وصومه صحيح، وقصاراها أنه أخطأ، وأنه غلط، وأنه عصى، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17824/حكم-صلاة-غير-المختون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78814.mp3","categories":["مسائل متفرقة في الصلاة","سنن الفطرة"]},{"id":19545,"question":"مستمع كتب في أعلى رسالته يقول: أرجو عدم ذكر اسمي، يسأل ويقول: إنني شاب طائع لله ورسوله بكل شيء، وأحافظ على الصلوات ولله الحمد، لكن يكون بعض الثياب التي ألبسها طويلة تحت الكعبين، فهل أكون من الذين لا ينظر الله إليهم ومن أهل النار؛ لحديث الرسول ﷺ: ما أسفل الكعبين ففي النار وهل لا يقبل الله الصلوات التي يصلي بها الإنسان وثوبه طويل؛ لأنني سمعت حديثًا عن الرسول ﷺ حيث قال: لا يقبل الله صلاة رجل مسبل إزاره أفيدونا جزاكم الله خيرًا، وأرجو أن يكون بتفصيل واضح؟","title":"التحذير من الإسبال وحكم صلاة المسبل","answer":"الجواب: الإسبال من المحرمات ومن المنكرات وهو نزول الملابس عن الكعبين يقال له: إسبال، كالبشت والقميص والإزار والسراويل كل هذا لا يجوز أن ينزل عن الكعبين للحديث الذي ذكرت وهو قول النبي ﷺ: ما أسفل من الكعبين من الإزار فهو في النار وإذا كان عن تكبر وعن خيلاء صار أشد في الإثم وأعظم، وقال عليه الصلاة والسلام: ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب رواه مسلم في صحيحه. فالواجب التحفظ من ذلك، وأن تكون الملابس حدها الكعب لا تنزل، وأن تحذر من الكبر والخيلاء أيضًا في جميع أحوالك وفي ملابسك. أما الحديث الذي ذكرته في عدم قبول الصلاة فهو حديث فيه ضعف، وإن صححه النووي أو حسنه فهو حديث ضعيف؛ لأن في إسناده مدلسًا وقد عنعن وفي إسناده من هو مجهول. فالحاصل أن الوعيد بعدم قبول الصلاة لو صح فهو دليل على شدة التحريم، وأنه ينبغي للمؤمن أن يحذر الإسبال وهو من باب الوعيد، والوعيد قد يعفو الله عن صاحبه، وقد ينفذ عليه وعيده، فالمسلم المصلي على خطر إذا خالف الأوامر ووقع في النواهي، فالواجب عليه أن لا يرتكب المحظور وأن لا يترك المأمور. وقد روي عنه ﷺ: أنه أمر المسبل أن يتوضأ، أن يعيد الوضوء، ولكن لم يأمره أن يعيد الصلاة، وهذا لو صح لكان من باب التحذير ومن باب الترهيب وفيه العلة التي سمعت. فالصواب أن صلاته صحيحة، وأنه أخطأ في إسباله، ولكن لا تلزمه الإعادة إنما هو صحيح مثل بقية المعاصي، لو صلى وفي ثوبه درهم من حرام، أو في ثوب مغصوب أو في أرض مغصوبة، فالصواب أن صلاته صحيحة؛ لأن الإثم يتعلق بالغصب لا بالصلاة فهو أمر منهي عنه مطلقًا في الصلاة وخارجها، فإذا صلى في ثوب مغصوب أو أرض مغصوبة، أو ثوب فيه درهم حرام صحت الصلاة مع الإثم فهو آثم لأجل تعاطيه ما حرم الله عليه من الغصب والكسب الحرام ولكن الصلاة صحيحة؛ لأن هذا لا يتعلق بالصلاة يتعلق بموضوع تعاطيه ما حرم الله عليه من الغصب والكسب الحرام. وهكذا لو صلى في ثوب فيه نجاسة ناسيًا، ناسيًا لها أو جاهلًا بها حتى فرغ من صلاته صحت صلاته، كما ثبت في حديث أبي سعيد عند أحمد وأبي داود بإسناد صحيح: «أنه صلى عليه الصلاة والسلام ذات يوم ثم خلع نعليه وهو في الصلاة، فخلع الناس نعالهم، فلما سلم سألهم عن ذلك، فقالوا: رأيناك خلعت نعليك فخلعنا نعالنا، فقال: إن جبرائيل أتاني فأخبرني أن بهما قذرًا فخلعتهما، فإذا أتى أحدكم المسجد فلينظر في نعليه، -أو قال: فليقلب نعليه- فإن رأى فيهما قذرًا فليمسحه ثم يصلي فيهما. ولم يعد الصلاة عليه الصلاة والسلام، ولم يستأنفها بل استمر فيها، فدل ذلك على أن من وجد في ثوبه شيئًا ولم يعلم إلا بعد الصلاة فصلاته صحيحة، وإن علم في أثنائها وخلعه فصلاته صحيحة كما خلع النبي ﷺ نعليه.\nفالمؤمن يتحفظ ويحرص على أن يكون سليم الثياب من النجاسة سليم البقعة، سليم البدن، ولكن متى نسي شيئًا من النجاسة حتى فرغ من صلاته أو جهل ذلك فصلاته صحيحة، بخلاف الحدث، لو صلى محدثًا فإنه يعيد، لو صلى يحسب أنه على وضوء ثم تبين أنه على غير وضوء فإنه تلزمه الإعادة. وهكذا لو صلى جُنب يحسب أنه مغتسل ثم بان له أنه لم يغتسل أعاد؛ لأن الطهارة لابد منها شرط في الصلاة، الطهارة من الأحداث شرط في الصلاة، ولهذا قال عليه الصلاة والسلام: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ وقال عليه الصلاة والسلام: لا تقبل صلاة بغير طهور بخلاف النجاسة في الثوب والبدن والبقعة فإنها أسهل إذا نسيها أو جهلها مثل الحديث الذي عرفت حديث أبي سعيد في قصة نعلي النبي ﷺ وما حصل فيهما من القذر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18796/التحذير-من-الاسبال-وحكم-صلاة-المسبل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_940/nour_94007.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":19641,"question":"يقول هذا السائل: الأدعية والتسابيح التي حث عليها الرسول ﷺ بعد دبر كل صلاة، هل يجوز أن تكون بعد صلاة السنة؟","title":"حكم تأخير أذكار الانصراف من الفريضة بعد السنة","answer":"الجواب: لا، السنة بعد الفريضة، الأذكار التي أرشد إليها النبي ﷺ تكون بعد الفريضة. نعم. خاصة. نعم.","link":"https://binbaz.org.sa/fatwas/18920/حكم-تاخير-اذكار-الانصراف-من-الفريضة-بعد-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94930.mp3","categories":["الأدعية والأذكار","مسائل متفرقة في الصلاة"]},{"id":19686,"question":"يقول هذا السائل الذي رمز لاسمه بـ (م. ع): سماحة المفتي حفظكم الله، ورد في كتاب الأذكار للنووي: بأن الأذكار المشروعة في الصلاة وغيرها واجبة كانت أو مستحبة لا يحسب شيء منها ولا يعتد به حتى يتلفظ به؛ بحيث يسمع نفسه إذا كان صحيح السمع لا عارض له، و هل هذا وارد؟","title":"حكم إسماع المصلي نفسه بأذكار الصلاة","answer":"الجواب: هذا هو السنة أن يسمع نفسه في أذكار الركوع والسجود، وبين السجدتين، وفي التحيات، ما يصير قارئًا إلا إذا أسمع نفسه إذا تلفظ، نعم ما يصير قارئًا ولا يصير ذاكرًا إلا بذلك، لكن الذكر بالقلب نوع ثالث، الذكر بالقلب والذكر باللسان والذكر بالعمل، فالذكر بالقلب نوع ثالث، يكون على باله محبة الله وتعظيم الله وشكر الله وذكره، لكن لا يكون مؤديًا للواجب في الصلاة إلا إذا قال: سبحان ربي العظيم في الركوع، سبحان ربي الأعلى في السجود، قرأ التحيات، قرأ الفاتحة، أما كونه ينويها بقلبه ما ينفع، أو يقرأها بقلبه ما يكفي. نعم.","link":"https://binbaz.org.sa/fatwas/18979/حكم-اسماع-المصلي-نفسه-باذكار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95040.mp3","categories":["الأدعية والأذكار","مسائل متفرقة في الصلاة"]},{"id":19688,"question":"سماحة الشيخ يقول هذا السائل حفظكم الله: ما المراد بقوله ﷺ: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب هل المراد باعد بيني وبينها فلا أقترفها أم المراد الذنوب؟","title":"ما معنى: «اللهم باعد بيني وبين خطاياي»؟","answer":"الجواب: يتضمن التوبة منها يعني: وفقني للتوبة منها النصوح التي تبعدها عني كما باعدت بين المشرق .. اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس المراد طلب العافية منها والبعد منها والسلامة منها. نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18981/ما-معنى-اللهم-باعد-بيني-وبين-خطاياي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95042.mp3","categories":["الأدعية والأذكار","شروح الحديث","مسائل متفرقة في الصلاة"]}]
